{"command":"cd /workspace && cat > src/json.rs <<'EOF'
// JSON value model and parser mimicking serde_json semantics.
use std::collections::BTreeMap;
use std::sync::OnceLock;

#[derive(Clone, Debug, PartialEq)]
pub enum Number {
    U(u64),
    I(i64),
    F(f64),
}

pub type Map = BTreeMap<String, Value>;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(Number),
    String(String),
    Array(Vec<Value>),
    Object(Map),
}

impl Number {
    pub fn as_u64(&self) -> Option<u64> {
        match *self {
            Number::U(u) => Some(u),
            Number::I(i) => {
                if i >= 0 {
                    Some(i as u64)
                } else {
                    None
                }
            }
            Number::F(_) => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match *self {
            Number::U(u) => {
                if u <= i64::MAX as u64 {
                    Some(u as i64)
                } else {
                    None
                }
            }
            Number::I(i) => Some(i),
            Number::F(_) => None,
        }
    }
    pub fn as_f64(&self) -> f64 {
        match *self {
            Number::U(u) => u as f64,
            Number::I(i) => i as f64,
            Number::F(f) => f,
        }
    }
    pub fn to_string(&self) -> String {
        match *self {
            Number::U(u) => u.to_string(),
            Number::I(i) => i.to_string(),
            Number::F(f) => fmt_float(f),
        }
    }
}

/// Shortest round-trip float formatting in the style used by serde_json.
pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        return "NaN".to_string();
    }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    if f == 0.0 {
        return if f.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let neg = f < 0.0;
    let s = format!("{:e}", f.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let e: i32 = exp.parse().unwrap();
    let n = digits.len() as i32;
    let kk = e + 1;
    let k = kk - n;
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in 0..k {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if n > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        let x = kk - 1;
        if x >= 0 {
            out.push('+');
        }
        out.push_str(&x.to_string());
    }
    out
}

fn pow10() -> &'static [f64; 309] {
    static P: OnceLock<[f64; 309]> = OnceLock::new();
    P.get_or_init(|| {
        let mut a = [0f64; 309];
        for (i, v) in a.iter_mut().enumerate() {
            *v = format!("1e{}", i).parse::<f64>().unwrap();
        }
        a
    })
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
    depth: usize,
}

type R<T> = Result<T, ()>;

pub fn parse(s: &str) -> Result<Value, ()> {
    let mut p = Parser { s: s.as_bytes(), i: 0, depth: 0 };
    p.ws();
    let v = p.value()?;
    p.ws();
    if p.i != p.s.len() {
        return Err(());
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\n' || c == b'\t' || c == b'\r' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn expect_lit(&mut self, lit: &[u8]) -> R<()> {
        if self.s[self.i..].starts_with(lit) {
            self.i += lit.len();
            Ok(())
        } else {
            Err(())
        }
    }
    fn value(&mut self) -> R<Value> {
        match self.peek() {
            None => Err(()),
            Some(b'n') => {
                self.expect_lit(b"null")?;
                Ok(Value::Null)
            }
            Some(b't') => {
                self.expect_lit(b"true")?;
                Ok(Value::Bool(true))
            }
            Some(b'f') => {
                self.expect_lit(b"false")?;
                Ok(Value::Bool(false))
            }
            Some(b'"') => {
                self.i += 1;
                Ok(Value::String(self.string()?))
            }
            Some(b'-') => {
                self.i += 1;
                self.number(false)
            }
            Some(b'0'..=b'9') => self.number(true),
            Some(b'[') => {
                self.depth += 1;
                if self.depth > 128 {
                    return Err(());
                }
                self.i += 1;
                let mut arr = Vec::new();
                self.ws();
                if self.peek() == Some(b']') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Array(arr));
                }
                loop {
                    self.ws();
                    arr.push(self.value()?);
                    self.ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                        }
                        Some(b']') => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err(()),
                    }
                }
                self.depth -= 1;
                Ok(Value::Array(arr))
            }
            Some(b'{') => {
                self.depth += 1;
                if self.depth > 128 {
                    return Err(());
                }
                self.i += 1;
                let mut map = Map::new();
                self.ws();
                if self.peek() == Some(b'}') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Object(map));
                }
                loop {
                    self.ws();
                    if self.peek() != Some(b'"') {
                        return Err(());
                    }
                    self.i += 1;
                    let k = self.string()?;
                    self.ws();
                    if self.peek() != Some(b':') {
                        return Err(());
                    }
                    self.i += 1;
                    self.ws();
                    let v = self.value()?;
                    map.insert(k, v);
                    self.ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                        }
                        Some(b'}') => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err(()),
                    }
                }
                self.depth -= 1;
                Ok(Value::Object(map))
            }
            _ => Err(()),
        }
    }

    fn hex4(&mut self) -> R<u16> {
        if self.i + 4 > self.s.len() {
            return Err(());
        }
        let mut v: u16 = 0;
        for _ in 0..4 {
            let c = self.s[self.i];
            let d = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => return Err(()),
            };
            v = v * 16 + d as u16;
            self.i += 1;
        }
        Ok(v)
    }

    fn string(&mut self) -> R<String> {
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = match self.peek() {
                None => return Err(()),
                Some(c) => c,
            };
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.peek().ok_or(())?;
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let n = self.hex4()?;
                            let ch: u32;
                            if (0xD800..0xDC00).contains(&n) {
                                // leading surrogate; need trailing
                                if self.peek() != Some(b'\\') {
                                    return Err(());
                                }
                                self.i += 1;
                                if self.peek() != Some(b'u') {
                                    return Err(());
                                }
                                self.i += 1;
                                let n2 = self.hex4()?;
                                if !(0xDC00..0xE000).contains(&n2) {
                                    return Err(());
                                }
                                ch = (((n as u32 - 0xD800) << 10) | (n2 as u32 - 0xDC00)) + 0x10000;
                            } else if (0xDC00..0xE000).contains(&n) {
                                return Err(());
                            } else {
                                ch = n as u32;
                            }
                            let chr = char::from_u32(ch).ok_or(())?;
                            let mut buf = [0u8; 4];
                            out.extend_from_slice(chr.encode_utf8(&mut buf).as_bytes());
                        }
                        _ => return Err(()),
                    }
                }
                0..=0x1f => return Err(()),
                _ => out.push(c),
            }
        }
        String::from_utf8(out).map_err(|_| ())
    }

    fn number(&mut self, positive: bool) -> R<Value> {
        let c = self.peek().ok_or(())?;
        self.i += 1;
        let f = match c {
            b'0' => {
                if let Some(b'0'..=b'9') = self.peek() {
                    return Err(());
                }
                return self.parse_number(positive, 0);
            }
            b'1'..=b'9' => {
                let mut sig = (c - b'0') as u64;
                loop {
                    match self.peek() {
                        Some(c @ b'0'..=b'9') => {
                            let d = (c - b'0') as u64;
                            if sig >= u64::MAX / 10 && (sig > u64::MAX / 10 || d > u64::MAX % 10) {
                                let f = self.parse_long_integer(positive, sig)?;
                                break f;
                            }
                            self.i += 1;
                            sig = sig * 10 + d;
                        }
                        _ => return self.parse_number(positive, sig),
                    }
                }
            }
            _ => return Err(()),
        };
        Ok(Value::Number(Number::F(f)))
    }

    fn parse_number(&mut self, positive: bool, sig: u64) -> R<Value> {
        match self.peek() {
            Some(b'.') => Ok(Value::Number(Number::F(self.parse_decimal(positive, sig, 0)?))),
            Some(b'e') | Some(b'E') => Ok(Value::Number(Number::F(self.parse_exponent(positive, sig, 0)?))),
            _ => {
                if positive {
                    Ok(Value::Number(Number::U(sig)))
                } else {
                    let neg = (sig as i64).wrapping_neg();
                    if neg >= 0 {
                        Ok(Value::Number(Number::F(-(sig as f64))))
                    } else {
                        Ok(Value::Number(Number::I(neg)))
                    }
                }
            }
        }
    }

    fn parse_decimal(&mut self, positive: bool, mut sig: u64, exp_before: i32) -> R<f64> {
        self.i += 1; // '.'
        let mut exp_after: i32 = 0;
        while let Some(c @ b'0'..=b'9') = self.peek() {
            let d = (c - b'0') as u64;
            if sig >= u64::MAX / 10 && (sig > u64::MAX / 10 || d > u64::MAX % 10) {
                let exponent = exp_before + exp_after;
                return self.parse_decimal_overflow(positive, sig, exponent);
            }
            self.i += 1;
            sig = sig * 10 + d;
            exp_after -= 1;
        }
        if exp_after == 0 {
            return Err(());
        }
        let exponent = exp_before + exp_after;
        match self.peek() {
            Some(b'e') | Some(b'E') => self.parse_exponent(positive, sig, exponent),
            _ => self.f64_from_parts(positive, sig, exponent),
        }
    }

    fn parse_exponent(&mut self, positive: bool, sig: u64, starting_exp: i32) -> R<f64> {
        self.i += 1; // e
        let positive_exp = match self.peek() {
            Some(b'+') => {
                self.i += 1;
                true
            }
            Some(b'-') => {
                self.i += 1;
                false
            }
            _ => true,
        };
        let c = self.peek().ok_or(())?;
        self.i += 1;
        let mut exp: i32 = match c {
            b'0'..=b'9' => (c - b'0') as i32,
            _ => return Err(()),
        };
        while let Some(c @ b'0'..=b'9') = self.peek() {
            self.i += 1;
            let d = (c - b'0') as i32;
            if exp >= i32::MAX / 10 && (exp > i32::MAX / 10 || d > i32::MAX % 10) {
                let zero_sig = sig == 0;
                return self.parse_exponent_overflow(positive, zero_sig, positive_exp);
            }
            exp = exp * 10 + d;
        }
        let final_exp = if positive_exp { starting_exp.saturating_add(exp) } else { starting_exp.saturating_sub(exp) };
        self.f64_from_parts(positive, sig, final_exp)
    }

    fn parse_exponent_overflow(&mut self, positive: bool, zero_sig: bool, positive_exp: bool) -> R<f64> {
        if !zero_sig && positive_exp {
            return Err(());
        }
        while let Some(b'0'..=b'9') = self.peek() {
            self.i += 1;
        }
        Ok(if positive { 0.0 } else { -0.0 })
    }

    fn parse_long_integer(&mut self, positive: bool, sig: u64) -> R<f64> {
        let mut exponent: i32 = 0;
        loop {
            match self.peek() {
                Some(b'0'..=b'9') => {
                    self.i += 1;
                    exponent += 1;
                }
                Some(b'.') => return self.parse_decimal(positive, sig, exponent),
                Some(b'e') | Some(b'E') => return self.parse_exponent(positive, sig, exponent),
                _ => return self.f64_from_parts(positive, sig, exponent),
