            Some(b'e') | Some(b'E') => self.parse_exponent(positive, sig, exponent),
            _ => self.f64_from_parts(positive, sig, exponent),
        }
    }

    fn f64_from_parts(&mut self, positive: bool, sig: u64, mut exponent: i32) -> R<f64> {
        let mut f = sig as f64;
        let p10 = pow10();
        loop {
            match p10.get(exponent.wrapping_abs() as usize) {
                Some(&pow) => {
