// JSON value model and parser mimicking serde_json semantics.
use std::collections::BTreeMap;
use std::sync::OnceLock;

#[derive(Clone, Debug, PartialEq)]
pub enum Number {
    U(u64),
    I(i64),
    F(f64),
}

pub type Map = BTreeMap<String, Value>;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(Number),
    String(String),
    Array(Vec<Value>),
    Object(Map),
}

impl Number {
    pub fn as_u64(&self) -> Option<u64> {
        match *self {
            Number::U(u) => Some(u),
            Number::I(i) => {
                if i >= 0 {
                    Some(i as u64)
                } else {
                    None
                }
            }
            Number::F(_) => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match *self {
            Number::U(u) => {
                if u <= i64::MAX as u64 {
                    Some(u as i64)
                } else {
                    None
                }
            }
            Number::I(i) => Some(i),
            Number::F(_) => None,
        }
    }
    pub fn as_f64(&self) -> f64 {
        match *self {
            Number::U(u) => u as f64,
            Number::I(i) => i as f64,
            Number::F(f) => f,
        }
    }
    pub fn to_string(&self) -> String {
        match *self {
            Number::U(u) => u.to_string(),
            Number::I(i) => i.to_string(),
            Number::F(f) => fmt_float(f),
        }
    }
}

/// Shortest round-trip float formatting in the style used by serde_json.
pub fn fmt_float(f: f64) -> String {
    if f.is_nan() {
        return "NaN".to_string();
    }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    if f == 0.0 {
        return if f.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let neg = f < 0.0;
    let s = format!("{:e}", f.abs());
    let (mant, exp) = s.split_once('e').unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let e: i32 = exp.parse().unwrap();
    let n = digits.len() as i32;
    let kk = e + 1;
    let k = kk - n;
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in 0..k {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if n > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        let x = kk - 1;
        if x >= 0 {
            out.push('+');
        }
        out.push_str(&x.to_string());
    }
    out
}

fn pow10() -> &'static [f64; 309] {
    static P: OnceLock<[f64; 309]> = OnceLock::new();
    P.get_or_init(|| {
        let mut a = [0f64; 309];
        for (i, v) in a.iter_mut().enumerate() {
            *v = format!("1e{}", i).parse::<f64>().unwrap();
        }
        a
    })
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
    depth: usize,
}

type R<T> = Result<T, ()>;

pub fn parse(s: &str) -> Result<Value, ()> {
    let mut p = Parser { s: s.as_bytes(), i: 0, depth: 0 };
    p.ws();
    let v = p.value()?;
    p.ws();
    if p.i != p.s.len() {
        return Err(());
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\n' || c == b'\t' || c == b'\r' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn expect_lit(&mut self, lit: &[u8]) -> R<()> {
        if self.s[self.i..].starts_with(lit) {
            self.i += lit.len();
            Ok(())
        } else {
            Err(())
        }
    }
    fn value(&mut self) -> R<Value> {
        match self.peek() {
            None => Err(()),
            Some(b'n') => {
                self.expect_lit(b"null")?;
                Ok(Value::Null)
            }
            Some(b't') => {
                self.expect_lit(b"true")?;
                Ok(Value::Bool(true))
            }
            Some(b'f') => {
                self.expect_lit(b"false")?;
                Ok(Value::Bool(false))
            }
            Some(b'"') => {
                self.i += 1;
                Ok(Value::String(self.string()?))
            }
            Some(b'-') => {
                self.i += 1;
                self.number(false)
            }
            Some(b'0'..=b'9') => self.number(true),
            Some(b'[') => {
                self.depth += 1;
                if self.depth > 128 {
                    return Err(());
                }
                self.i += 1;
                let mut arr = Vec::new();
                self.ws();
                if self.peek() == Some(b']') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Array(arr));
                }
                loop {
                    self.ws();
                    arr.push(self.value()?);
                    self.ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                        }
                        Some(b']') => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err(()),
                    }
                }
                self.depth -= 1;
                Ok(Value::Array(arr))
            }
            Some(b'{') => {
                self.depth += 1;
                if self.depth > 128 {
                    return Err(());
                }
                self.i += 1;
                let mut map = Map::new();
                self.ws();
                if self.peek() == Some(b'}') {
                    self.i += 1;
                    self.depth -= 1;
                    return Ok(Value::Object(map));
                }
                loop {
                    self.ws();
                    if self.peek() != Some(b'"') {
                        return Err(());
                    }
                    self.i += 1;
                    let k = self.string()?;
                    self.ws();
                    if self.peek() != Some(b':') {
                        return Err(());
                    }
                    self.i += 1;
                    self.ws();
                    let v = self.value()?;
                    map.insert(k, v);
                    self.ws();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                        }
                        Some(b'}') => {
                            self.i += 1;
                            break;
                        }
                        _ => return Err(()),
                    }
                }
                self.depth -= 1;
                Ok(Value::Object(map))
            }
            _ => Err(()),
        }
    }

    fn hex4(&mut self) -> R<u16> {
        if self.i + 4 > self.s.len() {
            return Err(());
        }
        let mut v: u16 = 0;
        for _ in 0..4 {
            let c = self.s[self.i];
            let d = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => return Err(()),
            };
            v = v * 16 + d as u16;
            self.i += 1;
        }
        Ok(v)
    }

    fn string(&mut self) -> R<String> {
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = match self.peek() {
                None => return Err(()),
                Some(c) => c,
            };
            self.i += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.peek().ok_or(())?;
                    self.i += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let n = self.hex4()?;
                            let ch: u32;
                            if (0xD800..0xDC00).contains(&n) {
                                // leading surrogate; need trailing
                                if self.peek() != Some(b'\\') {
                                    return Err(());
                                }
                                self.i += 1;
                                if self.peek() != Some(b'u') {
                                    return Err(());
                                }
                                self.i += 1;
                                let n2 = self.hex4()?;
                                if !(0xDC00..0xE000).contains(&n2) {
