                        _ => return self.parse_number(positive, sig),
                    }
                }
            }
            _ => return Err(()),
        };
        Ok(Value::Number(Number::F(f)))
    }

    fn parse_number(&mut self, positive: bool, sig: u64) -> R<Value> {
        match self.peek() {
            Some(b'.') => Ok(Value::Number(Number::F(self.parse_decimal(positive, sig, 0)?))),
            Some(b'e') | Some(b'E') => Ok(Value::Number(Number::F(self.parse_exponent(positive, sig, 0)?))),
