            self.i += 1;
            sig = sig * 10 + d;
            exp_after -= 1;
        }
        if exp_after == 0 {
            return Err(());
        }
        let exponent = exp_before + exp_after;
        match self.peek() {
            Some(b'e') | Some(b'E') => self.parse_exponent(positive, sig, exponent),
            _ => self.f64_from_parts(positive, sig, exponent),
        }
    }

    fn parse_exponent(&mut self, positive: bool, sig: u64, starting_exp: i32) -> R<f64> {
