    }

    fn parse_exponent_overflow(&mut self, positive: bool, zero_sig: bool, positive_exp: bool) -> R<f64> {
        if !zero_sig && positive_exp {
            return Err(());
        }
        while let Some(b'0'..=b'9') = self.peek() {
            self.i += 1;
        }
        Ok(if positive { 0.0 } else { -0.0 })
    }

    fn parse_long_integer(&mut self, positive: bool, sig: u64) -> R<f64> {
