// Timestamp conversion helpers (epoch seconds / millis to RFC3339).
use std::time::{SystemTime, UNIX_EPOCH};

pub fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn now_millis() -> i64 {
    match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(d) => d.as_millis() as i64,
        Err(e) => -(e.duration().as_millis() as i64),
    }
}

pub fn format_millis(ms: i128) -> Option<String> {
    let min = days_from_civil(-262143, 1, 1) as i128 * 86_400_000;
    let max = days_from_civil(262143, 1, 1) as i128 * 86_400_000 - 1;
    if ms < min || ms > max {
        return None;
    }
    let days = ms.div_euclid(86_400_000) as i64;
    let rem = ms.rem_euclid(86_400_000) as i64;
    let (y, m, d) = civil_from_days(days);
    let h = rem / 3_600_000;
    let mi = (rem / 60_000) % 60;
    let s = (rem / 1000) % 60;
    let milli = rem % 1000;
    let year = if (0..=9999).contains(&y) { format!("{:04}", y) } else { format!("{:+05}", y) };
    Some(format!("{}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z", year, m, d, h, mi, s, milli))
}

/// Try to convert an integer-looking timestamp into a readable date.
pub fn convert_timestamp(input: &str) -> String {
    let n: i64 = match input.parse::<i64>() {
        Ok(n) => n,
        Err(_) => return input.to_string(),
    };
    let now = now_millis() as i128;
    let as_secs = n as i128 * 1000;
    let as_ms = n as i128;
    let ds = (as_secs - now).abs();
    let dm = (as_ms - now).abs();
    let ms = if ds < dm { as_secs } else { as_ms };
    match format_millis(ms) {
        Some(s) => s,
        None => input.to_string(),
    }
}
