    Eos,
    Flt(f64),
    Int(i64),
    Name(Vec<u8>),
    Str(Vec<u8>),
    Char(u8),
}

pub fn tok2str(t: &Tok) -> String {
    let s = match t {
        Tok::And => "and",
        Tok::Break => "break",
        Tok::Do => "do",
        Tok::Else => "else",
        Tok::Elseif => "elseif",
        Tok::End => "end",
        Tok::False => "false",
        Tok::For => "for",
        Tok::Function => "function",
        Tok::Goto => "goto",
        Tok::If => "if",
        Tok::In => "in",
        Tok::Local => "local",
        Tok::Nil => "nil",
        Tok::Not => "not",
        Tok::Or => "or",
        Tok::Repeat => "repeat",
        Tok::Return => "return",
        Tok::Then => "then",
        Tok::True => "true",
        Tok::Until => "until",
        Tok::While => "while",
        Tok::IDiv => "//",
        Tok::Concat => "..",
        Tok::Dots => "...",
        Tok::Eq => "==",
        Tok::Ge => ">=",
        Tok::Le => "<=",
        Tok::Ne => "~=",
        Tok::Shl => "<<",
        Tok::Shr => ">>",
        Tok::DbColon => "::",
        Tok::Eos => return "<eof>".to_string(),
        Tok::Flt(_) => return "<number>".to_string(),
        Tok::Int(_) => return "<integer>".to_string(),
        Tok::Name(_) => return "<name>".to_string(),
        Tok::Str(_) => return "<string>".to_string(),
        Tok::Char(c) => {
            let c = *c;
