pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub linenumber: u32,
    pub lastline: u32,
    pub tok: Tok,
    pub tok_text: Vec<u8>,
    pub ahead: Option<(Tok, Vec<u8>, u32)>,
    pub buff: Vec<u8>,
    pub chunkname: String,
}

pub struct SynErr(pub String);

fn is_alpha(c: i32) -> bool {
    c >= 0 && ((c as u8).is_ascii_alphabetic() || c == b'_' as i32)
}
fn is_alnum(c: i32) -> bool {
    c >= 0 && ((c as u8).is_ascii_alphanumeric() || c == b'_' as i32)
}
fn is_digit(c: i32) -> bool {
    c >= 0 && (c as u8).is_ascii_digit()
}
fn is_xdigit(c: i32) -> bool {
    c >= 0 && (c as u8).is_ascii_hexdigit()
}
fn is_space(c: i32) -> bool {
    c == b' ' as i32 || c == b'\t' as i32 || c == b'\n' as i32 || c == b'\r' as i32 || c == 0x0b || c == 0x0c
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let mut l = Lexer {
            src,
            pos: 0,
            linenumber: 1,
            lastline: 1,
            tok: Tok::Eos,
            tok_text: Vec::new(),
            ahead: None,
            buff: Vec::new(),
            chunkname: chunkname.to_string(),
        };
        // skip first line if starts with '#'
        if l.src.first() == Some(&b'#') {
            while l.cur() != -1 && !l.is_newline() {
                l.pos += 1;
            }
        }
        l
    }

    fn cur(&self) -> i32 {
        match self.src.get(self.pos) {
            Some(&c) => c as i32,
            None => -1,
        }
    }
    fn is_newline(&self) -> bool {
        let c = self.cur();
        c == b'\n' as i32 || c == b'\r' as i32
    }
    fn next_ch(&mut self) {
        if self.pos < self.src.len() {
            self.pos += 1;
        }
    }
    fn save_and_next(&mut self) {
        let c = self.cur();
        if c >= 0 {
            self.buff.push(c as u8);
        }
        self.next_ch();
    }
    fn save(&mut self, c: u8) {
        self.buff.push(c);
    }
    fn inc_line(&mut self) {
        let old = self.cur();
        self.next_ch();
        if self.is_newline() && self.cur() != old {
            self.next_ch();
        }
        self.linenumber += 1;
    }
    fn check_next1(&mut self, c: u8) -> bool {
        if self.cur() == c as i32 {
            self.next_ch();
            true
        } else {
            false
        }
    }
    fn check_next2(&mut self, set: &[u8; 2]) -> bool {
        let c = self.cur();
        if c == set[0] as i32 || c == set[1] as i32 {
            self.save_and_next();
            true
        } else {
            false
        }
    }

    pub fn txt_token(&self, t: &Tok, text: &[u8]) -> String {
        match t {
            Tok::Name(_) | Tok::Str(_) | Tok::Flt(_) | Tok::Int(_) => {
                format!("'{}'", String::from_utf8_lossy(text))
            }
            _ => tok2str(t),
        }
    }

    pub fn error_at(&self, msg: &str, tok: Option<(&Tok, &[u8])>) -> SynErr {
        let mut m = format!("{}:{}: {}", self.chunkname, self.linenumber, msg);
        if let Some((t, text)) = tok {
            m = format!("{} near {}", m, self.txt_token(t, text));
        }
        SynErr(m)
    }

    fn lexerror(&self, msg: &str, tok: Option<Tok>) -> SynErr {
        match tok {
            Some(t) => {
                let s = self.txt_token(&t, &self.buff);
                SynErr(format!("{}:{}: {} near {}", self.chunkname, self.linenumber, msg, s))
            }
            None => SynErr(format!("{}:{}: {}", self.chunkname, self.linenumber, msg)),
        }
    }

    pub fn syntax_error(&self, msg: &str) -> SynErr {
        let s = self.txt_token(&self.tok, &self.tok_text);
        SynErr(format!("{}:{}: {} near {}", self.chunkname, self.linenumber, msg, s))
    }

    pub fn next(&mut self) -> Result<(), SynErr> {
        self.lastline = self.linenumber;
        if let Some((t, text, _)) = self.ahead.take() {
            self.tok = t;
            self.tok_text = text;
            return Ok(());
        }
        let t = self.lex()?;
        self.tok = t;
        self.tok_text = self.buff.clone();
        Ok(())
    }

    pub fn lookahead(&mut self) -> Result<Tok, SynErr> {
        let t = self.lex()?;
        let text = self.buff.clone();
        self.ahead = Some((t.clone(), text, self.linenumber));
        Ok(t)
    }

    fn skip_sep(&mut self) -> usize {
        // returns count+2 if well formed, 1 if single bracket, 0 if malformed
        let mut count = 0usize;
        let s = self.cur();
        self.save_and_next();
        while self.cur() == b'=' as i32 {
            self.save_and_next();
            count += 1;
        }
        if self.cur() == s {
            count + 2
        } else if count == 0 {
            1
        } else {
            0
        }
    }

    fn read_long_string(&mut self, is_string: bool, sep: usize) -> Result<Vec<u8>, SynErr> {
        let line = self.linenumber;
        self.save_and_next(); // skip second '['
        if self.is_newline() {
            self.inc_line();
        }
        loop {
            match self.cur() {
                -1 => {
                    let what = if is_string { "string" } else { "comment" };
                    let msg = format!("unfinished long {} (starting at line {})", what, line);
                    return Err(self.lexerror(&msg, Some(Tok::Eos)));
                }
                c if c == b']' as i32 => {
                    if self.skip_sep() == sep {
                        self.save_and_next();
                        break;
                    }
                }
                c if c == b'\n' as i32 || c == b'\r' as i32 => {
                    self.save(b'\n');
                    self.inc_line();
                    if !is_string {
                        self.buff.clear();
                    }
                }
                _ => {
                    if is_string {
                        self.save_and_next();
                    } else {
                        self.next_ch();
                    }
                }
            }
        }
        if is_string {
            let b = &self.buff[sep..self.buff.len() - sep];
            Ok(b.to_vec())
        } else {
            Ok(Vec::new())
        }
    }

    fn esc_check(&mut self, cond: bool, msg: &str) -> Result<(), SynErr> {
        if !cond {
            if self.cur() != -1 {
                self.save_and_next();
            }
            return Err(self.lexerror(msg, Some(Tok::Str(Vec::new()))));
        }
        Ok(())
    }

    fn gethexa(&mut self) -> Result<u32, SynErr> {
        self.save_and_next();
        let c = self.cur();
        self.esc_check(is_xdigit(c), "hexadecimal digit expected")?;
        Ok((c as u8 as char).to_digit(16).unwrap())
    }

    fn read_string(&mut self, del: i32) -> Result<Vec<u8>, SynErr> {
        self.save_and_next();
        let mut out: Vec<u8> = Vec::new();
        while self.cur() != del {
            match self.cur() {
                -1 => return Err(self.lexerror("unfinished string", Some(Tok::Eos))),
                c if c == b'\n' as i32 || c == b'\r' as i32 => {
                    return Err(self.lexerror("unfinished string", Some(Tok::Str(Vec::new()))));
                }
                c if c == b'\\' as i32 => {
                    self.save_and_next();
                    let c = self.cur();
                    let mut ch: Option<u8> = None;
                    match c {
                        x if x == b'a' as i32 => ch = Some(7),
                        x if x == b'b' as i32 => ch = Some(8),
                        x if x == b'f' as i32 => ch = Some(12),
                        x if x == b'n' as i32 => ch = Some(b'\n'),
                        x if x == b'r' as i32 => ch = Some(b'\r'),
                        x if x == b't' as i32 => ch = Some(b'\t'),
                        x if x == b'v' as i32 => ch = Some(11),
                        x if x == b'x' as i32 => {
                            let mut r = self.gethexa()?;
                            r = (r << 4) + self.gethexa()?;
                            // remove saved chars: '\\' 'x' and first digit
                            let l = self.buff.len();
                            self.buff.truncate(l - 2);
                            self.next_ch();
                            self.buff.pop(); // remove '\\'
                            out.push(r as u8);
                            self.buff.push(r as u8);
                            continue;
                        }
                        x if x == b'u' as i32 => {
