                        self.next_ch();
                        self.buff.pop(); // remove '\\'
                        out.push(chv);
                        self.buff.push(chv);
                    }
                }
                _ => {
                    let c = self.cur() as u8;
                    out.push(c);
                    self.save_and_next();
                }
            }
        }
        self.save_and_next();
        Ok(out)
    }

    fn read_numeral(&mut self) -> Result<Tok, SynErr> {
        let mut expo: [u8; 2] = *b"Ee";
        let first = self.cur();
        self.save_and_next();
        if first == b'0' as i32 && self.check_next2(b"xX") {
            expo = *b"Pp";
        }
        loop {
            if self.check_next2(&expo) {
                self.check_next2(b"-+");
            } else if is_xdigit(self.cur()) || self.cur() == b'.' as i32 {
                self.save_and_next();
            } else {
                break;
            }
        }
        if is_alpha(self.cur()) {
            self.save_and_next();
        }
        match str2number(&self.buff) {
            Some(Val::Int(i)) => Ok(Tok::Int(i)),
            Some(Val::Num(f)) => Ok(Tok::Flt(f)),
            _ => Err(self.lexerror("malformed number", Some(Tok::Flt(0.0)))),
        }
    }

    fn lex(&mut self) -> Result<Tok, SynErr> {
        self.buff.clear();
        loop {
            let c = self.cur();
            match c {
                -1 => return Ok(Tok::Eos),
                x if x == b'\n' as i32 || x == b'\r' as i32 => {
                    self.inc_line();
                }
                x if x == b' ' as i32 || x == b'\t' as i32 || x == 0x0b || x == 0x0c => {
                    self.next_ch();
                }
                x if x == b'-' as i32 => {
                    self.next_ch();
                    if self.cur() != b'-' as i32 {
                        return Ok(Tok::Char(b'-'));
                    }
                    self.next_ch();
                    if self.cur() == b'[' as i32 {
                        let sep = self.skip_sep();
                        self.buff.clear();
                        if sep >= 2 {
                            self.read_long_string(false, sep)?;
                            self.buff.clear();
                            continue;
                        }
                    }
                    while !self.is_newline() && self.cur() != -1 {
                        self.next_ch();
                    }
                }
                x if x == b'[' as i32 => {
                    let sep = self.skip_sep();
                    if sep >= 2 {
                        let s = self.read_long_string(true, sep)?;
                        return Ok(Tok::Str(s));
                    } else if sep == 0 {
                        return Err(self.lexerror("invalid long string delimiter", Some(Tok::Str(Vec::new()))));
                    }
                    return Ok(Tok::Char(b'['));
                }
                x if x == b'=' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Eq);
                    }
                    return Ok(Tok::Char(b'='));
                }
                x if x == b'<' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Le);
                    }
                    if self.check_next1(b'<') {
                        return Ok(Tok::Shl);
                    }
                    return Ok(Tok::Char(b'<'));
                }
                x if x == b'>' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Ge);
                    }
                    if self.check_next1(b'>') {
                        return Ok(Tok::Shr);
                    }
                    return Ok(Tok::Char(b'>'));
                }
                x if x == b'/' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'/') {
                        return Ok(Tok::IDiv);
                    }
                    return Ok(Tok::Char(b'/'));
                }
                x if x == b'~' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Ne);
                    }
                    return Ok(Tok::Char(b'~'));
                }
                x if x == b':' as i32 => {
                    self.next_ch();
                    if self.check_next1(b':') {
                        return Ok(Tok::DbColon);
                    }
                    return Ok(Tok::Char(b':'));
                }
                x if x == b'"' as i32 || x == b'\'' as i32 => {
                    let s = self.read_string(x)?;
                    return Ok(Tok::Str(s));
                }
                x if x == b'.' as i32 => {
                    self.save_and_next();
                    if self.check_next1(b'.') {
                        if self.check_next1(b'.') {
                            return Ok(Tok::Dots);
                        }
                        return Ok(Tok::Concat);
                    }
                    if !is_digit(self.cur()) {
                        return Ok(Tok::Char(b'.'));
                    }
                    // number starting with '.'
                    loop {
                        if self.check_next2(b"Ee") {
                            self.check_next2(b"-+");
                        } else if is_xdigit(self.cur()) || self.cur() == b'.' as i32 {
                            self.save_and_next();
                        } else {
                            break;
                        }
                    }
                    if is_alpha(self.cur()) {
                        self.save_and_next();
                    }
                    return match str2number(&self.buff) {
                        Some(Val::Int(i)) => Ok(Tok::Int(i)),
                        Some(Val::Num(f)) => Ok(Tok::Flt(f)),
                        _ => Err(self.lexerror("malformed number", Some(Tok::Flt(0.0)))),
                    };
                }
                x if is_digit(x) => {
                    return self.read_numeral();
                }
                x => {
                    if is_alpha(x) {
                        while is_alnum(self.cur()) {
                            self.save_and_next();
                        }
                        if let Some(t) = reserved(&self.buff) {
                            return Ok(t);
                        }
                        return Ok(Tok::Name(self.buff.clone()));
                    }
                    self.next_ch();
                    return Ok(Tok::Char(x as u8));
                }
            }
        }
    }
}

pub fn utf8_encode(x: u32) -> Vec<u8> {
    let mut out = Vec::new();
    if x < 0x80 {
        out.push(x as u8);
        return out;
    }
    let mut buf = [0u8; 8];
    let mut n = 1usize;
    let mut x = x;
    let mut mfb: u32 = 0x3f;
    loop {
        buf[8 - n] = (0x80 | (x & 0x3f)) as u8;
        n += 1;
        x >>= 6;
        mfb >>= 1;
        if x <= mfb {
            break;
        }
    }
    buf[8 - n] = ((!mfb << 1) | x) as u8;
    out.extend_from_slice(&buf[8 - n..]);
    out
}
