// Lua 5.4 lexer
use super::value::str2number;
use super::value::Val;

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    // reserved
    And,
    Break,
    Do,
    Else,
    Elseif,
    End,
    False,
    For,
    Function,
    Goto,
