    DbColon,
    Eos,
    Flt(f64),
    Int(i64),
    Name(Vec<u8>),
    Str(Vec<u8>),
    Char(u8),
}

pub fn tok2str(t: &Tok) -> String {
    let s = match t {
        Tok::And => "and",
        Tok::Break => "break",
        Tok::Do => "do",
        Tok::Else => "else",
        Tok::Elseif => "elseif",
        Tok::End => "end",
        Tok::False => "false",
        Tok::For => "for",
        Tok::Function => "function",
