    })
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub linenumber: u32,
    pub lastline: u32,
    pub tok: Tok,
    pub tok_text: Vec<u8>,
    pub ahead: Option<(Tok, Vec<u8>, u32)>,
    pub buff: Vec<u8>,
    pub chunkname: String,
}

pub struct SynErr(pub String);

fn is_alpha(c: i32) -> bool {
    c >= 0 && ((c as u8).is_ascii_alphabetic() || c == b'_' as i32)
}
fn is_alnum(c: i32) -> bool {
    c >= 0 && ((c as u8).is_ascii_alphanumeric() || c == b'_' as i32)
}
fn is_digit(c: i32) -> bool {
    c >= 0 && (c as u8).is_ascii_digit()
}
fn is_xdigit(c: i32) -> bool {
    c >= 0 && (c as u8).is_ascii_hexdigit()
}
fn is_space(c: i32) -> bool {
    c == b' ' as i32 || c == b'\t' as i32 || c == b'\n' as i32 || c == b'\r' as i32 || c == 0x0b || c == 0x0c
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let mut l = Lexer {
            src,
            pos: 0,
            linenumber: 1,
            lastline: 1,
            tok: Tok::Eos,
            tok_text: Vec::new(),
            ahead: None,
            buff: Vec::new(),
            chunkname: chunkname.to_string(),
        };
        // skip first line if starts with '#'
        if l.src.first() == Some(&b'#') {
            while l.cur() != -1 && !l.is_newline() {
                l.pos += 1;
            }
        }
        l
    }

    fn cur(&self) -> i32 {
        match self.src.get(self.pos) {
            Some(&c) => c as i32,
            None => -1,
        }
    }
    fn is_newline(&self) -> bool {
        let c = self.cur();
        c == b'\n' as i32 || c == b'\r' as i32
    }
    fn next_ch(&mut self) {
        if self.pos < self.src.len() {
            self.pos += 1;
        }
    }
    fn save_and_next(&mut self) {
        let c = self.cur();
        if c >= 0 {
            self.buff.push(c as u8);
        }
        self.next_ch();
    }
    fn save(&mut self, c: u8) {
        self.buff.push(c);
    }
    fn inc_line(&mut self) {
        let old = self.cur();
        self.next_ch();
        if self.is_newline() && self.cur() != old {
            self.next_ch();
        }
        self.linenumber += 1;
    }
    fn check_next1(&mut self, c: u8) -> bool {
        if self.cur() == c as i32 {
            self.next_ch();
            true
        } else {
            false
        }
    }
    fn check_next2(&mut self, set: &[u8; 2]) -> bool {
        let c = self.cur();
        if c == set[0] as i32 || c == set[1] as i32 {
            self.save_and_next();
            true
        } else {
            false
        }
    }

    pub fn txt_token(&self, t: &Tok, text: &[u8]) -> String {
        match t {
            Tok::Name(_) | Tok::Str(_) | Tok::Flt(_) | Tok::Int(_) => {
                format!("'{}'", String::from_utf8_lossy(text))
            }
            _ => tok2str(t),
        }
    }

    pub fn error_at(&self, msg: &str, tok: Option<(&Tok, &[u8])>) -> SynErr {
        let mut m = format!("{}:{}: {}", self.chunkname, self.linenumber, msg);
        if let Some((t, text)) = tok {
            m = format!("{} near {}", m, self.txt_token(t, text));
        }
        SynErr(m)
    }

    fn lexerror(&self, msg: &str, tok: Option<Tok>) -> SynErr {
        match tok {
            Some(t) => {
                let s = self.txt_token(&t, &self.buff);
                SynErr(format!("{}:{}: {} near {}", self.chunkname, self.linenumber, msg, s))
            }
            None => SynErr(format!("{}:{}: {}", self.chunkname, self.linenumber, msg)),
        }
    }

    pub fn syntax_error(&self, msg: &str) -> SynErr {
        let s = self.txt_token(&self.tok, &self.tok_text);
        SynErr(format!("{}:{}: {} near {}", self.chunkname, self.linenumber, msg, s))
    }

    pub fn next(&mut self) -> Result<(), SynErr> {
        self.lastline = self.linenumber;
        if let Some((t, text, _)) = self.ahead.take() {
            self.tok = t;
            self.tok_text = text;
            return Ok(());
        }
        let t = self.lex()?;
        self.tok = t;
        self.tok_text = self.buff.clone();
        Ok(())
    }

    pub fn lookahead(&mut self) -> Result<Tok, SynErr> {
        let t = self.lex()?;
        let text = self.buff.clone();
        self.ahead = Some((t.clone(), text, self.linenumber));
        Ok(t)
    }

    fn skip_sep(&mut self) -> usize {
        // returns count+2 if well formed, 1 if single bracket, 0 if malformed
        let mut count = 0usize;
        let s = self.cur();
        self.save_and_next();
        while self.cur() == b'=' as i32 {
            self.save_and_next();
            count += 1;
        }
        if self.cur() == s {
            count + 2
        } else if count == 0 {
            1
        } else {
            0
        }
    }

    fn read_long_string(&mut self, is_string: bool, sep: usize) -> Result<Vec<u8>, SynErr> {
        let line = self.linenumber;
        self.save_and_next(); // skip second '['
        if self.is_newline() {
            self.inc_line();
        }
        loop {
            match self.cur() {
                -1 => {
                    let what = if is_string { "string" } else { "comment" };
                    let msg = format!("unfinished long {} (starting at line {})", what, line);
                    return Err(self.lexerror(&msg, Some(Tok::Eos)));
                }
                c if c == b']' as i32 => {
                    if self.skip_sep() == sep {
                        self.save_and_next();
                        break;
                    }
                }
                c if c == b'\n' as i32 || c == b'\r' as i32 => {
                    self.save(b'\n');
                    self.inc_line();
                    if !is_string {
                        self.buff.clear();
                    }
                }
                _ => {
                    if is_string {
                        self.save_and_next();
                    } else {
                        self.next_ch();
                    }
                }
            }
        }
        if is_string {
            let b = &self.buff[sep..self.buff.len() - sep];
            Ok(b.to_vec())
        } else {
            Ok(Vec::new())
        }
    }

    fn esc_check(&mut self, cond: bool, msg: &str) -> Result<(), SynErr> {
        if !cond {
            if self.cur() != -1 {
                self.save_and_next();
            }
            return Err(self.lexerror(msg, Some(Tok::Str(Vec::new()))));
        }
        Ok(())
    }

    fn gethexa(&mut self) -> Result<u32, SynErr> {
        self.save_and_next();
        let c = self.cur();
        self.esc_check(is_xdigit(c), "hexadecimal digit expected")?;
        Ok((c as u8 as char).to_digit(16).unwrap())
    }

    fn read_string(&mut self, del: i32) -> Result<Vec<u8>, SynErr> {
        self.save_and_next();
        let mut out: Vec<u8> = Vec::new();
        while self.cur() != del {
            match self.cur() {
                -1 => return Err(self.lexerror("unfinished string", Some(Tok::Eos))),
                c if c == b'\n' as i32 || c == b'\r' as i32 => {
                    return Err(self.lexerror("unfinished string", Some(Tok::Str(Vec::new()))));
                }
                c if c == b'\\' as i32 => {
                    self.save_and_next();
                    let c = self.cur();
                    let mut ch: Option<u8> = None;
                    match c {
                        x if x == b'a' as i32 => ch = Some(7),
                        x if x == b'b' as i32 => ch = Some(8),
                        x if x == b'f' as i32 => ch = Some(12),
                        x if x == b'n' as i32 => ch = Some(b'\n'),
                        x if x == b'r' as i32 => ch = Some(b'\r'),
                        x if x == b't' as i32 => ch = Some(b'\t'),
                        x if x == b'v' as i32 => ch = Some(11),
                        x if x == b'x' as i32 => {
                            let mut r = self.gethexa()?;
                            r = (r << 4) + self.gethexa()?;
                            // remove saved chars: '\\' 'x' and first digit
                            let l = self.buff.len();
                            self.buff.truncate(l - 2);
                            self.next_ch();
                            self.buff.pop(); // remove '\\'
                            out.push(r as u8);
                            self.buff.push(r as u8);
                            continue;
                        }
                        x if x == b'u' as i32 => {
                            // utf8 escape
                            self.save_and_next();
                            self.esc_check(self.cur() == b'{' as i32, "missing '{' in \\u{xxxx}")?;
                            let mut r = self.gethexa()?;
                            loop {
                                self.save_and_next();
                                let c = self.cur();
                                if !is_xdigit(c) {
                                    break;
                                }
                                self.esc_check(r <= (0x7FFFFFFFu32 >> 4), "UTF-8 value too large")?;
                                r = (r << 4) + (c as u8 as char).to_digit(16).unwrap();
                            }
                            self.esc_check(self.cur() == b'}' as i32, "missing '}' in \\u{xxxx}")?;
                            self.next_ch();
                            // remove "\u{xxx" from buffer
                            while let Some(&b) = self.buff.last() {
                                self.buff.pop();
                                if b == b'\\' {
                                    break;
                                }
                            }
                            let enc = utf8_encode(r);
                            out.extend_from_slice(&enc);
                            self.buff.extend_from_slice(&enc);
                            continue;
                        }
                        x if x == b'\n' as i32 || x == b'\r' as i32 => {
                            self.inc_line();
                            self.buff.pop();
                            out.push(b'\n');
                            self.buff.push(b'\n');
                            continue;
                        }
                        x if x == b'\\' as i32 || x == b'"' as i32 || x == b'\'' as i32 => {
                            ch = Some(x as u8);
                        }
                        -1 => continue, // will raise unfinished string
                        x if x == b'z' as i32 => {
                            self.buff.pop();
                            self.next_ch();
                            while is_space(self.cur()) {
                                if self.is_newline() {
                                    self.inc_line();
                                } else {
                                    self.next_ch();
                                }
                            }
                            continue;
                        }
                        _ => {
                            self.esc_check(is_digit(c), "invalid escape sequence")?;
                            // decimal escape
                            let mut r: u32 = 0;
                            let mut i = 0;
                            while i < 3 && is_digit(self.cur()) {
                                r = 10 * r + (self.cur() - b'0' as i32) as u32;
                                self.save_and_next();
                                i += 1;
                            }
                            self.esc_check(r <= 255, "decimal escape too large")?;
                            // remove saved digits and backslash
                            for _ in 0..i {
                                self.buff.pop();
                            }
                            self.buff.pop();
                            out.push(r as u8);
                            self.buff.push(r as u8);
                            continue;
                        }
                    }
                    if let Some(chv) = ch {
                        self.next_ch();
                        self.buff.pop(); // remove '\\'
                        out.push(chv);
                        self.buff.push(chv);
                    }
                }
                _ => {
                    let c = self.cur() as u8;
                    out.push(c);
                    self.save_and_next();
                }
            }
        }
        self.save_and_next();
        Ok(out)
    }

    fn read_numeral(&mut self) -> Result<Tok, SynErr> {
        let mut expo: [u8; 2] = *b"Ee";
        let first = self.cur();
        self.save_and_next();
        if first == b'0' as i32 && self.check_next2(b"xX") {
            expo = *b"Pp";
        }
        loop {
            if self.check_next2(&expo) {
                self.check_next2(b"-+");
            } else if is_xdigit(self.cur()) || self.cur() == b'.' as i32 {
                self.save_and_next();
            } else {
                break;
            }
        }
        if is_alpha(self.cur()) {
            self.save_and_next();
        }
        match str2number(&self.buff) {
            Some(Val::Int(i)) => Ok(Tok::Int(i)),
            Some(Val::Num(f)) => Ok(Tok::Flt(f)),
            _ => Err(self.lexerror("malformed number", Some(Tok::Flt(0.0)))),
        }
    }

    fn lex(&mut self) -> Result<Tok, SynErr> {
        self.buff.clear();
        loop {
            let c = self.cur();
            match c {
                -1 => return Ok(Tok::Eos),
                x if x == b'\n' as i32 || x == b'\r' as i32 => {
                    self.inc_line();
                }
                x if x == b' ' as i32 || x == b'\t' as i32 || x == 0x0b || x == 0x0c => {
                    self.next_ch();
                }
                x if x == b'-' as i32 => {
                    self.next_ch();
                    if self.cur() != b'-' as i32 {
                        return Ok(Tok::Char(b'-'));
                    }
                    self.next_ch();
                    if self.cur() == b'[' as i32 {
                        let sep = self.skip_sep();
                        self.buff.clear();
                        if sep >= 2 {
                            self.read_long_string(false, sep)?;
                            self.buff.clear();
                            continue;
                        }
                    }
                    while !self.is_newline() && self.cur() != -1 {
                        self.next_ch();
                    }
                }
                x if x == b'[' as i32 => {
                    let sep = self.skip_sep();
                    if sep >= 2 {
                        let s = self.read_long_string(true, sep)?;
                        return Ok(Tok::Str(s));
                    } else if sep == 0 {
                        return Err(self.lexerror("invalid long string delimiter", Some(Tok::Str(Vec::new()))));
                    }
                    return Ok(Tok::Char(b'['));
                }
                x if x == b'=' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Eq);
                    }
                    return Ok(Tok::Char(b'='));
                }
                x if x == b'<' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Le);
                    }
                    if self.check_next1(b'<') {
                        return Ok(Tok::Shl);
                    }
                    return Ok(Tok::Char(b'<'));
                }
                x if x == b'>' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Ge);
                    }
                    if self.check_next1(b'>') {
                        return Ok(Tok::Shr);
                    }
                    return Ok(Tok::Char(b'>'));
                }
                x if x == b'/' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'/') {
                        return Ok(Tok::IDiv);
                    }
                    return Ok(Tok::Char(b'/'));
                }
                x if x == b'~' as i32 => {
                    self.next_ch();
                    if self.check_next1(b'=') {
                        return Ok(Tok::Ne);
                    }
                    return Ok(Tok::Char(b'~'));
                }
                x if x == b':' as i32 => {
                    self.next_ch();
                    if self.check_next1(b':') {
                        return Ok(Tok::DbColon);
                    }
                    return Ok(Tok::Char(b':'));
                }
                x if x == b'"' as i32 || x == b'\'' as i32 => {
                    let s = self.read_string(x)?;
                    return Ok(Tok::Str(s));
                }
                x if x == b'.' as i32 => {
                    self.save_and_next();
                    if self.check_next1(b'.') {
                        if self.check_next1(b'.') {
                            return Ok(Tok::Dots);
                        }
                        return Ok(Tok::Concat);
                    }
                    if !is_digit(self.cur()) {
                        return Ok(Tok::Char(b'.'));
                    }
                    // number starting with '.'
                    loop {
                        if self.check_next2(b"Ee") {
                            self.check_next2(b"-+");
                        } else if is_xdigit(self.cur()) || self.cur() == b'.' as i32 {
                            self.save_and_next();
                        } else {
                            break;
                        }
                    }
                    if is_alpha(self.cur()) {
                        self.save_and_next();
                    }
                    return match str2number(&self.buff) {
                        Some(Val::Int(i)) => Ok(Tok::Int(i)),
                        Some(Val::Num(f)) => Ok(Tok::Flt(f)),
                        _ => Err(self.lexerror("malformed number", Some(Tok::Flt(0.0)))),
                    };
                }
                x if is_digit(x) => {
                    return self.read_numeral();
                }
                x => {
                    if is_alpha(x) {
                        while is_alnum(self.cur()) {
                            self.save_and_next();
                        }
                        if let Some(t) = reserved(&self.buff) {
                            return Ok(t);
                        }
                        return Ok(Tok::Name(self.buff.clone()));
                    }
                    self.next_ch();
                    return Ok(Tok::Char(x as u8));
                }
            }
        }
    }
}

pub fn utf8_encode(x: u32) -> Vec<u8> {
    let mut out = Vec::new();
    if x < 0x80 {
        out.push(x as u8);
        return out;
    }
    let mut buf = [0u8; 8];
    let mut n = 1usize;
    let mut x = x;
    let mut mfb: u32 = 0x3f;
    loop {
        buf[8 - n] = (0x80 | (x & 0x3f)) as u8;
        n += 1;
        x >>= 6;
        mfb >>= 1;
        if x <= mfb {
            break;
        }
    }
    buf[8 - n] = ((!mfb << 1) | x) as u8;
    out.extend_from_slice(&buf[8 - n..]);
    out
}
