                    let (mode, ch): (u8, u8) = match c {
                        x if x == b'a' as i32 => (0, 7),
                        x if x == b'b' as i32 => (0, 8),
                        x if x == b'f' as i32 => (0, 12),
                        x if x == b'n' as i32 => (0, b'\n'),
                        x if x == b'r' as i32 => (0, b'\r'),
                        x if x == b't' as i32 => (0, b'\t'),
                        x if x == b'v' as i32 => (0, 11),
