                            }
                            (2, 0)
                        }
                        _ => {
                            self.esc_check(is_digit(c), "invalid escape sequence")?;
                            let mut r: u32 = 0;
                            let mut i = 0;
                            while i < 3 && is_digit(self.cur()) {
