                                i += 1;
                            }
                            self.esc_check(r <= 255, "decimal escape too large")?;
                            self.buffremove(i);
                            (1, r as u8)
                        }
                    };
                    if mode == 0 {
                        self.next_ch();
                    }
                    if mode <= 1 {
                        self.buffremove(1);
                        self.save(ch);
                    }
                }
                _ => {
                    self.save_and_next();
                }
            }
        }
        self.save_and_next();
        let b = &self.buff[1..self.buff.len() - 1];
        Ok(b.to_vec())
    }

