// Lua values
use std::cell::RefCell;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::rc::Rc;

use super::ast::Proto;
use super::interp::Interp;

pub type TableRef = Rc<RefCell<Table>>;
pub type LStr = Rc<[u8]>;

pub type NativeFn = Rc<dyn Fn(&mut Interp, Vec<Val>) -> Result<Vec<Val>, LuaError>>;

pub enum Func {
    Lua { proto: Rc<Proto>, upvals: Vec<Rc<RefCell<Val>>> },
    Native { name: String, f: NativeFn },
}

#[derive(Clone)]
pub enum Val {
    Nil,
    Bool(bool),
    Int(i64),
    Num(f64),
    Str(LStr),
    Table(TableRef),
    Func(Rc<Func>),
}

#[derive(Clone)]
pub enum LuaError {
    Runtime { value: Val, traceback: Option<String> },
    Syntax { msg: String, incomplete: bool },
}

impl Val {
    pub fn str(s: &str) -> Val {
        Val::Str(Rc::from(s.as_bytes()))
    }
    pub fn bytes(s: &[u8]) -> Val {
        Val::Str(Rc::from(s))
    }
    pub fn truthy(&self) -> bool {
        !matches!(self, Val::Nil | Val::Bool(false))
    }
    pub fn is_nil(&self) -> bool {
        matches!(self, Val::Nil)
    }
    pub fn type_name(&self) -> &'static str {
        match self {
            Val::Nil => "nil",
            Val::Bool(_) => "boolean",
            Val::Int(_) | Val::Num(_) => "number",
            Val::Str(_) => "string",
            Val::Table(_) => "table",
            Val::Func(_) => "function",
        }
    }
    pub fn raw_eq(&self, o: &Val) -> bool {
        match (self, o) {
            (Val::Nil, Val::Nil) => true,
            (Val::Bool(a), Val::Bool(b)) => a == b,
            (Val::Int(a), Val::Int(b)) => a == b,
            (Val::Num(a), Val::Num(b)) => a == b,
            (Val::Int(a), Val::Num(b)) => (*a as f64) == *b && float_to_int_exact(*b) == Some(*a),
            (Val::Num(a), Val::Int(b)) => (*b as f64) == *a && float_to_int_exact(*a) == Some(*b),
            (Val::Str(a), Val::Str(b)) => a == b,
            (Val::Table(a), Val::Table(b)) => Rc::ptr_eq(a, b),
            (Val::Func(a), Val::Func(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
    pub fn ptr_addr(&self) -> usize {
        match self {
            Val::Table(t) => Rc::as_ptr(t) as *const u8 as usize,
            Val::Func(f) => Rc::as_ptr(f) as *const u8 as usize,
            Val::Str(s) => s.as_ptr() as usize,
            _ => 0,
        }
    }
}

pub fn float_to_int_exact(f: f64) -> Option<i64> {
    if f.floor() == f && f >= -9223372036854775808.0 && f < 9223372036854775808.0 {
        Some(f as i64)
    } else {
        None
    }
}

/// Key wrapper for hashing
#[derive(Clone)]
pub struct HKey(pub Val);

impl PartialEq for HKey {
    fn eq(&self, o: &HKey) -> bool {
        match (&self.0, &o.0) {
            (Val::Num(a), Val::Num(b)) => a.to_bits() == b.to_bits() || a == b,
            _ => self.0.raw_eq(&o.0),
        }
    }
}
impl Eq for HKey {}
impl Hash for HKey {
    fn hash<H: Hasher>(&self, h: &mut H) {
        match &self.0 {
            Val::Nil => 0u8.hash(h),
            Val::Bool(b) => {
                1u8.hash(h);
                b.hash(h)
            }
            Val::Int(i) => {
                2u8.hash(h);
                i.hash(h)
            }
            Val::Num(f) => {
                3u8.hash(h);
                f.to_bits().hash(h)
            }
            Val::Str(s) => {
                4u8.hash(h);
                s.hash(h)
            }
            v => {
                5u8.hash(h);
                v.ptr_addr().hash(h)
            }
        }
    }
}

#[derive(Default)]
pub struct Table {
    pub arr: Vec<Val>,
    pub index: HashMap<HKey, usize>,
    pub entries: Vec<(Val, Val)>,
    pub live: usize,
    pub meta: Option<TableRef>,
}

/// Normalize a key: floats with integral value become integers.
pub fn norm_key(k: &Val) -> Val {
    if let Val::Num(f) = k {
        if let Some(i) = float_to_int_exact(*f) {
            return Val::Int(i);
        }
    }
    k.clone()
}

impl Table {
    pub fn new() -> Table {
        Table::default()
    }
    pub fn new_ref() -> TableRef {
        Rc::new(RefCell::new(Table::new()))
    }
    pub fn get(&self, k: &Val) -> Val {
        let k = norm_key(k);
        if let Val::Int(i) = k {
            if i >= 1 && (i as usize) <= self.arr.len() {
                return self.arr[i as usize - 1].clone();
            }
        }
        if let Val::Nil = k {
            return Val::Nil;
        }
        match self.index.get(&HKey(k)) {
            Some(&idx) => self.entries[idx].1.clone(),
            None => Val::Nil,
        }
    }
    pub fn get_str(&self, k: &str) -> Val {
        self.get(&Val::str(k))
    }
    pub fn get_int(&self, i: i64) -> Val {
        if i >= 1 && (i as usize) <= self.arr.len() {
            return self.arr[i as usize - 1].clone();
        }
        match self.index.get(&HKey(Val::Int(i))) {
            Some(&idx) => self.entries[idx].1.clone(),
            None => Val::Nil,
        }
    }
    /// raw set; caller must ensure key is not nil/NaN
    pub fn set(&mut self, k: Val, v: Val) {
        let k = norm_key(&k);
        if let Val::Int(i) = k {
            let n = self.arr.len();
            if i >= 1 && (i as usize) <= n {
                self.arr[i as usize - 1] = v;
                if i as usize == n {
                    while let Some(Val::Nil) = self.arr.last() {
                        self.arr.pop();
                    }
                }
                return;
            }
            if i as usize == n + 1 && i >= 1 {
                if v.is_nil() {
                    // maybe remove from hash
                    self.hash_set(Val::Int(i), v);
                    return;
                }
                // remove any hash entry for this key
                if let Some(&idx) = self.index.get(&HKey(Val::Int(i))) {
                    if !self.entries[idx].1.is_nil() {
                        self.live -= 1;
                    }
                    self.entries[idx].1 = Val::Nil;
                }
                self.arr.push(v);
                // migrate following keys
                loop {
                    let nk = Val::Int(self.arr.len() as i64 + 1);
                    let hk = HKey(nk);
                    match self.index.get(&hk) {
                        Some(&idx) if !self.entries[idx].1.is_nil() => {
                            let val = std::mem::replace(&mut self.entries[idx].1, Val::Nil);
                            self.live -= 1;
                            self.arr.push(val);
                        }
                        _ => break,
                    }
                }
                return;
            }
        }
        self.hash_set(k, v);
    }
    fn hash_set(&mut self, k: Val, v: Val) {
        let hk = HKey(k.clone());
        if let Some(&idx) = self.index.get(&hk) {
            let was_nil = self.entries[idx].1.is_nil();
            let now_nil = v.is_nil();
            self.entries[idx].1 = v;
            if was_nil && !now_nil {
                self.live += 1;
            } else if !was_nil && now_nil {
                self.live -= 1;
            }
            return;
        }
        if v.is_nil() {
            return;
        }
        // compact if many tombstones
        if self.entries.len() > 16 && self.live * 2 < self.entries.len() {
            self.compact();
        }
        self.index.insert(hk, self.entries.len());
        self.entries.push((k, v));
        self.live += 1;
    }
    fn compact(&mut self) {
        let old = std::mem::take(&mut self.entries);
        self.index.clear();
        for (k, v) in old {
            if !v.is_nil() {
                self.index.insert(HKey(k.clone()), self.entries.len());
                self.entries.push((k, v));
            }
        }
        self.live = self.entries.len();
    }
    pub fn len(&self) -> i64 {
        let mut n = self.arr.len() as i64;
        if self.live == 0 {
            return n;
        }
        loop {
            match self.index.get(&HKey(Val::Int(n + 1))) {
                Some(&idx) if !self.entries[idx].1.is_nil() => n += 1,
                _ => break,
            }
        }
        n
    }
    /// next for iteration; Err(()) for invalid key
    pub fn next(&self, k: &Val) -> Result<Option<(Val, Val)>, ()> {
        let mut start_arr = 0usize;
        let mut start_ent = 0usize;
        let k = norm_key(k);
        match &k {
            Val::Nil => {}
            Val::Int(i) if *i >= 1 && (*i as usize) <= self.arr.len() => {
                start_arr = *i as usize;
            }
            _ => match self.index.get(&HKey(k.clone())) {
                Some(&idx) => {
                    start_arr = self.arr.len();
                    start_ent = idx + 1;
                }
                None => return Err(()),
            },
        }
        for i in start_arr..self.arr.len() {
            if !self.arr[i].is_nil() {
                return Ok(Some((Val::Int(i as i64 + 1), self.arr[i].clone())));
            }
        }
        for j in start_ent..self.entries.len() {
            if !self.entries[j].1.is_nil() {
                return Ok(Some((self.entries[j].0.clone(), self.entries[j].1.clone())));
            }
        }
        Ok(None)
    }
}

fn is_lspace(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c
}

fn str2int(s: &[u8]) -> Option<i64> {
    let mut i = 0;
    while i < s.len() && is_lspace(s[i]) {
        i += 1;
    }
    let mut neg = false;
    if i < s.len() && s[i] == b'-' {
        neg = true;
        i += 1;
    } else if i < s.len() && s[i] == b'+' {
        i += 1;
    }
    let mut a: u64 = 0;
    let mut empty = true;
    if i + 1 < s.len() && s[i] == b'0' && (s[i + 1] == b'x' || s[i + 1] == b'X') {
        i += 2;
        while i < s.len() && s[i].is_ascii_hexdigit() {
            a = a.wrapping_mul(16).wrapping_add((s[i] as char).to_digit(16).unwrap() as u64);
            empty = false;
            i += 1;
        }
    } else {
        let maxby10 = (i64::MAX as u64) / 10;
        let maxlastd = (i64::MAX as u64) % 10;
        while i < s.len() && s[i].is_ascii_digit() {
            let d = (s[i] - b'0') as u64;
            if a >= maxby10 && (a > maxby10 || d > maxlastd + neg as u64) {
                return None;
            }
            a = a * 10 + d;
            empty = false;
            i += 1;
        }
    }
    while i < s.len() && is_lspace(s[i]) {
        i += 1;
    }
    if empty || i != s.len() {
        return None;
    }
    Some(if neg { (0u64.wrapping_sub(a)) as i64 } else { a as i64 })
}

fn hexval(c: u8) -> u32 {
    (c as char).to_digit(16).unwrap()
}

fn strx2number(s: &[u8]) -> Option<f64> {
    // s already trimmed of leading spaces; returns value and requires full consumption except trailing spaces
    let mut i = 0;
    let mut neg = false;
    if i < s.len() && s[i] == b'-' {
        neg = true;
        i += 1;
    } else if i < s.len() && s[i] == b'+' {
        i += 1;
    }
    if !(i + 1 < s.len() && s[i] == b'0' && (s[i + 1] == b'x' || s[i + 1] == b'X')) {
        return None;
    }
    i += 2;
    let mut r: f64 = 0.0;
    let mut sigdig = 0;
    let mut nosigdig = 0;
    let mut e: i64 = 0;
    let mut hasdot = false;
    let mut any = false;
    loop {
        if i < s.len() && s[i] == b'.' {
            if hasdot {
                break;
            }
            hasdot = true;
        } else if i < s.len() && s[i].is_ascii_hexdigit() {
            any = true;
            if sigdig == 0 && s[i] == b'0' {
                nosigdig += 1;
            } else {
                sigdig += 1;
                if sigdig <= 30 {
                    r = r * 16.0 + hexval(s[i]) as f64;
                } else {
                    e += 1;
                }
            }
            if hasdot {
                e -= 1;
            }
        } else {
            break;
        }
        i += 1;
    }
    let _ = nosigdig;
    if !any {
        return None;
    }
    e *= 4;
    if i < s.len() && (s[i] == b'p' || s[i] == b'P') {
        i += 1;
        let mut eneg = false;
        if i < s.len() && s[i] == b'-' {
            eneg = true;
            i += 1;
        } else if i < s.len() && s[i] == b'+' {
            i += 1;
        }
        if !(i < s.len() && s[i].is_ascii_digit()) {
            return None;
        }
        let mut exp1: i64 = 0;
        while i < s.len() && s[i].is_ascii_digit() {
            exp1 = (exp1 * 10 + (s[i] - b'0') as i64).min(1 << 40);
            i += 1;
        }
        if eneg {
            exp1 = -exp1;
        }
        e += exp1;
    }
    while i < s.len() && is_lspace(s[i]) {
        i += 1;
    }
    if i != s.len() {
        return None;
    }
    let v = r * (2f64).powi(e.clamp(-3000, 3000) as i32);
    Some(if neg { -v } else { v })
}

fn str2d(s: &[u8]) -> Option<f64> {
    if s.iter().any(|&c| c == b'n' || c == b'N') {
        return None;
    }
    let mut i = 0;
    while i < s.len() && is_lspace(s[i]) {
        i += 1;
    }
    let t = &s[i..];
    if t.iter().any(|&c| c == b'x' || c == b'X') {
        return strx2number(t);
    }
    let mut j = t.len();
    while j > 0 && is_lspace(t[j - 1]) {
        j -= 1;
    }
    let body = &t[..j];
    if body.is_empty() {
        return None;
    }
    // validate characters: digits, sign, '.', e/E
    let st = std::str::from_utf8(body).ok()?;
    // Rust parse accepts "inf"/"nan" which we excluded (n/N). Also rejects "1e" etc like strtod would (trailing junk)
    let ok = st.bytes().all(|c| c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-');
    if !ok {
        return None;
    }
    st.parse::<f64>().ok()
}

pub fn str2number(s: &[u8]) -> Option<Val> {
    if let Some(i) = str2int(s) {
        return Some(Val::Int(i));
    }
    str2d(s).map(Val::Num)
}

/// C-like %.14g formatting used by Lua for floats
pub fn fmt_g(f: f64, prec: usize, alt: bool, upper: bool) -> String {
    if f.is_nan() {
        let s = if f.is_sign_negative() { "-nan" } else { "nan" };
        return if upper { s.to_uppercase() } else { s.to_string() };
    }
    if f.is_infinite() {
        let s = if f < 0.0 { "-inf" } else { "inf" };
        return if upper { s.to_uppercase() } else { s.to_string() };
    }
    let p = if prec == 0 { 1 } else { prec };
    if f == 0.0 {
        let mut s = String::new();
        if f.is_sign_negative() {
            s.push('-');
        }
        s.push('0');
        if alt && p > 1 {
            s.push('.');
            for _ in 0..p - 1 {
                s.push('0');
            }
        }
        return s;
    }
    let es = format!("{:.*e}", p - 1, f);
    let (_, ex) = es.split_once('e').unwrap();
    let x: i32 = ex.parse().unwrap();
    let mut s;
    if (x as i64) < p as i64 && x >= -4 {
        let fp = (p as i32 - 1 - x) as usize;
        s = format!("{:.*}", fp, f);
        if !alt && s.contains('.') {
            while s.ends_with('0') {
                s.pop();
            }
            if s.ends_with('.') {
                s.pop();
            }
        }
    } else {
        let (m, _) = es.split_once('e').unwrap();
        let mut m = m.to_string();
        if !alt && m.contains('.') {
            while m.ends_with('0') {
                m.pop();
            }
            if m.ends_with('.') {
                m.pop();
            }
        }
        s = format!("{}e{}{:02}", m, if x < 0 { '-' } else { '+' }, x.abs());
    }
    if upper {
        s = s.to_uppercase();
    }
    s
}

pub fn fmt_e(f: f64, prec: usize, upper: bool) -> String {
    if !f.is_finite() {
        return fmt_g(f, 1, false, upper);
    }
    let es = format!("{:.*e}", prec, f);
    let (m, ex) = es.split_once('e').unwrap();
    let x: i32 = ex.parse().unwrap();
    let s = format!("{}e{}{:02}", m, if x < 0 { '-' } else { '+' }, x.abs());
    if upper {
        s.to_uppercase()
    } else {
        s
    }
}

pub fn number_to_str(v: &Val) -> Vec<u8> {
    match v {
        Val::Int(i) => i.to_string().into_bytes(),
        Val::Num(f) => {
            let mut s = fmt_g(*f, 14, false, false);
            if s.bytes().all(|c| c == b'-' || c.is_ascii_digit()) {
                s.push_str(".0");
            }
            s.into_bytes()
        }
        _ => Vec::new(),
    }
}
