}

const UNARY_PRIORITY: u8 = 12;

fn binop_of(t: &Tok) -> Option<(BinOp, u8, u8)> {
    Some(match t {
        Tok::Char(b'+') => (BinOp::Add, 10, 10),
        Tok::Char(b'-') => (BinOp::Sub, 10, 10),
        Tok::Char(b'*') => (BinOp::Mul, 11, 11),
        Tok::Char(b'%') => (BinOp::Mod, 11, 11),
        Tok::Char(b'^') => (BinOp::Pow, 14, 13),
        Tok::Char(b'/') => (BinOp::Div, 11, 11),
        Tok::IDiv => (BinOp::IDiv, 11, 11),
        Tok::Char(b'&') => (BinOp::BAnd, 6, 6),
        Tok::Char(b'|') => (BinOp::BOr, 4, 4),
        Tok::Char(b'~') => (BinOp::BXor, 5, 5),
        Tok::Shl => (BinOp::Shl, 7, 7),
        Tok::Shr => (BinOp::Shr, 7, 7),
        Tok::Concat => (BinOp::Concat, 9, 8),
        Tok::Eq => (BinOp::Eq, 3, 3),
        Tok::Lt | Tok::Char(b'<') => (BinOp::Lt, 3, 3),
        Tok::Le => (BinOp::Le, 3, 3),
        Tok::Ne => (BinOp::Ne, 3, 3),
        Tok::Char(b'>') => (BinOp::Gt, 3, 3),
        Tok::Ge => (BinOp::Ge, 3, 3),
        Tok::And => (BinOp::Eq, 2, 2), // placeholder handled specially
        Tok::Or => (BinOp::Eq, 1, 1),
        _ => return None,
    })
}

impl Tok {
    #[allow(non_upper_case_globals)]
    pub const Lt: Tok = Tok::Char(b'<');
}

pub fn parse_chunk(src: &[u8], chunkname: &str) -> Result<Rc<Proto>, SynErr> {
    let mut p = Parser { ls: Lexer::new(src, chunkname), fs: Vec::new(), source: Rc::from(chunkname) };
    p.main_func()
}

impl<'a> Parser<'a> {
    fn cur(&mut self) -> &mut FuncState {
        self.fs.last_mut().unwrap()
    }

    fn next(&mut self) -> PR<()> {
        self.ls.next()
    }

    fn tok(&self) -> &Tok {
        &self.ls.tok
    }

    fn is_char(&self, c: u8) -> bool {
        self.ls.tok == Tok::Char(c)
    }

    fn err(&self, msg: &str) -> SynErr {
        self.ls.syntax_error(msg)
    }

    fn error_expected(&self, t: &Tok) -> SynErr {
        self.err(&format!("{} expected", tok2str(t)))
    }

    fn check(&self, t: &Tok) -> PR<()> {
        if &self.ls.tok != t {
            return Err(self.error_expected(t));
        }
        Ok(())
    }

    fn checknext(&mut self, t: &Tok) -> PR<()> {
        self.check(t)?;
        self.next()
    }

    fn testnext(&mut self, t: &Tok) -> PR<bool> {
        if &self.ls.tok == t {
            self.next()?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn check_match(&mut self, what: &Tok, who: &Tok, where_: u32) -> PR<()> {
        if !self.testnext(what)? {
            if where_ == self.ls.linenumber {
                return Err(self.error_expected(what));
            } else {
                return Err(self.err(&format!(
                    "{} expected (to close {} at line {})",
                    tok2str(what),
                    tok2str(who),
                    where_
                )));
            }
        }
        Ok(())
    }

    fn str_checkname(&mut self) -> PR<LStr> {
        if let Tok::Name(n) = &self.ls.tok {
            let n: LStr = Rc::from(&n[..]);
            self.next()?;
            Ok(n)
        } else {
            Err(self.error_expected(&Tok::Name(Vec::new())))
        }
    }

    fn block_follow(&self, withuntil: bool) -> bool {
        match self.ls.tok {
            Tok::Else | Tok::Elseif | Tok::End | Tok::Eos => true,
            Tok::Until => withuntil,
            _ => false,
        }
    }

    fn new_local(&mut self, name: LStr, is_const: bool) -> usize {
        let fs = self.cur();
        let slot = fs.nslots;
        fs.nslots += 1;
        fs.actvars.push(VarInfo { name, slot, is_const });
        slot
    }

    fn enter_block(&mut self, is_loop: bool) {
        let fs = self.cur();
        let id = fs.next_block_id;
        fs.next_block_id += 1;
        let n = fs.actvars.len();
        fs.blocks.push(BlockScope { nactvar: n, is_loop, labels: Vec::new(), id });
    }

    fn leave_block(&mut self) {
        let fs = self.cur();
        let b = fs.blocks.pop().unwrap();
        fs.actvars.truncate(b.nactvar);
    }

    fn resolve_in(&mut self, level: usize, name: &[u8]) -> VarRes {
        // search locals
        {
            let fs = &self.fs[level];
            for v in fs.actvars.iter().rev() {
                if &v.name[..] == name {
                    return VarRes::Local(v.slot, v.is_const);
                }
            }
            for (i, u) in fs.upvals.iter().enumerate() {
                if &u.name[..] == name {
                    return VarRes::Upval(i, fs.upval_const[i]);
                }
            }
        }
        if level == 0 {
            return VarRes::Global;
        }
        match self.resolve_in(level - 1, name) {
            VarRes::Local(slot, c) => {
                let fs = &mut self.fs[level];
                fs.upvals.push(UpvalDesc { name: Rc::from(name), in_parent_local: true, idx: slot });
                fs.upval_const.push(c);
                VarRes::Upval(fs.upvals.len() - 1, c)
            }
            VarRes::Upval(idx, c) => {
                let fs = &mut self.fs[level];
                fs.upvals.push(UpvalDesc { name: Rc::from(name), in_parent_local: false, idx });
                fs.upval_const.push(c);
                VarRes::Upval(fs.upvals.len() - 1, c)
            }
            VarRes::Global => VarRes::Global,
        }
    }

    fn singlevar(&mut self, name: LStr, line: u32) -> Expr {
        let level = self.fs.len() - 1;
        match self.resolve_in(level, &name) {
            VarRes::Local(slot, _) => Expr::Local(slot, name),
            VarRes::Upval(idx, _) => Expr::Upval(idx, name),
            VarRes::Global => {
                let env = match self.resolve_in(level, b"_ENV") {
                    VarRes::Local(slot, _) => Expr::Local(slot, Rc::from(&b"_ENV"[..])),
                    VarRes::Upval(idx, _) => Expr::Upval(idx, Rc::from(&b"_ENV"[..])),
                    VarRes::Global => Expr::Nil,
                };
                Expr::Global(Box::new(env), name, line)
            }
        }
    }

    fn is_const_var(&mut self, e: &Expr) -> Option<LStr> {
        match e {
            Expr::Local(slot, name) => {
                let fs = self.fs.last().unwrap();
                for v in fs.actvars.iter().rev() {
                    if v.slot == *slot {
                        if v.is_const {
                            return Some(name.clone());
                        }
                        break;
                    }
                }
                None
            }
            Expr::Upval(idx, name) => {
                let fs = self.fs.last().unwrap();
                if fs.upval_const[*idx] {
                    Some(name.clone())
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    fn main_func(&mut self) -> PR<Rc<Proto>> {
        let mut fs = FuncState::new();
        fs.is_vararg = true;
        fs.upvals.push(UpvalDesc { name: Rc::from(&b"_ENV"[..]), in_parent_local: false, idx: 0 });
        fs.upval_const.push(false);
        self.fs.push(fs);
        self.next()?;
        self.enter_block(false);
        let body = self.statlist()?;
        self.check(&Tok::Eos)?;
        self.leave_block();
        self.close_func_checks()?;
        let fs = self.fs.pop().unwrap();
        Ok(Rc::new(Proto {
            nparams: 0,
            param_slots: Vec::new(),
            is_vararg: true,
            body,
            nslots: fs.nslots,
            upvals: fs.upvals,
            line_defined: 0,
            source: self.source.clone(),
            is_main: true,
        }))
    }

    fn close_func_checks(&mut self) -> PR<()> {
        let fs = self.fs.last().unwrap();
        for g in &fs.gotos {
            let mut found = false;
            for (bid, lname) in &fs.all_labels {
                if &lname[..] == &g.name[..] && g.blocks.contains(bid) {
                    found = true;
                    break;
                }
            }
            if !found {
                let msg = format!(
                    "{}:{}: no visible label '{}' for <goto> at line {}",
                    self.ls.chunkname,
                    self.ls.linenumber,
                    String::from_utf8_lossy(&g.name),
                    g.line
                );
                return Err(SynErr(msg));
            }
        }
        Ok(())
    }

    fn statlist(&mut self) -> PR<Block> {
        let mut stats = Vec::new();
        let mut labels = Vec::new();
        while !self.block_follow(true) {
            if self.ls.tok == Tok::Return {
                stats.push(self.statement(&mut labels, stats.len())?);
                break;
            }
            let s = self.statement(&mut labels, stats.len())?;
            stats.push(s);
        }
        Ok(Block { stats, labels })
    }

    fn block(&mut self) -> PR<Block> {
        self.enter_block(false);
        let b = self.statlist()?;
        self.leave_block();
        Ok(b)
    }

    fn statement(&mut self, labels: &mut Vec<(LStr, usize)>, idx: usize) -> PR<Stat> {
        let line = self.ls.linenumber;
        match self.ls.tok.clone() {
            Tok::Char(b';') => {
                self.next()?;
                Ok(Stat::Do(Block { stats: Vec::new(), labels: Vec::new() }))
            }
            Tok::If => self.ifstat(line),
            Tok::While => {
                self.next()?;
                let cond = self.expr()?;
                self.checknext(&Tok::Do)?;
                self.enter_block(true);
                let body = self.statlist()?;
                self.leave_block();
                self.check_match(&Tok::End, &Tok::While, line)?;
                Ok(Stat::While { cond, body, line })
            }
            Tok::Do => {
                self.next()?;
                let b = self.block()?;
                self.check_match(&Tok::End, &Tok::Do, line)?;
                Ok(Stat::Do(b))
            }
            Tok::For => self.forstat(line),
            Tok::Repeat => {
                self.next()?;
                self.enter_block(true);
                let body = self.statlist()?;
                self.check_match(&Tok::Until, &Tok::Repeat, line)?;
                let cond = self.expr()?;
                self.leave_block();
                Ok(Stat::Repeat { body, cond, line })
            }
            Tok::Function => self.funcstat(line),
            Tok::Local => {
                self.next()?;
                if self.testnext(&Tok::Function)? {
                    let name = self.str_checkname()?;
                    let slot = self.new_local(name, false);
                    let func = self.body(false, line)?;
                    Ok(Stat::LocalFunction { slot, func })
                } else {
                    self.localstat(line)
                }
            }
            Tok::DbColon => {
                self.next()?;
                let name = self.str_checkname()?;
                self.checknext(&Tok::DbColon)?;
                // check duplicate
                {
                    let fs = self.fs.last().unwrap();
                    for (_, l) in &fs.all_labels {
                        if &l[..] == &name[..] {
                            // only error if visible in the same function block chain
                        }
                    }
                }
                let fs = self.cur();
                let bid = fs.blocks.last().unwrap().id;
                for b in fs.blocks.iter() {
                    if b.labels.iter().any(|l| &l[..] == &name[..]) {
                        let msg = format!(
                            "{}:{}: label '{}' already defined",
                            self.ls.chunkname,
                            self.ls.linenumber,
                            String::from_utf8_lossy(&name)
                        );
                        return Err(SynErr(msg));
                    }
                }
                let fs = self.cur();
                fs.blocks.last_mut().unwrap().labels.push(name.clone());
                fs.all_labels.push((bid, name.clone()));
                labels.push((name, idx));
                Ok(Stat::Label)
            }
            Tok::Return => {
                self.next()?;
                let mut exprs = Vec::new();
                if !(self.block_follow(true) || self.is_char(b';')) {
                    exprs = self.explist()?;
                }
                self.testnext(&Tok::Char(b';'))?;
                Ok(Stat::Return { exprs, line })
            }
            Tok::Break => {
                self.next()?;
                let fs = self.fs.last().unwrap();
                if !fs.blocks.iter().any(|b| b.is_loop) {
                    let msg = format!("{}:{}: break outside a loop at line {}", self.ls.chunkname, self.ls.linenumber, line);
                    return Err(SynErr(msg));
                }
                Ok(Stat::Break)
            }
            Tok::Goto => {
                self.next()?;
                let name = self.str_checkname()?;
                let fs = self.cur();
                let blocks: Vec<usize> = fs.blocks.iter().map(|b| b.id).collect();
                fs.gotos.push(PendingGoto { name: name.clone(), line, blocks });
                Ok(Stat::Goto(name, line))
            }
            _ => self.exprstat(line),
        }
    }

    fn ifstat(&mut self, line: u32) -> PR<Stat> {
        let mut conds = Vec::new();
        // IF cond THEN block
        self.next()?;
        let c = self.expr()?;
        self.checknext(&Tok::Then)?;
        let b = self.block()?;
        conds.push((c, b));
        while self.ls.tok == Tok::Elseif {
            self.next()?;
            let c = self.expr()?;
            self.checknext(&Tok::Then)?;
            let b = self.block()?;
            conds.push((c, b));
        }
        let mut else_ = None;
        if self.testnext(&Tok::Else)? {
            else_ = Some(self.block()?);
        }
        self.check_match(&Tok::End, &Tok::If, line)?;
        Ok(Stat::If { conds, else_, line })
    }

    fn forstat(&mut self, line: u32) -> PR<Stat> {
        self.next()?;
        let varname = self.str_checkname()?;
        match self.ls.tok {
            Tok::Char(b'=') => {
                self.next()?;
                let start = self.expr()?;
                self.checknext(&Tok::Char(b','))?;
                let limit = self.expr()?;
                let step = if self.testnext(&Tok::Char(b','))? { Some(self.expr()?) } else { None };
                self.checknext(&Tok::Do)?;
                self.enter_block(true);
                let var = self.new_local(varname, false);
                let body = self.block()?;
                self.leave_block();
                self.check_match(&Tok::End, &Tok::For, line)?;
                Ok(Stat::NumFor { var, start, limit, step, body, line })
            }
            Tok::Char(b',') | Tok::In => {
                let mut names = vec![varname];
                while self.testnext(&Tok::Char(b','))? {
                    names.push(self.str_checkname()?);
                }
                self.checknext(&Tok::In)?;
                let exprs = self.explist()?;
                self.checknext(&Tok::Do)?;
                self.enter_block(true);
                let mut vars = Vec::new();
                for n in names {
                    vars.push(self.new_local(n, false));
                }
                let body = self.block()?;
                self.leave_block();
                self.check_match(&Tok::End, &Tok::For, line)?;
                Ok(Stat::GenFor { vars, exprs, body, line })
            }
            _ => Err(self.err("'=' or 'in' expected")),
        }
    }

    fn funcstat(&mut self, line: u32) -> PR<Stat> {
        self.next()?;
        // funcname: NAME {fieldsel} [':' NAME]
        let nline = self.ls.linenumber;
        let n = self.str_checkname()?;
        let mut target = self.singlevar(n, nline);
        let mut is_method = false;
        while self.is_char(b'.') {
            self.next()?;
            let kline = self.ls.linenumber;
            let k = self.str_checkname()?;
            target = Expr::Index(Box::new(target), Box::new(Expr::Str(k)), kline);
        }
        if self.is_char(b':') {
            self.next()?;
            let kline = self.ls.linenumber;
            let k = self.str_checkname()?;
            target = Expr::Index(Box::new(target), Box::new(Expr::Str(k)), kline);
            is_method = true;
        }
        if let Some(name) = self.is_const_var(&target) {
            return Err(SynErr(format!(
                "{}:{}: attempt to assign to const variable '{}'",
                self.ls.chunkname,
                self.ls.linenumber,
                String::from_utf8_lossy(&name)
            )));
        }
        let func = self.body(is_method, line)?;
        let lt = self.to_lexpr(target, line);
        Ok(Stat::Assign { targets: vec![lt], exprs: vec![Expr::Function(func)], line })
    }

    fn to_lexpr(&self, e: Expr, line: u32) -> LExpr {
        match e {
            Expr::Local(s, n) => LExpr::Local(s, n),
            Expr::Upval(i, n) => LExpr::Upval(i, n),
            Expr::Global(env, n, l) => LExpr::Index(*env, Expr::Str(n), l),
            Expr::Index(t, k, l) => LExpr::Index(*t, *k, l),
            _ => LExpr::Index(Expr::Nil, Expr::Nil, line),
        }
    }

    fn localstat(&mut self, line: u32) -> PR<Stat> {
        let mut names = Vec::new();
        loop {
            let name = self.str_checkname()?;
            let mut is_const = false;
            if self.testnext(&Tok::Char(b'<'))? {
                let attr = self.str_checkname()?;
                self.checknext(&Tok::Char(b'>'))?;
                match &attr[..] {
                    b"const" => is_const = true,
                    b"close" => is_const = true,
                    _ => {
                        return Err(SynErr(format!(
                            "{}:{}: unknown attribute '{}'",
                            self.ls.chunkname,
                            self.ls.linenumber,
                            String::from_utf8_lossy(&attr)
                        )));
                    }
                }
            }
            names.push((name, is_const));
            if !self.testnext(&Tok::Char(b','))? {
                break;
            }
        }
        let exprs = if self.testnext(&Tok::Char(b'='))? { self.explist()? } else { Vec::new() };
        let mut slots = Vec::new();
        for (n, c) in names {
            slots.push(self.new_local(n, c));
        }
        Ok(Stat::Local { slots, exprs, line })
    }

    fn exprstat(&mut self, line: u32) -> PR<Stat> {
        let e = self.suffixedexp()?;
        if self.is_char(b'=') || self.is_char(b',') {
            let mut targets = vec![e];
            loop {
                {
                    let last = targets.last().unwrap();
                    let isvar = matches!(last, Expr::Local(..) | Expr::Upval(..) | Expr::Global(..) | Expr::Index(..));
                    if !isvar {
                        return Err(self.err("syntax error"));
                    }
                }
                let last = targets.last().unwrap();
                if let Some(name) = self.is_const_var(last) {
                    return Err(SynErr(format!(
                        "{}:{}: attempt to assign to const variable '{}'",
                        self.ls.chunkname,
                        self.ls.linenumber,
                        String::from_utf8_lossy(&name)
                    )));
                }
                if self.testnext(&Tok::Char(b','))? {
                    let e = self.suffixedexp()?;
                    targets.push(e);
                } else {
                    self.checknext(&Tok::Char(b'='))?;
                    let exprs = self.explist()?;
                    let lts = targets.into_iter().map(|t| self.to_lexpr(t, line)).collect();
                    return Ok(Stat::Assign { targets: lts, exprs, line });
                }
            }
        } else {
            if !matches!(e, Expr::Call(..) | Expr::Method(..)) {
                return Err(self.err("syntax error"));
            }
            Ok(Stat::Call(e, line))
        }
    }

    fn explist(&mut self) -> PR<Vec<Expr>> {
        let mut v = vec![self.expr()?];
        while self.testnext(&Tok::Char(b','))? {
            v.push(self.expr()?);
        }
        Ok(v)
    }

    fn body(&mut self, is_method: bool, line: u32) -> PR<Rc<Proto>> {
        let fs = FuncState::new();
        self.fs.push(fs);
        self.enter_block(false);
        let mut param_slots = Vec::new();
        if is_method {
            param_slots.push(self.new_local(Rc::from(&b"self"[..]), false));
        }
        self.checknext(&Tok::Char(b'('))?;
        if !self.is_char(b')') {
            loop {
                match self.ls.tok.clone() {
                    Tok::Name(n) => {
                        self.next()?;
                        param_slots.push(self.new_local(Rc::from(&n[..]), false));
                    }
                    Tok::Dots => {
                        self.next()?;
                        self.cur().is_vararg = true;
                    }
                    _ => return Err(self.err("<name> or '...' expected")),
                }
                if self.cur().is_vararg || !self.testnext(&Tok::Char(b','))? {
                    break;
                }
            }
        }
        self.checknext(&Tok::Char(b')'))?;
        let body = self.statlist()?;
        self.check_match(&Tok::End, &Tok::Function, line)?;
        self.leave_block();
        self.close_func_checks()?;
        let fs = self.fs.pop().unwrap();
        Ok(Rc::new(Proto {
            nparams: param_slots.len(),
            param_slots,
            is_vararg: fs.is_vararg,
            body,
            nslots: fs.nslots,
            upvals: fs.upvals,
            line_defined: line,
            source: self.source.clone(),
            is_main: false,
        }))
    }

    fn primaryexp(&mut self) -> PR<Expr> {
        match self.ls.tok.clone() {
            Tok::Char(b'(') => {
                let line = self.ls.linenumber;
                self.next()?;
                let e = self.expr()?;
                self.check_match(&Tok::Char(b')'), &Tok::Char(b'('), line)?;
                Ok(Expr::Paren(Box::new(e)))
            }
            Tok::Name(n) => {
                let line = self.ls.linenumber;
                self.next()?;
                Ok(self.singlevar(Rc::from(&n[..]), line))
            }
            _ => Err(self.err("unexpected symbol")),
        }
    }

    fn suffixedexp(&mut self) -> PR<Expr> {
        let line = self.ls.linenumber;
        let mut e = self.primaryexp()?;
        loop {
            match self.ls.tok.clone() {
                Tok::Char(b'.') => {
                    self.next()?;
                    let kline = self.ls.linenumber;
                    let k = self.str_checkname()?;
                    e = Expr::Index(Box::new(e), Box::new(Expr::Str(k)), kline);
                }
                Tok::Char(b'[') => {
                    self.next()?;
                    let k = self.expr()?;
                    let kline = self.ls.linenumber;
                    self.checknext(&Tok::Char(b']'))?;
                    e = Expr::Index(Box::new(e), Box::new(k), kline);
                }
                Tok::Char(b':') => {
                    self.next()?;
                    let name = self.str_checkname()?;
                    let args = self.funcargs(line)?;
                    e = Expr::Method(Box::new(e), name, args, line);
                }
                Tok::Char(b'(') | Tok::Str(_) | Tok::Char(b'{') => {
                    let args = self.funcargs(line)?;
                    e = Expr::Call(Box::new(e), args, line);
                }
                _ => return Ok(e),
            }
        }
    }

    fn funcargs(&mut self, line: u32) -> PR<Vec<Expr>> {
        match self.ls.tok.clone() {
            Tok::Char(b'(') => {
                self.next()?;
                let args = if self.is_char(b')') { Vec::new() } else { self.explist()? };
                self.check_match(&Tok::Char(b')'), &Tok::Char(b'('), line)?;
                Ok(args)
            }
            Tok::Char(b'{') => Ok(vec![self.constructor()?]),
            Tok::Str(s) => {
                self.next()?;
                Ok(vec![Expr::Str(Rc::from(&s[..]))])
            }
            _ => Err(self.err("function arguments expected")),
        }
    }

    fn constructor(&mut self) -> PR<Expr> {
        let line = self.ls.linenumber;
        self.checknext(&Tok::Char(b'{'))?;
        let mut fields = Vec::new();
        loop {
            if self.is_char(b'}') {
                break;
            }
            // field
            match self.ls.tok.clone() {
                Tok::Name(n) => {
                    let la = self.ls.lookahead()?;
                    if la != Tok::Char(b'=') {
                        fields.push(TField::Pos(self.expr()?));
                    } else {
                        self.next()?; // name
                        self.next()?; // '='
                        let v = self.expr()?;
                        fields.push(TField::Named(Expr::Str(Rc::from(&n[..])), v));
                    }
                }
                Tok::Char(b'[') => {
                    self.next()?;
                    let k = self.expr()?;
                    self.checknext(&Tok::Char(b']'))?;
                    self.checknext(&Tok::Char(b'='))?;
                    let v = self.expr()?;
                    fields.push(TField::Named(k, v));
                }
                _ => {
                    fields.push(TField::Pos(self.expr()?));
                }
            }
            if !(self.testnext(&Tok::Char(b','))? || self.testnext(&Tok::Char(b';'))?) {
                break;
            }
        }
        self.check_match(&Tok::Char(b'}'), &Tok::Char(b'{'), line)?;
        Ok(Expr::Table(fields, line))
    }

    fn simpleexp(&mut self) -> PR<Expr> {
        let e = match self.ls.tok.clone() {
            Tok::Flt(f) => Expr::Num(f),
            Tok::Int(i) => Expr::Int(i),
            Tok::Str(s) => Expr::Str(Rc::from(&s[..])),
            Tok::Nil => Expr::Nil,
            Tok::True => Expr::True,
            Tok::False => Expr::False,
            Tok::Dots => {
                if !self.fs.last().unwrap().is_vararg {
                    return Err(self.err("cannot use '...' outside a vararg function"));
                }
                Expr::Dots
            }
            Tok::Char(b'{') => return self.constructor(),
            Tok::Function => {
                let line = self.ls.linenumber;
                self.next()?;
                let p = self.body(false, line)?;
                return Ok(Expr::Function(p));
            }
            _ => return self.suffixedexp(),
        };
        self.next()?;
        Ok(e)
    }

    pub fn expr(&mut self) -> PR<Expr> {
        self.subexpr(0)
    }

    fn subexpr(&mut self, limit: u8) -> PR<Expr> {
        let uop = match self.ls.tok {
            Tok::Not => Some(UnOp::Not),
            Tok::Char(b'-') => Some(UnOp::Neg),
            Tok::Char(b'~') => Some(UnOp::BNot),
            Tok::Char(b'#') => Some(UnOp::Len),
            _ => None,
        };
        let mut e = if let Some(op) = uop {
            let line = self.ls.linenumber;
            self.next()?;
            let operand = self.subexpr(UNARY_PRIORITY)?;
            fold_unary(op, operand, line)
        } else {
            self.simpleexp()?
        };
        loop {
            let tok = self.ls.tok.clone();
            let info = binop_of(&tok);
            let (op, lp, rp) = match info {
                Some(x) => x,
                None => break,
            };
            if lp <= limit {
                break;
            }
            let line = self.ls.linenumber;
            self.next()?;
            let rhs = self.subexpr(rp)?;
            e = match tok {
                Tok::And => Expr::And(Box::new(e), Box::new(rhs)),
                Tok::Or => Expr::Or(Box::new(e), Box::new(rhs)),
                _ => Expr::Bin(op, Box::new(e), Box::new(rhs), line),
            };
        }
        Ok(e)
    }
}

fn fold_unary(op: UnOp, e: Expr, line: u32) -> Expr {
    match (op, &e) {
        (UnOp::Neg, Expr::Int(i)) => Expr::Int(i.wrapping_neg()),
        (UnOp::Neg, Expr::Num(f)) => Expr::Num(-f),
        _ => Expr::Un(op, Box::new(e), line),
    }
}
EOF"}

