// Tree-walking Lua 5.4 interpreter core
use std::cell::RefCell;
use std::rc::Rc;

use super::ast::*;
use super::value::*;

pub type CallName = Option<(&'static str, Vec<u8>)>;

pub struct FrameInfo {
    pub func: Val,
    pub lua: Option<Rc<Proto>>,
    pub line: u32,
    pub call_name: CallName,
    pub tail: bool,
}

pub struct Interp {
    pub globals: TableRef,
    pub string_mt: Option<TableRef>,
    pub loaded: TableRef,
    pub frames: Vec<FrameInfo>,
    pub pcall_depth: usize,
    pub depth: usize,
    pub out: Vec<u8>,
}

struct Frame<'a> {
    slots: Vec<Option<Rc<RefCell<Val>>>>,
    varargs: Vec<Val>,
    upvals: &'a [Rc<RefCell<Val>>],
}

enum Flow {
    Normal,
    Break,
    Return(Vec<Val>),
    Goto(LStr),
    Tail(Val, Vec<Val>, CallName),
}

pub type LResult<T> = Result<T, LuaError>;

const MAX_DEPTH: usize = 190;

fn lstr(v: &[u8]) -> String {
    String::from_utf8_lossy(v).into_owned()
}

/// variable info for error messages
fn varinfo(e: &Expr) -> String {
    match e {
        Expr::Global(_, n, _) => format!(" (global '{}')", lstr(n)),
        Expr::Local(_, n) => format!(" (local '{}')", lstr(n)),
        Expr::Upval(_, n) => format!(" (upvalue '{}')", lstr(n)),
        Expr::Str(s) => format!(" (constant '{}')", lstr(s)),
        Expr::Index(t, k, _) => {
            let is_env = matches!(&**t, Expr::Local(_, n) | Expr::Upval(_, n) if &n[..] == b"_ENV");
            let what = if is_env { "global" } else { "field" };
            match &**k {
                Expr::Str(s) => format!(" ({} '{}')", what, lstr(s)),
                Expr::Int(i) if *i >= 0 && *i <= 255 => " (field 'integer index')".to_string(),
                _ => format!(" ({} '?')", what),
            }
        }
        Expr::Paren(inner) => varinfo(inner),
        _ => String::new(),
    }
}

fn callname_of(e: &Expr) -> CallName {
    match e {
        Expr::Global(_, n, _) => Some(("global", n.to_vec())),
        Expr::Local(_, n) => Some(("local", n.to_vec())),
        Expr::Upval(_, n) => Some(("upvalue", n.to_vec())),
        Expr::Str(s) => Some(("constant", s.to_vec())),
        Expr::Index(t, k, _) => {
            let is_env = matches!(&**t, Expr::Local(_, n) | Expr::Upval(_, n) if &n[..] == b"_ENV");
            let what = if is_env { "global" } else { "field" };
            match &**k {
                Expr::Str(s) => Some((what, s.to_vec())),
                Expr::Int(i) if *i >= 0 && *i <= 255 => Some(("field", b"integer index".to_vec())),
                _ => Some((what, b"?".to_vec())),
            }
        }
        Expr::Paren(inner) => callname_of(inner),
        _ => None,
    }
}

fn binop_event(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "add",
        BinOp::Sub => "sub",
        BinOp::Mul => "mul",
        BinOp::Div => "div",
        BinOp::IDiv => "idiv",
        BinOp::Mod => "mod",
        BinOp::Pow => "pow",
        BinOp::Concat => "concat",
        BinOp::BAnd => "band",
        BinOp::BOr => "bor",
        BinOp::BXor => "bxor",
        BinOp::Shl => "shl",
        BinOp::Shr => "shr",
        BinOp::Eq | BinOp::Ne => "eq",
        BinOp::Lt | BinOp::Gt => "lt",
        BinOp::Le | BinOp::Ge => "le",
    }
}

pub fn tointeger(v: &Val) -> Option<i64> {
    match v {
        Val::Int(i) => Some(*i),
        Val::Num(f) => float_to_int_exact(*f),
        Val::Str(s) => match str2number(s) {
            Some(Val::Int(i)) => Some(i),
            Some(Val::Num(f)) => float_to_int_exact(f),
            _ => None,
        },
        _ => None,
    }
}

pub fn tonumber(v: &Val) -> Option<Val> {
    match v {
        Val::Int(_) | Val::Num(_) => Some(v.clone()),
        Val::Str(s) => str2number(s),
        _ => None,
    }
}

pub fn tofloat(v: &Val) -> Option<f64> {
    match v {
        Val::Int(i) => Some(*i as f64),
        Val::Num(f) => Some(*f),
        _ => None,
    }
}

fn lua_imod(a: i64, b: i64) -> i64 {
    let m = a.wrapping_rem(b);
    if m != 0 && (m ^ b) < 0 {
        m + b
    } else {
        m
    }
}

fn lua_idiv(a: i64, b: i64) -> i64 {
    if b == -1 {
        return a.wrapping_neg();
    }
    let q = a / b;
    if (a % b != 0) && ((a ^ b) < 0) {
        q - 1
    } else {
        q
    }
}

fn lua_fmod(a: f64, b: f64) -> f64 {
    let m = a % b;
    if (m > 0.0 && b < 0.0) || (m < 0.0 && b > 0.0) {
        m + b
    } else {
        m
    }
}

fn shift_left(x: i64, y: i64) -> i64 {
    if y <= -64 || y >= 64 {
        0
    } else if y >= 0 {
        ((x as u64) << y) as i64
    } else {
        ((x as u64) >> (-y)) as i64
    }
}

pub fn arith_raw(op: BinOp, a: &Val, b: &Val) -> Option<Val> {
    // both must be numbers already
    match op {
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Mod | BinOp::IDiv => {
            if let (Val::Int(x), Val::Int(y)) = (a, b) {
                return Some(Val::Int(match op {
                    BinOp::Add => x.wrapping_add(*y),
                    BinOp::Sub => x.wrapping_sub(*y),
                    BinOp::Mul => x.wrapping_mul(*y),
                    BinOp::Mod => {
                        if *y == 0 {
                            return None;
                        }
                        lua_imod(*x, *y)
                    }
                    BinOp::IDiv => {
                        if *y == 0 {
                            return None;
                        }
                        lua_idiv(*x, *y)
                    }
                    _ => unreachable!(),
                }));
            }
            let x = tofloat(a)?;
            let y = tofloat(b)?;
            Some(Val::Num(match op {
                BinOp::Add => x + y,
                BinOp::Sub => x - y,
                BinOp::Mul => x * y,
                BinOp::Mod => {
                    if y.is_infinite() && x.is_finite() {
                        if (x >= 0.0) == (y > 0.0) {
                            x
                        } else {
                            y
                        }
                    } else {
                        lua_fmod(x, y)
                    }
                }
                BinOp::IDiv => (x / y).floor(),
                _ => unreachable!(),
            }))
        }
        BinOp::Div => Some(Val::Num(tofloat(a)? / tofloat(b)?)),
        BinOp::Pow => {
            let x = tofloat(a)?;
            let y = tofloat(b)?;
            Some(Val::Num(if y == 2.0 { x * x } else { x.powf(y) }))
        }
        _ => None,
    }
}

impl Interp {
    pub fn new() -> Interp {
        Interp {
            globals: Table::new_ref(),
            string_mt: None,
            loaded: Table::new_ref(),
            frames: Vec::new(),
            pcall_depth: 0,
            depth: 0,
            out: Vec::new(),
        }
    }

    // ---------- error helpers ----------

    fn cur_lua_where(&self) -> String {
        if let Some(fi) = self.frames.last() {
            if let Some(p) = &fi.lua {
                return format!("{}:{}: ", p.source, fi.line);
            }
        }
        String::new()
    }

    /// position info for level (1 = caller of current native function)
    pub fn where_level(&self, level: usize) -> String {
        if self.frames.len() < level + 1 {
            return String::new();
        }
        let fi = &self.frames[self.frames.len() - 1 - level];
        if let Some(p) = &fi.lua {
            if fi.line > 0 {
                return format!("{}:{}: ", p.source, fi.line);
            }
        }
        String::new()
    }

    pub fn global_func_name(&self, f: &Val) -> Option<String> {
        if !matches!(f, Val::Func(_)) {
            return None;
        }
        let loaded = self.loaded.borrow();
        let mut k = Val::Nil;
        while let Ok(Some((key, v))) = loaded.next(&k) {
            k = key.clone();
            if let Val::Str(ks) = &key {
                if v.raw_eq(f) {
                    let name = lstr(ks);
                    return Some(name.strip_prefix("_G.").map(|s| s.to_string()).unwrap_or(name));
                }
                if let Val::Table(t) = &v {
                    let t = t.borrow();
                    let mut k2 = Val::Nil;
                    while let Ok(Some((key2, v2))) = t.next(&k2) {
                        k2 = key2.clone();
                        if let Val::Str(ks2) = &key2 {
                            if v2.raw_eq(f) {
                                let name = format!("{}.{}", lstr(ks), lstr(ks2));
                                return Some(name.strip_prefix("_G.").map(|s| s.to_string()).unwrap_or(name));
                            }
                        }
                    }
                }
            }
        }
        None
    }

    fn describe_frame(&self, fi: &FrameInfo) -> String {
        let mut s = match &fi.lua {
            None => "\n\t[C]: in ".to_string(),
            Some(p) => format!("\n\t{}:{}: in ", p.source, fi.line),
        };
        if let Some(gn) = self.global_func_name(&fi.func) {
            s.push_str(&format!("function '{}'", gn));
        } else if let Some((w, n)) = &fi.call_name {
            s.push_str(&format!("{} '{}'", w, lstr(n)));
        } else if let Some(p) = &fi.lua {
            if p.is_main {
                s.push_str("main chunk");
            } else {
                s.push_str(&format!("function <{}:{}>", p.source, p.line_defined));
            }
        } else {
            s.push('?');
        }
        if fi.tail {
            s.push_str("\n\t(...tail calls...)");
        }
        s
    }

    pub fn traceback(&self, handler: &str) -> String {
        let mut levels: Vec<String> = Vec::new();
        levels.push(format!("\n\t[C]: in {}", handler));
        for fi in self.frames.iter().rev() {
            levels.push(self.describe_frame(fi));
        }
        let mut out = String::from("stack traceback:");
        let last = levels.len() as i64 - 1;
        let mut limit2show: i64 = if last > 21 { 10 } else { -1 };
        let mut level: i64 = 0;
        while level <= last {
            let cur = level;
            level += 1;
            if limit2show == 0 {
                let n = last - level - 11 + 1;
                out.push_str(&format!("\n\t...\t(skipping {} levels)", n));
                level += n;
                limit2show -= 1;
                continue;
            }
            limit2show -= 1;
            out.push_str(&levels[cur as usize]);
        }
        out
    }

    fn make_err(&self, value: Val, handler: &str) -> LuaError {
        let tb = if self.pcall_depth == 0 { Some(self.traceback(handler)) } else { None };
        LuaError::Runtime { value, traceback: tb }
    }

    /// runtime error raised by the VM in the current Lua frame
    fn vm_error(&mut self, msg: String, line: u32, handler: &str) -> LuaError {
        if let Some(fi) = self.frames.last_mut() {
            fi.line = line;
        }
        let m = format!("{}{}", self.cur_lua_where(), msg);
        self.make_err(Val::str(&m), handler)
    }

    /// luaL_error from a native function
    pub fn error_native(&mut self, msg: &str) -> LuaError {
        let m = format!("{}{}", self.where_level(1), msg);
        self.make_err(Val::str(&m), "?")
    }

    pub fn error_value(&mut self, v: Val) -> LuaError {
        self.make_err(v, "?")
    }

    pub fn arg_error(&mut self, arg: usize, extramsg: &str) -> LuaError {
        let mut arg = arg;
        let (cn, func) = match self.frames.last() {
            Some(fi) => (fi.call_name.clone(), fi.func.clone()),
            None => (None, Val::Nil),
        };
        if let Some((w, n)) = &cn {
            if *w == "method" {
                arg -= 1;
                if arg == 0 {
                    let m = format!("calling '{}' on bad self ({})", lstr(n), extramsg);
                    return self.error_native(&m);
                }
            }
        }
        let name = match &cn {
            Some((_, n)) => lstr(n),
            None => self.global_func_name(&func).unwrap_or_else(|| "?".to_string()),
        };
        let m = format!("bad argument #{} to '{}' ({})", arg, name, extramsg);
        self.error_native(&m)
    }

    pub fn typename_of(&self, v: &Val) -> String {
        if let Val::Table(t) = v {
            if let Some(mt) = &t.borrow().meta {
                if let Val::Str(s) = mt.borrow().get_str("__name") {
                    return lstr(&s);
                }
            }
        }
        v.type_name().to_string()
    }

    pub fn type_error(&mut self, arg: usize, expected: &str, got: Option<&Val>) -> LuaError {
        let tn = match got {
            None => "no value".to_string(),
            Some(v) => self.typename_of(v),
        };
        let msg = format!("{} expected, got {}", expected, tn);
        self.arg_error(arg, &msg)
    }

    // ---------- metatables ----------

    pub fn get_metatable(&self, v: &Val) -> Option<TableRef> {
        match v {
            Val::Table(t) => t.borrow().meta.clone(),
            Val::Str(_) => self.string_mt.clone(),
            _ => None,
        }
    }

    pub fn get_metamethod(&self, v: &Val, name: &str) -> Val {
        match self.get_metatable(v) {
            Some(mt) => mt.borrow().get_str(name),
            None => Val::Nil,
        }
    }

    // ---------- calls ----------

    pub fn call(&mut self, f: &Val, args: Vec<Val>, cname: CallName) -> LResult<Vec<Val>> {
        match f {
            Val::Func(func) => {
                let func = func.clone();
                match &*func {
                    Func::Native { f: nf, .. } => {
                        if self.depth >= MAX_DEPTH {
                            return Err(self.error_native("stack overflow"));
                        }
                        self.depth += 1;
                        let saved = self.frames.len();
                        self.frames.push(FrameInfo { func: Val::Func(func.clone()), lua: None, line: 0, call_name: cname, tail: false });
                        let nf = nf.clone();
                        let r = nf(self, args);
                        self.frames.truncate(saved);
                        self.depth -= 1;
                        r
                    }
                    Func::Lua { .. } => self.call_lua(func, args, cname),
                }
            }
            _ => {
                let mm = self.get_metamethod(f, "__call");
                if !mm.is_nil() {
                    let mut a = Vec::with_capacity(args.len() + 1);
                    a.push(f.clone());
                    a.extend(args);
                    return self.call(&mm, a, cname);
                }
                let extra = match &cname {
                    Some((w, n)) => format!(" ({} '{}')", w, lstr(n)),
                    None => String::new(),
                };
                let tn = self.typename_of(f);
                let msg = format!("attempt to call a {} value{}", tn, extra);
                let handler = match &cname {
                    Some((w, n)) => format!("{} '{}'", w, lstr(n)),
                    None => "?".to_string(),
                };
                let line = self.frames.last().map(|f| f.line).unwrap_or(0);
                Err(self.vm_error(msg, line, &handler))
            }
        }
    }

    fn call_lua(&mut self, func: Rc<Func>, args: Vec<Val>, cname: CallName) -> LResult<Vec<Val>> {
        if self.depth >= MAX_DEPTH {
            let line = self.frames.last().map(|f| f.line).unwrap_or(0);
            return Err(self.vm_error("stack overflow".to_string(), line, "?"));
        }
        self.depth += 1;
        let saved = self.frames.len();
        let mut func = func;
        let mut args = args;
        let mut cname = cname;
        let mut tail = false;
        let result;
        loop {
            let (proto, upvals) = match &*func {
                Func::Lua { proto, upvals } => (proto.clone(), upvals.clone()),
                _ => unreachable!(),
            };
            self.frames.push(FrameInfo {
                func: Val::Func(func.clone()),
                lua: Some(proto.clone()),
                line: proto.line_defined,
                call_name: cname.take(),
                tail,
            });
            let mut fr = Frame { slots: vec![None; proto.nslots], varargs: Vec::new(), upvals: &upvals };
            let mut it = args.into_iter();
            for &s in &proto.param_slots {
                fr.slots[s] = Some(Rc::new(RefCell::new(it.next().unwrap_or(Val::Nil))));
            }
            if proto.is_vararg {
                fr.varargs = it.collect();
            }
            let r = self.exec_block(&proto.body, &mut fr);
            match r {
                Err(e) => {
                    result = Err(e);
                    break;
                }
                Ok(Flow::Return(v)) => {
                    result = Ok(v);
                    break;
                }
                Ok(Flow::Tail(f, a, _cn)) => {
                    // replace frame
                    self.frames.pop();
                    if let Val::Func(nf) = &f {
                        if let Func::Lua { .. } = &**nf {
                            func = nf.clone();
                            args = a;
                            tail = true;
                            continue;
                        }
                    }
                    unreachable!();
                }
                Ok(_) => {
                    result = Ok(Vec::new());
                    break;
                }
            }
        }
        self.frames.truncate(saved);
        self.depth -= 1;
        result
    }

    fn set_line(&mut self, line: u32) {
        if let Some(fi) = self.frames.last_mut() {
            fi.line = line;
        }
    }

    // ---------- statements ----------

    fn exec_block(&mut self, b: &Block, fr: &mut Frame) -> LResult<Flow> {
        let mut i = 0;
        let n = b.stats.len();
        while i < n {
            let f = self.exec_stat(&b.stats[i], fr)?;
            match f {
                Flow::Normal => i += 1,
                Flow::Goto(name) => {
                    if let Some((_, idx)) = b.labels.iter().find(|(l, _)| &l[..] == &name[..]) {
                        i = *idx + 1;
                    } else {
                        return Ok(Flow::Goto(name));
                    }
                }
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_loop_body(&mut self, b: &Block, fr: &mut Frame) -> LResult<Option<Flow>> {
        // returns Some(flow) if loop must exit with that flow; None to continue
        match self.exec_block(b, fr)? {
            Flow::Normal => Ok(None),
            Flow::Break => Ok(Some(Flow::Normal)),
            other => Ok(Some(other)),
        }
    }

    fn exec_stat(&mut self, s: &Stat, fr: &mut Frame) -> LResult<Flow> {
        match s {
            Stat::Local { slots, exprs, line } => {
                self.set_line(*line);
                if slots.len() == 1 && exprs.len() == 1 {
                    let v = self.eval(&exprs[0], fr)?;
                    fr.slots[slots[0]] = Some(Rc::new(RefCell::new(v)));
                    return Ok(Flow::Normal);
                }
                let vals = self.eval_list(exprs, fr)?;
                let mut it = vals.into_iter();
                for &sl in slots {
                    fr.slots[sl] = Some(Rc::new(RefCell::new(it.next().unwrap_or(Val::Nil))));
                }
                Ok(Flow::Normal)
            }
            Stat::Assign { targets, exprs, line } => {
                self.set_line(*line);
                if targets.len() == 1 && exprs.len() == 1 {
                    match &targets[0] {
                        LExpr::Local(sl, _) => {
                            let v = self.eval(&exprs[0], fr)?;
                            *fr.slots[*sl].as_ref().unwrap().borrow_mut() = v;
                        }
                        LExpr::Upval(i, _) => {
                            let v = self.eval(&exprs[0], fr)?;
                            *fr.upvals[*i].borrow_mut() = v;
                        }
                        LExpr::Index(t, k, l) => {
                            let tv = self.eval(t, fr)?;
                            let kv = self.eval(k, fr)?;
                            let v = self.eval(&exprs[0], fr)?;
                            self.setindex(tv, kv, v, t, *l)?;
                        }
                    }
                    return Ok(Flow::Normal);
                }
                // evaluate target refs
                let mut refs: Vec<(Val, Val)> = Vec::new();
                for t in targets {
                    if let LExpr::Index(te, ke, _) = t {
                        let tv = self.eval(te, fr)?;
                        let kv = self.eval(ke, fr)?;
                        refs.push((tv, kv));
                    } else {
                        refs.push((Val::Nil, Val::Nil));
                    }
                }
                let mut vals = self.eval_list(exprs, fr)?;
                vals.resize(targets.len(), Val::Nil);
                for (i, t) in targets.iter().enumerate().rev() {
                    let v = vals[i].clone();
                    match t {
                        LExpr::Local(sl, _) => {
                            *fr.slots[*sl].as_ref().unwrap().borrow_mut() = v;
                        }
                        LExpr::Upval(ui, _) => {
                            *fr.upvals[*ui].borrow_mut() = v;
                        }
                        LExpr::Index(te, _, l) => {
                            let (tv, kv) = refs[i].clone();
                            self.setindex(tv, kv, v, te, *l)?;
                        }
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::Call(e, line) => {
                self.set_line(*line);
                self.eval_multi(e, fr)?;
                Ok(Flow::Normal)
            }
            Stat::Do(b) => self.exec_block(b, fr),
            Stat::While { cond, body, line } => {
                loop {
                    self.set_line(*line);
                    if !self.eval(cond, fr)?.truthy() {
                        break;
                    }
                    if let Some(f) = self.exec_loop_body(body, fr)? {
                        return Ok(f);
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::Repeat { body, cond, line } => {
                loop {
                    if let Some(f) = self.exec_loop_body(body, fr)? {
                        return Ok(f);
                    }
                    self.set_line(*line);
                    if self.eval(cond, fr)?.truthy() {
                        break;
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::If { conds, else_, line } => {
                self.set_line(*line);
                for (c, b) in conds {
                    if self.eval(c, fr)?.truthy() {
                        return self.exec_block(b, fr);
                    }
                }
                if let Some(b) = else_ {
                    return self.exec_block(b, fr);
                }
                Ok(Flow::Normal)
            }
            Stat::NumFor { var, start, limit, step, body, line } => {
                self.set_line(*line);
                let v0 = self.eval(start, fr)?;
                let vl = self.eval(limit, fr)?;
                let vs = match step {
                    Some(e) => self.eval(e, fr)?,
                    None => Val::Int(1),
                };
                self.set_line(*line);
                if let (Val::Int(init), Val::Int(stp)) = (&v0, &vs) {
                    let init = *init;
                    let stp = *stp;
                    if stp == 0 {
                        return Err(self.vm_error("'for' step is zero".into(), *line, "?"));
                    }
                    // forlimit
                    let lim: i64;
                    match &vl {
                        Val::Int(l) => lim = *l,
                        _ => {
                            let fl = match &vl {
                                Val::Num(f) => Some(*f),
                                Val::Str(s) => match str2number(s) {
                                    Some(Val::Int(i)) => Some(i as f64),
                                    Some(Val::Num(f)) => Some(f),
                                    _ => None,
                                },
                                _ => None,
                            };
                            let fl = match fl {
                                Some(f) => f,
                                None => return Err(self.vm_error("'for' limit must be a number".into(), *line, "?")),
                            };
                            if fl.is_nan() {
                                return Ok(Flow::Normal);
                            }
                            let r = if stp < 0 { fl.ceil() } else { fl.floor() };
                            if r >= 9223372036854775808.0 {
                                if stp < 0 {
                                    return Ok(Flow::Normal);
                                }
                                lim = i64::MAX;
                            } else if r < -9223372036854775808.0 {
                                if stp > 0 {
                                    return Ok(Flow::Normal);
                                }
                                lim = i64::MIN;
                            } else {
                                lim = r as i64;
                            }
                        }
                    }
                    if if stp > 0 { init > lim } else { init < lim } {
                        return Ok(Flow::Normal);
                    }
                    let mut count: u64 = if stp > 0 {
                        let c = (lim as u64).wrapping_sub(init as u64);
                        if stp != 1 {
                            c / (stp as u64)
                        } else {
                            c
                        }
                    } else {
                        let c = (init as u64).wrapping_sub(lim as u64);
                        c / ((-(stp + 1)) as u64 + 1)
                    };
                    let mut i = init;
                    loop {
                        fr.slots[*var] = Some(Rc::new(RefCell::new(Val::Int(i))));
                        if let Some(f) = self.exec_loop_body(body, fr)? {
                            return Ok(f);
                        }
                        if count == 0 {
                            break;
                        }
                        count -= 1;
                        i = i.wrapping_add(stp);
                    }
                    return Ok(Flow::Normal);
                }
                let tofl = |v: &Val| -> Option<f64> {
                    match v {
                        Val::Int(i) => Some(*i as f64),
                        Val::Num(f) => Some(*f),
                        Val::Str(s) => match str2number(s) {
                            Some(Val::Int(i)) => Some(i as f64),
                            Some(Val::Num(f)) => Some(f),
                            _ => None,
                        },
                        _ => None,
                    }
                };
                let fl = match tofl(&vl) {
                    Some(f) => f,
                    None => return Err(self.vm_error("'for' limit must be a number".into(), *line, "?")),
                };
                let fs = match tofl(&vs) {
                    Some(f) => f,
                    None => return Err(self.vm_error("'for' step must be a number".into(), *line, "?")),
                };
                let fi = match tofl(&v0) {
                    Some(f) => f,
                    None => return Err(self.vm_error("'for' initial value must be a number".into(), *line, "?")),
                };
                if fs == 0.0 {
                    return Err(self.vm_error("'for' step is zero".into(), *line, "?"));
                }
                let mut i = fi;
                loop {
                    if if fs > 0.0 { i > fl } else { i < fl } {
                        break;
                    }
                    if i.is_nan() || fl.is_nan() {
                        break;
                    }
                    fr.slots[*var] = Some(Rc::new(RefCell::new(Val::Num(i))));
                    if let Some(f) = self.exec_loop_body(body, fr)? {
                        return Ok(f);
                    }
                    i += fs;
                }
                Ok(Flow::Normal)
            }
            Stat::GenFor { vars, exprs, body, line } => {
                self.set_line(*line);
                let mut vals = self.eval_list(exprs, fr)?;
                vals.resize(3, Val::Nil);
                let f = vals[0].clone();
                let st = vals[1].clone();
                let mut ctrl = vals[2].clone();
                loop {
                    self.set_line(*line);
                    let r = self.call(&f, vec![st.clone(), ctrl.clone()], Some(("for iterator", b"for iterator".to_vec())))?;
                    let first = r.first().cloned().unwrap_or(Val::Nil);
                    if first.is_nil() {
                        break;
                    }
                    ctrl = first;
                    let mut it = r.into_iter();
                    for &v in vars {
                        fr.slots[v] = Some(Rc::new(RefCell::new(it.next().unwrap_or(Val::Nil))));
                    }
                    if let Some(fl) = self.exec_loop_body(body, fr)? {
                        return Ok(fl);
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::LocalFunction { slot, func } => {
                let cell = Rc::new(RefCell::new(Val::Nil));
                fr.slots[*slot] = Some(cell.clone());
                let c = self.make_closure(func, fr);
                *cell.borrow_mut() = c;
                Ok(Flow::Normal)
            }
            Stat::Return { exprs, line } => {
                self.set_line(*line);
                if exprs.len() == 1 {
                    match &exprs[0] {
                        Expr::Call(fe, args, cline) => {
                            let fv = self.eval(fe, fr)?;
                            let a = self.eval_list(args, fr)?;
                            return self.tail_or_call(fv, a, callname_of(fe), *cline);
                        }
                        Expr::Method(oe, name, args, cline) => {
                            let ov = self.eval(oe, fr)?;
                            let fv = self.index(ov.clone(), Val::bytes(name), oe, *cline)?;
                            let mut a = vec![ov];
                            a.extend(self.eval_list(args, fr)?);
                            return self.tail_or_call(fv, a, Some(("method", name.to_vec())), *cline);
                        }
                        _ => {}
                    }
                }
                let v = self.eval_list(exprs, fr)?;
                Ok(Flow::Return(v))
            }
            Stat::Break => Ok(Flow::Break),
            Stat::Goto(name, _) => Ok(Flow::Goto(name.clone())),
            Stat::Label => Ok(Flow::Normal),
        }
    }

    fn tail_or_call(&mut self, fv: Val, args: Vec<Val>, cn: CallName, line: u32) -> LResult<Flow> {
        self.set_line(line);
        // resolve __call for non-functions
        let mut fv = fv;
        let mut args = args;
        if !matches!(fv, Val::Func(_)) {
            let mm = self.get_metamethod(&fv, "__call");
            if !mm.is_nil() {
                let mut a = vec![fv.clone()];
                a.extend(args);
                args = a;
                fv = mm;
            }
        }
        if let Val::Func(f) = &fv {
            if let Func::Lua { .. } = &**f {
                return Ok(Flow::Tail(fv.clone(), args, cn));
            }
        }
        let r = self.call(&fv, args, cn)?;
        Ok(Flow::Return(r))
    }

    fn make_closure(&mut self, p: &Rc<Proto>, fr: &Frame) -> Val {
        let mut ups = Vec::with_capacity(p.upvals.len());
        for u in &p.upvals {
            if u.in_parent_local {
                let cell = match &fr.slots[u.idx] {
                    Some(c) => c.clone(),
                    None => Rc::new(RefCell::new(Val::Nil)),
                };
                ups.push(cell);
            } else {
                ups.push(fr.upvals[u.idx].clone());
            }
        }
        Val::Func(Rc::new(Func::Lua { proto: p.clone(), upvals: ups }))
    }

    // ---------- expressions ----------

    fn eval_list(&mut self, es: &[Expr], fr: &mut Frame) -> LResult<Vec<Val>> {
        let mut out = Vec::with_capacity(es.len());
        for (i, e) in es.iter().enumerate() {
            if i + 1 == es.len() && e.is_multi() {
                let vs = self.eval_multi(e, fr)?;
                out.extend(vs);
            } else {
                out.push(self.eval(e, fr)?);
            }
        }
        Ok(out)
    }

    fn eval_multi(&mut self, e: &Expr, fr: &mut Frame) -> LResult<Vec<Val>> {
        match e {
            Expr::Call(fe, args, line) => {
                let fv = self.eval(fe, fr)?;
                let a = self.eval_list(args, fr)?;
                self.set_line(*line);
                self.call(&fv, a, callname_of(fe))
            }
            Expr::Method(oe, name, args, line) => {
                let ov = self.eval(oe, fr)?;
                let fv = self.index(ov.clone(), Val::bytes(name), oe, *line)?;
                let mut a = vec![ov];
                a.extend(self.eval_list(args, fr)?);
                self.set_line(*line);
                self.call(&fv, a, Some(("method", name.to_vec())))
            }
            Expr::Dots => Ok(fr.varargs.clone()),
            _ => Ok(vec![self.eval(e, fr)?]),
        }
    }

    fn eval(&mut self, e: &Expr, fr: &mut Frame) -> LResult<Val> {
        match e {
            Expr::Nil => Ok(Val::Nil),
            Expr::True => Ok(Val::Bool(true)),
            Expr::False => Ok(Val::Bool(false)),
            Expr::Int(i) => Ok(Val::Int(*i)),
            Expr::Num(f) => Ok(Val::Num(*f)),
            Expr::Str(s) => Ok(Val::Str(s.clone())),
            Expr::Dots => Ok(fr.varargs.first().cloned().unwrap_or(Val::Nil)),
            Expr::Local(s, _) => Ok(match &fr.slots[*s] {
                Some(c) => c.borrow().clone(),
                None => Val::Nil,
            }),
            Expr::Upval(i, _) => Ok(fr.upvals[*i].borrow().clone()),
            Expr::Global(env, name, line) => {
                let ev = self.eval(env, fr)?;
                if let Val::Table(t) = &ev {
                    let v = t.borrow().get(&Val::Str(name.clone()));
                    if !v.is_nil() || t.borrow().meta.is_none() {
                        return Ok(v);
                    }
                }
                self.index(ev, Val::Str(name.clone()), env, *line)
            }
            Expr::Index(t, k, line) => {
                let tv = self.eval(t, fr)?;
                let kv = self.eval(k, fr)?;
                if let Val::Table(tt) = &tv {
                    let v = tt.borrow().get(&kv);
                    if !v.is_nil() || tt.borrow().meta.is_none() {
                        return Ok(v);
                    }
                }
                self.index(tv, kv, t, *line)
            }
            Expr::Call(..) | Expr::Method(..) => {
                let v = self.eval_multi(e, fr)?;
                Ok(v.into_iter().next().unwrap_or(Val::Nil))
            }
            Expr::Function(p) => Ok(self.make_closure(p, fr)),
            Expr::And(a, b) => {
                let av = self.eval(a, fr)?;
                if !av.truthy() {
                    Ok(av)
                } else {
                    self.eval(b, fr)
                }
            }
            Expr::Or(a, b) => {
                let av = self.eval(a, fr)?;
                if av.truthy() {
                    Ok(av)
                } else {
                    self.eval(b, fr)
                }
            }
            Expr::Paren(inner) => self.eval(inner, fr),
            Expr::Un(op, a, line) => {
                let av = self.eval(a, fr)?;
                self.unop(*op, av, a, *line)
            }
            Expr::Bin(op, a, b, line) => {
                let av = self.eval(a, fr)?;
                let bv = self.eval(b, fr)?;
                self.binop(*op, av, bv, a, b, *line)
            }
            Expr::Table(fields, line) => {
                let t = Table::new_ref();
                let mut n: i64 = 0;
                let nf = fields.len();
                for (i, f) in fields.iter().enumerate() {
                    match f {
                        TField::Pos(e) => {
                            if i + 1 == nf && e.is_multi() {
                                let vs = self.eval_multi(e, fr)?;
                                for v in vs {
                                    n += 1;
                                    t.borrow_mut().set(Val::Int(n), v);
                                }
                            } else {
                                let v = self.eval(e, fr)?;
                                n += 1;
                                t.borrow_mut().set(Val::Int(n), v);
                            }
                        }
                        TField::Named(k, v) => {
                            let kv = self.eval(k, fr)?;
                            let vv = self.eval(v, fr)?;
                            match &kv {
                                Val::Nil => return Err(self.vm_error("index is nil".into(), *line, "?")),
                                Val::Num(f) if f.is_nan() => return Err(self.vm_error("index is NaN".into(), *line, "?")),
                                _ => {}
                            }
                            t.borrow_mut().set(kv, vv);
                        }
                    }
                }
                Ok(Val::Table(t))
            }
        }
    }

    // ---------- indexing ----------

    pub fn index(&mut self, obj: Val, key: Val, oe: &Expr, line: u32) -> LResult<Val> {
        let mut obj = obj;
        let mut first = true;
        for _ in 0..2000 {
            let mm;
            match &obj {
                Val::Table(t) => {
                    let v = t.borrow().get(&key);
                    if !v.is_nil() {
                        return Ok(v);
                    }
                    let meta = t.borrow().meta.clone();
                    match meta {
                        None => return Ok(Val::Nil),
                        Some(m) => {
                            mm = m.borrow().get_str("__index");
                            if mm.is_nil() {
                                return Ok(Val::Nil);
                            }
                        }
                    }
                }
                _ => {
                    mm = self.get_metamethod(&obj, "__index");
                    if mm.is_nil() {
                        let vi = if first { varinfo(oe) } else { String::new() };
                        let tn = self.typename_of(&obj);
                        let msg = format!("attempt to index a {} value{}", tn, vi);
                        return Err(self.vm_error(msg, line, "metamethod 'index'"));
                    }
                }
            }
            if let Val::Func(_) = mm {
                self.set_line(line);
                let r = self.call(&mm, vec![obj.clone(), key.clone()], Some(("metamethod", b"index".to_vec())))?;
                return Ok(r.into_iter().next().unwrap_or(Val::Nil));
            }
            obj = mm;
            first = false;
        }
        Err(self.vm_error("'__index' chain too long; possible loop".into(), line, "?"))
    }

    pub fn setindex(&mut self, obj: Val, key: Val, val: Val, oe: &Expr, line: u32) -> LResult<()> {
        let mut obj = obj;
        let mut first = true;
        for _ in 0..2000 {
            let mm;
            match &obj {
                Val::Table(t) => {
                    let existing = t.borrow().get(&key);
                    let meta = t.borrow().meta.clone();
                    let m = if existing.is_nil() { meta.map(|m| m.borrow().get_str("__newindex")).unwrap_or(Val::Nil) } else { Val::Nil };
                    if m.is_nil() {
                        match &key {
                            Val::Nil => return Err(self.vm_error("index is nil".into(), line, "?")),
                            Val::Num(f) if f.is_nan() => return Err(self.vm_error("index is NaN".into(), line, "?")),
                            _ => {}
                        }
                        t.borrow_mut().set(key, val);
                        return Ok(());
                    }
                    mm = m;
                }
                _ => {
                    mm = self.get_metamethod(&obj, "__newindex");
                    if mm.is_nil() {
                        let vi = if first { varinfo(oe) } else { String::new() };
                        let tn = self.typename_of(&obj);
                        let msg = format!("attempt to index a {} value{}", tn, vi);
                        return Err(self.vm_error(msg, line, "metamethod 'newindex'"));
                    }
                }
            }
            if let Val::Func(_) = mm {
                self.set_line(line);
                self.call(&mm, vec![obj.clone(), key.clone(), val], Some(("metamethod", b"newindex".to_vec())))?;
                return Ok(());
            }
            obj = mm;
            first = false;
        }
        Err(self.vm_error("'__newindex' chain too long; possible loop".into(), line, "?"))
    }

    // ---------- operators ----------

    fn unop(&mut self, op: UnOp, a: Val, ae: &Expr, line: u32) -> LResult<Val> {
        match op {
            UnOp::Not => Ok(Val::Bool(!a.truthy())),
            UnOp::Neg => match &a {
                Val::Int(i) => Ok(Val::Int(i.wrapping_neg())),
                Val::Num(f) => Ok(Val::Num(-f)),
                _ => {
                    let mm = self.get_metamethod(&a, "__unm");
                    if let Val::Str(_) = &a {
                        if let Some(n) = tonumber(&a) {
                            return Ok(match n {
                                Val::Int(i) => Val::Int(i.wrapping_neg()),
                                Val::Num(f) => Val::Num(-f),
                                _ => unreachable!(),
                            });
                        }
                        return Err(self.string_arith_error("unm", &a, &a, line));
                    }
                    if !mm.is_nil() {
                        self.set_line(line);
                        let r = self.call(&mm, vec![a.clone(), a.clone()], Some(("metamethod", b"unm".to_vec())))?;
                        return Ok(r.into_iter().next().unwrap_or(Val::Nil));
                    }
                    let tn = self.typename_of(&a);
                    let msg = format!("attempt to perform arithmetic on a {} value{}", tn, varinfo(ae));
                    Err(self.vm_error(msg, line, "metamethod 'unm'"))
                }
            },
            UnOp::Len => match &a {
                Val::Str(s) => Ok(Val::Int(s.len() as i64)),
                _ => {
                    let mm = self.get_metamethod(&a, "__len");
                    if !mm.is_nil() {
                        self.set_line(line);
                        let r = self.call(&mm, vec![a.clone(), a.clone()], Some(("metamethod", b"len".to_vec())))?;
                        return Ok(r.into_iter().next().unwrap_or(Val::Nil));
                    }
                    if let Val::Table(t) = &a {
                        return Ok(Val::Int(t.borrow().len()));
                    }
                    let tn = self.typename_of(&a);
                    let msg = format!("attempt to get length of a {} value{}", tn, varinfo(ae));
                    Err(self.vm_error(msg, line, "metamethod 'len'"))
                }
            },
            UnOp::BNot => {
                if let Some(i) = match &a {
                    Val::Int(i) => Some(*i),
                    Val::Num(_) | Val::Str(_) => tointeger(&a),
                    _ => None,
                } {
                    return Ok(Val::Int(!i));
                }
                let mm = self.get_metamethod(&a, "__bnot");
                if !mm.is_nil() {
                    self.set_line(line);
                    let r = self.call(&mm, vec![a.clone(), a.clone()], Some(("metamethod", b"bnot".to_vec())))?;
                    return Ok(r.into_iter().next().unwrap_or(Val::Nil));
                }
                if let Val::Num(_) = &a {
                    let msg = format!("number{} has no integer representation", varinfo(ae));
                    return Err(self.vm_error(msg, line, "metamethod 'bnot'"));
                }
                let tn = self.typename_of(&a);
                let msg = format!("attempt to perform bitwise operation on a {} value{}", tn, varinfo(ae));
                Err(self.vm_error(msg, line, "metamethod 'bnot'"))
            }
        }
    }

    fn string_arith_error(&mut self, ev: &str, a: &Val, b: &Val, line: u32) -> LuaError {
        // emulate error raised inside string metamethod (a C function)
        self.set_line(line);
        let saved = self.frames.len();
        let mm = self.string_mt.as_ref().map(|m| m.borrow().get_str(&format!("__{}", ev))).unwrap_or(Val::Nil);
        self.frames.push(FrameInfo { func: mm, lua: None, line: 0, call_name: Some(("metamethod", ev.as_bytes().to_vec())), tail: false });
        let ta = self.typename_of(a);
        let tb = self.typename_of(b);
        let msg = format!("attempt to {} a '{}' with a '{}'", ev, ta, tb);
        let e = self.error_native(&msg);
        self.frames.truncate(saved);
        e
    }

    fn binop(&mut self, op: BinOp, a: Val, b: Val, ae: &Expr, be: &Expr, line: u32) -> LResult<Val> {
        match op {
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod | BinOp::Pow | BinOp::IDiv => {
                let an = matches!(a, Val::Int(_) | Val::Num(_));
                let bn = matches!(b, Val::Int(_) | Val::Num(_));
                if an && bn {
                    if let (Val::Int(_), Val::Int(y)) = (&a, &b) {
                        if *y == 0 && op == BinOp::IDiv {
                            return Err(self.vm_error("attempt to perform 'n//0'".into(), line, "?"));
                        }
                        if *y == 0 && op == BinOp::Mod {
                            return Err(self.vm_error("attempt to perform 'n%%0'".into(), line, "?"));
                        }
                    }
                    return Ok(arith_raw(op, &a, &b).unwrap());
                }
                self.arith_meta(op, a, b, ae, be, line)
            }
            BinOp::BAnd | BinOp::BOr | BinOp::BXor | BinOp::Shl | BinOp::Shr => {
                let ai = match &a {
                    Val::Int(i) => Some(*i),
                    Val::Num(_) | Val::Str(_) => tointeger(&a),
                    _ => None,
                };
                let bi = match &b {
                    Val::Int(i) => Some(*i),
                    Val::Num(_) | Val::Str(_) => tointeger(&b),
                    _ => None,
                };
                if let (Some(x), Some(y)) = (ai, bi) {
                    return Ok(Val::Int(match op {
                        BinOp::BAnd => x & y,
                        BinOp::BOr => x | y,
                        BinOp::BXor => x ^ y,
                        BinOp::Shl => shift_left(x, y),
                        BinOp::Shr => shift_left(x, y.wrapping_neg()),
                        _ => unreachable!(),
                    }));
                }
                let ev = binop_event(op);
                let mmname = format!("__{}", ev);
                let mut mm = self.get_metamethod(&a, &mmname);
                if mm.is_nil() {
                    mm = self.get_metamethod(&b, &mmname);
                }
                if !mm.is_nil() {
                    self.set_line(line);
                    let r = self.call(&mm, vec![a, b], Some(("metamethod", ev.as_bytes().to_vec())))?;
                    return Ok(r.into_iter().next().unwrap_or(Val::Nil));
                }
                let handler = format!("metamethod '{}'", ev);
                let an = matches!(a, Val::Int(_) | Val::Num(_));
                let bn = matches!(b, Val::Int(_) | Val::Num(_));
                if an && bn {
                    let culprit = if ai.is_none() { ae } else { be };
                    let msg = format!("number{} has no integer representation", varinfo(culprit));
                    return Err(self.vm_error(msg, line, &handler));
                }
                let (bad, be2) = if !an { (&a, ae) } else { (&b, be) };
                let tn = self.typename_of(bad);
                let msg = format!("attempt to perform bitwise operation on a {} value{}", tn, varinfo(be2));
                Err(self.vm_error(msg, line, &handler))
            }
            BinOp::Concat => {
                let sa = match &a {
                    Val::Str(_) | Val::Int(_) | Val::Num(_) => true,
                    _ => false,
                };
                let sb = match &b {
                    Val::Str(_) | Val::Int(_) | Val::Num(_) => true,
                    _ => false,
                };
                if sa && sb {
                    let mut v = self.tostr_bytes_simple(&a);
                    v.extend_from_slice(&self.tostr_bytes_simple(&b));
                    return Ok(Val::Str(Rc::from(&v[..])));
                }
                let mut mm = self.get_metamethod(&a, "__concat");
                if mm.is_nil() {
                    mm = self.get_metamethod(&b, "__concat");
                }
                if !mm.is_nil() {
                    self.set_line(line);
                    let r = self.call(&mm, vec![a, b], Some(("metamethod", b"concat".to_vec())))?;
                    return Ok(r.into_iter().next().unwrap_or(Val::Nil));
                }
                let (bad, bexp) = if sa { (&b, be) } else { (&a, ae) };
                let tn = self.typename_of(bad);
                let msg = format!("attempt to concatenate a {} value{}", tn, varinfo(bexp));
                Err(self.vm_error(msg, line, "metamethod 'concat'"))
            }
            BinOp::Eq => Ok(Val::Bool(self.equals(&a, &b, line)?)),
            BinOp::Ne => Ok(Val::Bool(!self.equals(&a, &b, line)?)),
            BinOp::Lt => Ok(Val::Bool(self.less_than(&a, &b, line)?)),
            BinOp::Le => Ok(Val::Bool(self.less_equal(&a, &b, line)?)),
            BinOp::Gt => Ok(Val::Bool(self.less_than(&b, &a, line)?)),
            BinOp::Ge => Ok(Val::Bool(self.less_equal(&b, &a, line)?)),
        }
    }

    fn arith_meta(&mut self, op: BinOp, a: Val, b: Val, ae: &Expr, be: &Expr, line: u32) -> LResult<Val> {
        let ev = binop_event(op);
        let mmname = format!("__{}", ev);
        // string metamethod semantics
        let first_mm_owner_is_str = |v: &Val| matches!(v, Val::Str(_));
        let ma = self.get_metamethod(&a, &mmname);
        let (mm, from_str) = if !ma.is_nil() {
            (ma, first_mm_owner_is_str(&a))
        } else {
            let mb = self.get_metamethod(&b, &mmname);
            let fs = first_mm_owner_is_str(&b);
            (mb, fs)
        };
        if !mm.is_nil() && from_str {
            // string arithmetic
            let na = tonumber(&a);
            let nb = tonumber(&b);
            if let (Some(x), Some(y)) = (&na, &nb) {
                if let (Val::Int(_), Val::Int(yy)) = (x, y) {
                    if *yy == 0 && (op == BinOp::IDiv || op == BinOp::Mod) {
                        // error raised inside the metamethod
                        self.set_line(line);
                        let saved = self.frames.len();
                        self.frames.push(FrameInfo { func: mm.clone(), lua: None, line: 0, call_name: Some(("metamethod", ev.as_bytes().to_vec())), tail: false });
                        let m = if op == BinOp::IDiv { "attempt to perform 'n//0'" } else { "attempt to perform 'n%%0'" };
                        let e = self.error_native(m);
                        self.frames.truncate(saved);
                        return Err(e);
                    }
                }
                return Ok(arith_raw(op, x, y).unwrap());
            }
            // trymt: if second is string or has no metamethod -> error
            if matches!(b, Val::Str(_)) || self.get_metamethod(&b, &mmname).is_nil() {
                return Err(self.string_arith_error(ev, &a, &b, line));
            }
            let mb = self.get_metamethod(&b, &mmname);
            self.set_line(line);
            let r = self.call(&mb, vec![a, b], Some(("metamethod", ev.as_bytes().to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil));
        }
        if !mm.is_nil() {
            self.set_line(line);
            let r = self.call(&mm, vec![a, b], Some(("metamethod", ev.as_bytes().to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil));
        }
        let an = matches!(a, Val::Int(_) | Val::Num(_));
        let (bad, bexp) = if !an { (&a, ae) } else { (&b, be) };
        let tn = self.typename_of(bad);
        let msg = format!("attempt to perform arithmetic on a {} value{}", tn, varinfo(bexp));
        let handler = format!("metamethod '{}'", ev);
        Err(self.vm_error(msg, line, &handler))
    }

    pub fn equals(&mut self, a: &Val, b: &Val, line: u32) -> LResult<bool> {
        if a.raw_eq(b) {
            return Ok(true);
        }
        if let (Val::Table(_), Val::Table(_)) = (a, b) {
            let mut mm = self.get_metamethod(a, "__eq");
            if mm.is_nil() {
                mm = self.get_metamethod(b, "__eq");
            }
            if !mm.is_nil() {
                self.set_line(line);
                let r = self.call(&mm, vec![a.clone(), b.clone()], Some(("metamethod", b"eq".to_vec())))?;
                return Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy());
            }
        }
        Ok(false)
    }

    fn order_error(&mut self, a: &Val, b: &Val, line: u32, ev: &str) -> LuaError {
        let t1 = self.typename_of(a);
        let t2 = self.typename_of(b);
        let msg = if t1 == t2 { format!("attempt to compare two {} values", t1) } else { format!("attempt to compare {} with {}", t1, t2) };
        self.vm_error(msg, line, &format!("metamethod '{}'", ev))
    }

    pub fn less_than(&mut self, a: &Val, b: &Val, line: u32) -> LResult<bool> {
        match (a, b) {
            (Val::Int(x), Val::Int(y)) => return Ok(x < y),
            (Val::Int(_), Val::Num(_)) | (Val::Num(_), Val::Int(_)) | (Val::Num(_), Val::Num(_)) => {
                return Ok(num_lt(a, b));
            }
            (Val::Str(x), Val::Str(y)) => return Ok(x[..] < y[..]),
            _ => {}
        }
        let mut mm = self.get_metamethod(a, "__lt");
        if mm.is_nil() {
            mm = self.get_metamethod(b, "__lt");
        }
        if !mm.is_nil() {
            self.set_line(line);
            let r = self.call(&mm, vec![a.clone(), b.clone()], Some(("metamethod", b"lt".to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy());
        }
        Err(self.order_error(a, b, line, "lt"))
    }

    pub fn less_equal(&mut self, a: &Val, b: &Val, line: u32) -> LResult<bool> {
        match (a, b) {
            (Val::Int(x), Val::Int(y)) => return Ok(x <= y),
            (Val::Int(_), Val::Num(_)) | (Val::Num(_), Val::Int(_)) | (Val::Num(_), Val::Num(_)) => {
                return Ok(num_le(a, b));
            }
            (Val::Str(x), Val::Str(y)) => return Ok(x[..] <= y[..]),
            _ => {}
        }
        let mut mm = self.get_metamethod(a, "__le");
        if mm.is_nil() {
            mm = self.get_metamethod(b, "__le");
        }
        if !mm.is_nil() {
            self.set_line(line);
            let r = self.call(&mm, vec![a.clone(), b.clone()], Some(("metamethod", b"le".to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy());
        }
        Err(self.order_error(a, b, line, "le"))
    }

    pub fn tostr_bytes_simple(&self, v: &Val) -> Vec<u8> {
        match v {
            Val::Str(s) => s.to_vec(),
            Val::Int(_) | Val::Num(_) => number_to_str(v),
            _ => Vec::new(),
        }
    }

    /// luaL_tolstring
    pub fn tostring(&mut self, v: &Val) -> LResult<Vec<u8>> {
        let mm = self.get_metamethod(v, "__tostring");
        if !mm.is_nil() {
            let r = self.call(&mm, vec![v.clone()], None)?;
            let r0 = r.into_iter().next().unwrap_or(Val::Nil);
            return match r0 {
                Val::Str(s) => Ok(s.to_vec()),
                Val::Int(_) | Val::Num(_) => Ok(number_to_str(&r0)),
                _ => Err(self.error_native("'__tostring' must return a string")),
            };
        }
        Ok(match v {
            Val::Nil => b"nil".to_vec(),
            Val::Bool(true) => b"true".to_vec(),
            Val::Bool(false) => b"false".to_vec(),
            Val::Int(_) | Val::Num(_) => number_to_str(v),
            Val::Str(s) => s.to_vec(),
            Val::Table(_) => {
                let name = self.typename_of(v);
                format!("{}: 0x{:012x}", name, v.ptr_addr()).into_bytes()
            }
            Val::Func(f) => match &**f {
                Func::Native { .. } => format!("function: builtin: 0x{:012x}", v.ptr_addr()).into_bytes(),
                _ => format!("function: 0x{:012x}", v.ptr_addr()).into_bytes(),
            },
        })
    }

    // ---------- loading ----------

    pub fn load(&mut self, src: &[u8], chunkname: &str, env: Option<Val>) -> Result<Val, LuaError> {
        match super::parser::parse_chunk(src, chunkname) {
            Ok(p) => {
                let envv = env.unwrap_or_else(|| Val::Table(self.globals.clone()));
                let ups = vec![Rc::new(RefCell::new(envv))];
                Ok(Val::Func(Rc::new(Func::Lua { proto: p, upvals: ups })))
            }
            Err(e) => {
                let incomplete = e.0.ends_with("<eof>");
                Err(LuaError::Syntax { msg: e.0, incomplete })
            }
        }
    }
}

fn num_lt(a: &Val, b: &Val) -> bool {
    match (a, b) {
        (Val::Int(x), Val::Num(y)) => {
            if y.is_nan() {
                false
            } else if *y >= 9223372036854775808.0 {
                true
            } else if *y > -9223372036854775808.0 {
                // x < y  <=> x < ceil(y)
                *x < y.ceil() as i64 || (*x as f64) < *y && y.ceil() as i64 > *x
            } else {
                false
            }
        }
        (Val::Num(x), Val::Int(y)) => {
            if x.is_nan() {
                false
            } else if *x < -9223372036854775808.0 {
                true
            } else if *x < 9223372036854775808.0 {
                (x.floor() as i64) < *y
            } else {
                false
            }
        }
        (Val::Num(x), Val::Num(y)) => x < y,
        (Val::Int(x), Val::Int(y)) => x < y,
        _ => false,
    }
}

fn num_le(a: &Val, b: &Val) -> bool {
    match (a, b) {
        (Val::Int(x), Val::Num(y)) => {
            if y.is_nan() {
                false
            } else if *y >= 9223372036854775808.0 {
                true
            } else if *y >= -9223372036854775808.0 {
                *x <= y.floor() as i64
            } else {
                false
            }
        }
        (Val::Num(x), Val::Int(y)) => {
            if x.is_nan() {
                false
            } else if *x < -9223372036854775808.0 {
                true
            } else if *x < 9223372036854775808.0 {
                (x.ceil() as i64) <= *y
            } else {
                false
            }
        }
        (Val::Num(x), Val::Num(y)) => x <= y,
        (Val::Int(x), Val::Int(y)) => x <= y,
        _ => false,
    }
}
EOF"}

