            (Val::Str(x), Val::Str(y)) => return Ok(x[..] < y[..]),
            _ => {}
        }
        let mut mm = self.get_metamethod(a, "__lt");
        if mm.is_nil() {
            mm = self.get_metamethod(b, "__lt");
        }
        if !mm.is_nil() {
            self.set_line(line);
            let r = self.call(&mm, vec![a.clone(), b.clone()], Some(("metamethod", b"lt".to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy());
        }
        Err(self.order_error(a, b, line, "lt"))
    }

    pub fn less_equal(&mut self, a: &Val, b: &Val, line: u32) -> LResult<bool> {
        match (a, b) {
            (Val::Int(x), Val::Int(y)) => return Ok(x <= y),
            (Val::Int(_), Val::Num(_)) | (Val::Num(_), Val::Int(_)) | (Val::Num(_), Val::Num(_)) => {
                return Ok(num_le(a, b));
            }
            (Val::Str(x), Val::Str(y)) => return Ok(x[..] <= y[..]),
            _ => {}
        }
        let mut mm = self.get_metamethod(a, "__le");
        if mm.is_nil() {
            mm = self.get_metamethod(b, "__le");
        }
        if !mm.is_nil() {
            self.set_line(line);
            let r = self.call(&mm, vec![a.clone(), b.clone()], Some(("metamethod", b"le".to_vec())))?;
            return Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy());
        }
        Err(self.order_error(a, b, line, "le"))
    }

    pub fn tostr_bytes_simple(&self, v: &Val) -> Vec<u8> {
        match v {
            Val::Str(s) => s.to_vec(),
            Val::Int(_) | Val::Num(_) => number_to_str(v),
            _ => Vec::new(),
        }
    }

    /// luaL_tolstring
    pub fn tostring(&mut self, v: &Val) -> LResult<Vec<u8>> {
        let mm = self.get_metamethod(v, "__tostring");
        if !mm.is_nil() {
            let r = self.call(&mm, vec![v.clone()], None)?;
            let r0 = r.into_iter().next().unwrap_or(Val::Nil);
            return match r0 {
                Val::Str(s) => Ok(s.to_vec()),
                Val::Int(_) | Val::Num(_) => Ok(number_to_str(&r0)),
                _ => Err(self.error_native("'__tostring' must return a string")),
            };
        }
        Ok(match v {
            Val::Nil => b"nil".to_vec(),
            Val::Bool(true) => b"true".to_vec(),
            Val::Bool(false) => b"false".to_vec(),
            Val::Int(_) | Val::Num(_) => number_to_str(v),
            Val::Str(s) => s.to_vec(),
            Val::Table(_) => {
                let name = self.typename_of(v);
                format!("{}: 0x{:012x}", name, v.ptr_addr()).into_bytes()
            }
            Val::Func(f) => match &**f {
                Func::Native { .. } => format!("function: builtin: 0x{:012x}", v.ptr_addr()).into_bytes(),
                _ => format!("function: 0x{:012x}", v.ptr_addr()).into_bytes(),
            },
        })
    }

