                let envv = env.unwrap_or_else(|| Val::Table(self.globals.clone()));
                let ups = vec![Rc::new(RefCell::new(envv))];
                Ok(Val::Func(Rc::new(Func::Lua { proto: p, upvals: ups })))
            }
            Err(e) => {
                let incomplete = e.0.ends_with("<eof>");
                Err(LuaError::Syntax { msg: e.0, incomplete })
            }
        }
    }
