fn num_lt(a: &Val, b: &Val) -> bool {
    match (a, b) {
        (Val::Int(x), Val::Num(y)) => {
            if y.is_nan() {
                false
            } else if *y >= 9223372036854775808.0 {
                true
            } else if *y > -9223372036854775808.0 {
                // x < y  <=> x < ceil(y)
