            } else {
                false
            }
        }
        (Val::Num(x), Val::Num(y)) => x < y,
        (Val::Int(x), Val::Int(y)) => x < y,
        _ => false,
    }
}

fn num_le(a: &Val, b: &Val) -> bool {
    match (a, b) {
        (Val::Int(x), Val::Num(y)) => {
