    fn tzset();
}

pub fn fmt_float(spec: &str, f: f64) -> String {
    let cfmt = CString::new(spec).unwrap();
    let mut buf = vec![0u8; 512];
    let n = unsafe { snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), f as c_double) };
    if n as usize >= buf.len() {
        buf = vec![0u8; n as usize + 1];
        unsafe { snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), f as c_double) };
    }
    buf.truncate(n.max(0) as usize);
    String::from_utf8_lossy(&buf).into_owned()
}

pub fn fmt_int(spec: &str, i: i64) -> String {
    let cfmt = CString::new(spec).unwrap();
    let mut buf = vec![0u8; 512];
    let n = unsafe { snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), i as c_longlong) };
    if n as usize >= buf.len() {
        buf = vec![0u8; n as usize + 1];
        unsafe { snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), i as c_longlong) };
