    let cfmt = CString::new(spec).unwrap();
    let cs = CString::new(s.to_vec()).unwrap_or_else(|_| CString::new("").unwrap());
    let mut buf = vec![0u8; s.len() + 512];
    let n = unsafe { snprintf(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), cs.as_ptr()) };
    buf.truncate(n.max(0) as usize);
    buf
}

/// strtod; returns (value, consumed bytes)
pub fn c_strtod(s: &[u8]) -> (f64, usize) {
    let cs = match CString::new(s.to_vec()) {
        Ok(c) => c,
        Err(_) => return (0.0, 0),
    };
    let mut end: *mut c_char = std::ptr::null_mut();
    let v = unsafe { strtod(cs.as_ptr(), &mut end) };
    let consumed = (end as usize).wrapping_sub(cs.as_ptr() as usize);
    (v, consumed)
}

