    let mut tm = Tm::default();
    let tt = t as c_long;
    unsafe {
        if gmtime_r(&tt, &mut tm).is_null() {
            None
        } else {
            Some(tm)
        }
    }
}

pub fn c_mktime(tm: &mut Tm) -> i64 {
    unsafe { mktime(tm) as i64 }
}

pub fn c_strftime(fmt: &[u8], tm: &Tm) -> Vec<u8> {
    let cfmt = match CString::new(fmt.to_vec()) {
        Ok(c) => c,
        Err(_) => return Vec::new(),
    };
    let mut buf = vec![0u8; 1024];
    let n = unsafe { strftime(buf.as_mut_ptr() as *mut c_char, buf.len(), cfmt.as_ptr(), tm) };
    buf.truncate(n);
    buf
}

pub fn c_clock() -> f64 {
    unsafe { clock() as f64 / 1_000_000.0 }
}

pub fn c_system(cmd: Option<&[u8]>) -> i32 {
    unsafe {
        match cmd {
            None => system(std::ptr::null()),
            Some(c) => {
                let cs = CString::new(c.to_vec()).unwrap_or_else(|_| CString::new("").unwrap());
                system(cs.as_ptr())
            }
        }
    }
}
