// Argument checking helpers for native functions (luaL_check* equivalents)
use super::interp::{tointeger, tonumber, Interp, LResult};
use super::value::*;

pub fn arg(a: &[Val], i: usize) -> Val {
    a.get(i).cloned().unwrap_or(Val::Nil)
}

pub fn is_none_or_nil(a: &[Val], i: usize) -> bool {
    matches!(a.get(i), None | Some(Val::Nil))
}

pub fn check_any(it: &mut Interp, a: &[Val], i: usize) -> LResult<Val> {
    match a.get(i) {
        None => Err(it.arg_error(i + 1, "value expected")),
        Some(v) => Ok(v.clone()),
    }
}

pub fn check_int(it: &mut Interp, a: &[Val], i: usize) -> LResult<i64> {
    match a.get(i) {
        Some(Val::Int(x)) => Ok(*x),
        Some(v @ (Val::Num(_) | Val::Str(_))) => match tointeger(v) {
            Some(x) => Ok(x),
            None => {
                if tonumber(v).is_some() {
                    Err(it.arg_error(i + 1, "number has no integer representation"))
                } else {
                    let v = v.clone();
                    Err(it.type_error(i + 1, "number", Some(&v)))
                }
            }
        },
        other => {
            let o = other.cloned();
            Err(it.type_error(i + 1, "number", o.as_ref()))
        }
    }
}

pub fn opt_int(it: &mut Interp, a: &[Val], i: usize, d: i64) -> LResult<i64> {
    if is_none_or_nil(a, i) {
        Ok(d)
    } else {
        check_int(it, a, i)
    }
}

pub fn check_number(it: &mut Interp, a: &[Val], i: usize) -> LResult<Val> {
    match a.get(i) {
        Some(v @ (Val::Int(_) | Val::Num(_))) => Ok(v.clone()),
        Some(v @ Val::Str(_)) => match tonumber(v) {
            Some(n) => Ok(n),
            None => {
                let v = v.clone();
                Err(it.type_error(i + 1, "number", Some(&v)))
            }
        },
        other => {
            let o = other.cloned();
            Err(it.type_error(i + 1, "number", o.as_ref()))
        }
    }
}

pub fn check_num(it: &mut Interp, a: &[Val], i: usize) -> LResult<f64> {
    match check_number(it, a, i)? {
        Val::Int(x) => Ok(x as f64),
        Val::Num(f) => Ok(f),
        _ => unreachable!(),
    }
}

pub fn opt_num(it: &mut Interp, a: &[Val], i: usize, d: f64) -> LResult<f64> {
    if is_none_or_nil(a, i) {
        Ok(d)
    } else {
        check_num(it, a, i)
    }
}

pub fn check_str(it: &mut Interp, a: &[Val], i: usize) -> LResult<LStr> {
    match a.get(i) {
        Some(Val::Str(s)) => Ok(s.clone()),
        Some(v @ (Val::Int(_) | Val::Num(_))) => Ok(LStr::from(&number_to_str(v)[..])),
        other => {
            let o = other.cloned();
            Err(it.type_error(i + 1, "string", o.as_ref()))
        }
    }
}

pub fn opt_str(it: &mut Interp, a: &[Val], i: usize, d: &[u8]) -> LResult<LStr> {
    if is_none_or_nil(a, i) {
        Ok(LStr::from(d))
    } else {
        check_str(it, a, i)
    }
}

pub fn check_table(it: &mut Interp, a: &[Val], i: usize) -> LResult<TableRef> {
    match a.get(i) {
        Some(Val::Table(t)) => Ok(t.clone()),
        other => {
            let o = other.cloned();
            Err(it.type_error(i + 1, "table", o.as_ref()))
        }
    }
}
