// Lua standard library (base, table, math, os, io, utf8, package, coroutine)
use std::cell::RefCell;
use std::io::Write;
use std::rc::Rc;

use super::args::*;
use super::interp::{tointeger, tonumber, Interp, LResult};
use super::value::*;

thread_local! {
    pub static C_STDOUT: RefCell<Vec<u8>> = RefCell::new(Vec::new());
    static RNG: RefCell<[u64; 4]> = RefCell::new([0x9e3779b97f4a7c15, 0xbf58476d1ce4e5b9, 0x94d049bb133111eb, 0x2545f4914f6cdd1d]);
}

pub fn c_stdout_write(b: &[u8]) {
    C_STDOUT.with(|c| {
        let mut c = c.borrow_mut();
        c.extend_from_slice(b);
        if c.len() >= 4096 {
            let n = c.len() / 4096 * 4096;
            let out = std::io::stdout();
            let mut o = out.lock();
            let _ = o.write_all(&c[..n]);
            let _ = o.flush();
            c.drain(..n);
        }
    });
}

pub fn c_stdout_flush() {
    C_STDOUT.with(|c| {
        let mut c = c.borrow_mut();
        if !c.is_empty() {
            let out = std::io::stdout();
            let mut o = out.lock();
            let _ = o.write_all(&c);
            let _ = o.flush();
            c.clear();
        }
    });
}

pub fn mk_native(name: &str, f: impl Fn(&mut Interp, Vec<Val>) -> LResult<Vec<Val>> + 'static) -> Val {
    Val::Func(Rc::new(Func::Native { name: name.to_string(), f: Rc::new(f) }))
}

pub fn reg(t: &TableRef, name: &str, f: impl Fn(&mut Interp, Vec<Val>) -> LResult<Vec<Val>> + 'static) {
    let v = mk_native(name, f);
    t.borrow_mut().set(Val::str(name), v);
}

fn one(v: Val) -> LResult<Vec<Val>> {
    Ok(vec![v])
}

pub fn chunkid(source: &[u8]) -> String {
    let s = source;
    if s.first() == Some(&b'=') {
        let rest = &s[1..];
        let n = rest.len().min(59);
        return String::from_utf8_lossy(&rest[..n]).into_owned();
    }
    if s.first() == Some(&b'@') {
        let rest = &s[1..];
        if rest.len() <= 59 {
            return String::from_utf8_lossy(rest).into_owned();
        }
        let keep = 59 - 3;
        return format!("...{}", String::from_utf8_lossy(&rest[rest.len() - keep..]));
    }
    let nl = s.iter().position(|&c| c == b'\n');
    let bufflen = 60 - (9 + 3 + 2) - 1;
    let mut out = String::from("[string \"");
    if s.len() < bufflen && nl.is_none() {
        out.push_str(&String::from_utf8_lossy(s));
    } else {
        let mut l = s.len();
        if let Some(p) = nl {
            l = p;
        }
        if l > bufflen {
            l = bufflen;
        }
        out.push_str(&String::from_utf8_lossy(&s[..l]));
        out.push_str("...");
    }
    out.push_str("\"]");
    out
}

pub fn open_libs(it: &mut Interp) {
