fn ipairs_aux(it: &mut Interp, a: Vec<Val>) -> LResult<Vec<Val>> {
    let i = match arg(&a, 1) {
        Val::Int(i) => i,
        _ => 0,
    }
    .wrapping_add(1);
    let t = arg(&a, 0);
    let v = match &t {
        Val::Table(tt) => {
            let raw = tt.borrow().get_int(i);
            if raw.is_nil() && tt.borrow().meta.is_some() {
                it.index(t.clone(), Val::Int(i), &super::ast::Expr::Nil, 0)?
            } else {
                raw
            }
        }
        _ => it.index(t.clone(), Val::Int(i), &super::ast::Expr::Nil, 0)?,
    };
    if v.is_nil() {
        Ok(vec![Val::Nil])
    } else {
        Ok(vec![Val::Int(i), v])
    }
}

fn lua_next(it: &mut Interp, a: Vec<Val>) -> LResult<Vec<Val>> {
    let t = check_table(it, &a, 0)?;
    let k = arg(&a, 1);
