        let fname = opt_str(it, &a, 0, b"")?;
        let path = String::from_utf8_lossy(&fname).into_owned();
        match std::fs::read(&path) {
            Ok(src) => {
                let cid = chunkid(format!("@{}", path).as_bytes());
                match it.load(&src, &cid, None) {
                    Ok(f) => it.call(&f, vec![], None),
                    Err(LuaError::Syntax { msg, .. }) => Err(it.error_value(Val::str(&msg))),
                    Err(e) => Err(e),
                }
            }
            Err(e) => Err(it.error_value(Val::str(&format!("cannot open {}: {}", path, ioerr(&e))))),
        }
    });
    reg(g, "require", |it, a| {
        let name = check_str(it, &a, 0)?;
        let loaded = it.loaded.clone();
        let v = loaded.borrow().get(&Val::Str(name.clone()));
        if v.truthy() {
            return one(v);
        }
        let n = String::from_utf8_lossy(&name).into_owned();
        let fname = n.replace('.', "/");
        let paths = [
            format!("/usr/local/share/lua/5.4/{}.lua", fname),
            format!("/usr/local/share/lua/5.4/{}/init.lua", fname),
            format!("/usr/local/lib/lua/5.4/{}.lua", fname),
            format!("/usr/local/lib/lua/5.4/{}/init.lua", fname),
            format!("./{}.lua", fname),
            format!("./{}/init.lua", fname),
        ];
        for p in &paths {
            if let Ok(src) = std::fs::read(p) {
                let cid = chunkid(format!("@{}", p).as_bytes());
                let f = match it.load(&src, &cid, None) {
                    Ok(f) => f,
                    Err(LuaError::Syntax { msg, .. }) => {
                        let m = format!("error loading module '{}' from file '{}':\n\t{}", n, p, msg);
                        return Err(it.error_native(&m));
                    }
                    Err(e) => return Err(e),
                };
                let r = it.call(&f, vec![Val::Str(name.clone()), Val::str(p)], None)?;
                let mut res = r.into_iter().next().unwrap_or(Val::Nil);
                if res.is_nil() {
                    let cur = loaded.borrow().get(&Val::Str(name.clone()));
                    res = if cur.is_nil() { Val::Bool(true) } else { cur };
                }
                loaded.borrow_mut().set(Val::Str(name.clone()), res.clone());
                return Ok(vec![res, Val::str(p)]);
            }
        }
        let cpaths = [format!("/usr/local/lib/lua/5.4/{}.so", fname), "/usr/local/lib/lua/5.4/loadall.so".to_string(), format!("./{}.so", fname)];
        let mut msg = format!("module '{}' not found:\n\tno field package.preload['{}']", n, n);
        for p in paths.iter().chain(cpaths.iter()) {
            msg.push_str(&format!("\n\tno file '{}'", p));
        }
        Err(it.error_native(&msg))
    });
    reg(g, "collectgarbage", |it, a| {
        let opt = opt_str(it, &a, 0, b"collect")?;
        match &opt[..] {
            b"count" => Ok(vec![Val::Num(24.5), Val::Int(0)]),
            b"collect" | b"step" | b"incremental" | b"generational" => {
                if &opt[..] == b"step" {
                    one(Val::Bool(true))
                } else if &opt[..] == b"collect" {
                    one(Val::Int(0))
                } else {
                    one(Val::str("incremental"))
                }
            }
            b"isrunning" => one(Val::Bool(true)),
            b"stop" | b"restart" | b"setpause" | b"setstepmul" => one(Val::Int(0)),
            _ => {
                let m = format!("invalid option '{}'", String::from_utf8_lossy(&opt));
                Err(it.arg_error(1, &m))
            }
        }
    });
    reg(g, "warn", |it, a| {
        check_str(it, &a, 0)?;
        Ok(vec![])
    });
}

pub fn ioerr(e: &std::io::Error) -> String {
    let s = e.to_string();
    match s.find(" (os error") {
        Some(p) => s[..p].to_string(),
        None => s,
    }
}

// ---------------- coroutine (unsupported) ----------------
fn open_coroutine(t: &TableRef) {
    for name in ["create", "resume", "yield", "status", "wrap", "isyieldable", "running", "close"] {
        let nm = name.to_string();
        reg(t, name, move |it, _a| {
            if nm == "isyieldable" {
                return one(Val::Bool(false));
            }
            if nm == "running" {
                return Ok(vec![Val::Nil, Val::Bool(true)]);
            }
            Err(it.error_native("coroutines are not supported"))
        });
    }
}

// ---------------- table ----------------

fn tget(it: &mut Interp, t: &Val, i: i64) -> LResult<Val> {
    if let Val::Table(tt) = t {
        let v = tt.borrow().get_int(i);
        if !v.is_nil() || tt.borrow().meta.is_none() {
            return Ok(v);
        }
    }
    it.index(t.clone(), Val::Int(i), &super::ast::Expr::Nil, 0)
}

fn tset(it: &mut Interp, t: &Val, i: i64, v: Val) -> LResult<()> {
    if let Val::Table(tt) = t {
        if tt.borrow().meta.is_none() {
            tt.borrow_mut().set(Val::Int(i), v);
            return Ok(());
        }
    }
    it.setindex(t.clone(), Val::Int(i), v, &super::ast::Expr::Nil, 0)
}

fn tlen(it: &mut Interp, t: &Val) -> LResult<i64> {
    if let Val::Table(tt) = t {
        if tt.borrow().meta.is_none() {
            return Ok(tt.borrow().len());
        }
        let mm = it.get_metamethod(t, "__len");
        if !mm.is_nil() {
            let r = it.call(&mm, vec![t.clone()], None)?;
            let r0 = r.into_iter().next().unwrap_or(Val::Nil);
            return match tointeger(&r0) {
                Some(i) => Ok(i),
                None => Err(it.error_native("object length is not an integer")),
            };
        }
        return Ok(tt.borrow().len());
    }
    Ok(0)
}

fn check_tab(it: &mut Interp, a: &[Val], i: usize) -> LResult<Val> {
    match a.get(i) {
        Some(v @ Val::Table(_)) => Ok(v.clone()),
        other => {
            let o = other.cloned();
            Err(it.type_error(i + 1, "table", o.as_ref()))
        }
    }
}

fn sort_lt(it: &mut Interp, cmp: &Val, a: &Val, b: &Val) -> LResult<bool> {
    if cmp.is_nil() {
        it.less_than(a, b, 0)
    } else {
        let r = it.call(cmp, vec![a.clone(), b.clone()], None)?;
        Ok(r.into_iter().next().unwrap_or(Val::Nil).truthy())
    }
}

fn auxsort(it: &mut Interp, t: &Val, cmp: &Val, mut lo: i64, mut up: i64, mut rnd: u64) -> LResult<()> {
    while lo < up {
        let a_lo = tget(it, t, lo)?;
        let a_up = tget(it, t, up)?;
        if sort_lt(it, cmp, &a_up, &a_lo)? {
            tset(it, t, lo, a_up)?;
            tset(it, t, up, a_lo)?;
        }
        if up - lo == 1 {
            break;
        }
        let p: i64 = if up - lo < 100 || rnd == 0 {
            (lo + up) / 2
        } else {
            let r4 = (up - lo) / 4;
            (rnd % (r4 as u64 * 2)) as i64 + lo + r4
        };
        let a_p = tget(it, t, p)?;
        let a_lo = tget(it, t, lo)?;
        if sort_lt(it, cmp, &a_p, &a_lo)? {
            tset(it, t, p, a_lo)?;
            tset(it, t, lo, a_p.clone())?;
        } else {
            let a_up = tget(it, t, up)?;
            if sort_lt(it, cmp, &a_up, &a_p)? {
                tset(it, t, p, a_up)?;
                tset(it, t, up, a_p.clone())?;
            }
        }
        if up - lo == 2 {
            break;
        }
        let pv = tget(it, t, p)?;
        let a_up1 = tget(it, t, up - 1)?;
        tset(it, t, p, a_up1)?;
        tset(it, t, up - 1, pv.clone())?;
        // partition
        let mut i = lo;
        let mut j = up - 1;
        loop {
            i += 1;
            let mut ai = tget(it, t, i)?;
            while sort_lt(it, cmp, &ai, &pv)? {
                if i == up - 1 {
                    return Err(it.error_native("invalid order function for sorting"));
                }
                i += 1;
                ai = tget(it, t, i)?;
            }
            j -= 1;
            let mut aj = tget(it, t, j)?;
            while sort_lt(it, cmp, &pv, &aj)? {
                if j < i {
                    return Err(it.error_native("invalid order function for sorting"));
                }
                j -= 1;
                aj = tget(it, t, j)?;
            }
            if j < i {
                break;
            }
            tset(it, t, i, aj)?;
            tset(it, t, j, ai)?;
        }
        let a_up1 = tget(it, t, up - 1)?;
        let ai = tget(it, t, i)?;
        tset(it, t, up - 1, ai)?;
        tset(it, t, i, a_up1)?;
        let p = i;
        if p - lo < up - p {
            auxsort(it, t, cmp, lo, p - 1, rnd)?;
            lo = p + 1;
        } else {
            auxsort(it, t, cmp, p + 1, up, rnd)?;
            up = p - 1;
        }
        if (up - lo) / 128 > 0 {
            rnd = rnd.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407) | 1;
        }
    }
    Ok(())
}

fn open_table(t: &TableRef) {
    reg(t, "insert", |it, a| {
        let tv = check_tab(it, &a, 0)?;
        let e = tlen(it, &tv)?.wrapping_add(1);
        match a.len() {
            2 => {
                tset(it, &tv, e, a[1].clone())?;
            }
            3 => {
                let pos = check_int(it, &a, 1)?;
                if (pos as u64).wrapping_sub(1) >= e as u64 {
                    return Err(it.arg_error(2, "position out of bounds"));
                }
                let mut i = e;
                while i > pos {
                    let v = tget(it, &tv, i - 1)?;
                    tset(it, &tv, i, v)?;
                    i -= 1;
                }
                tset(it, &tv, pos, a[2].clone())?;
            }
            _ => return Err(it.error_native("wrong number of arguments to 'insert'")),
        }
        Ok(vec![])
    });
    reg(t, "remove", |it, a| {
        let tv = check_tab(it, &a, 0)?;
        let size = tlen(it, &tv)?;
        let mut pos = opt_int(it, &a, 1, size)?;
        if a.len() >= 2 && size.wrapping_add(1) as u64 != pos as u64 && (pos as u64).wrapping_sub(1) >= (size as u64).wrapping_add(1) {
            return Err(it.arg_error(2, "position out of bounds"));
        }
        if a.len() >= 2 && !((size + 1) == pos || (pos as u64).wrapping_sub(1) < (size as u64).wrapping_add(1)) {
            return Err(it.arg_error(2, "position out of bounds"));
        }
        let v = tget(it, &tv, pos)?;
        while pos < size {
            let nv = tget(it, &tv, pos + 1)?;
            tset(it, &tv, pos, nv)?;
            pos += 1;
        }
        if pos <= size || a.len() < 2 {
            tset(it, &tv, pos, Val::Nil)?;
        } else {
            tset(it, &tv, pos, Val::Nil)?;
        }
        one(v)
    });
    reg(t, "concat", |it, a| {
        let tv = check_tab(it, &a, 0)?;
        let sep = opt_str(it, &a, 1, b"")?;
        let i = opt_int(it, &a, 2, 1)?;
        let j = if is_none_or_nil(&a, 3) { tlen(it, &tv)? } else { check_int(it, &a, 3)? };
        let mut out: Vec<u8> = Vec::new();
        let mut k = i;
        while k <= j {
            let v = tget(it, &tv, k)?;
            match &v {
                Val::Str(s) => out.extend_from_slice(s),
                Val::Int(_) | Val::Num(_) => out.extend_from_slice(&number_to_str(&v)),
                _ => {
                    let tn = it.typename_of(&v);
                    let m = format!("invalid value (at index {}) in table for 'concat'", k);
                    let _ = tn;
                    return Err(it.error_native(&m));
                }
            }
            if k != j {
                out.extend_from_slice(&sep);
            }
            if k == i64::MAX {
                break;
            }
            k += 1;
        }
        one(Val::bytes(&out))
    });
    reg(t, "unpack", |it, a| {
        let tv = arg(&a, 0);
        let i = opt_int(it, &a, 1, 1)?;
        let e = if is_none_or_nil(&a, 2) { tlen(it, &tv)? } else { check_int(it, &a, 2)? };
        if i > e {
            return Ok(vec![]);
        }
        let n = (e as u64).wrapping_sub(i as u64);
        if n >= 1_000_000 {
            return Err(it.error_native("too many results to unpack"));
        }
        let mut out = Vec::new();
        let mut k = i;
        loop {
            out.push(tget(it, &tv, k)?);
            if k == e {
                break;
            }
            k += 1;
        }
        Ok(out)
    });
    reg(t, "pack", |_it, a| {
        let t = Table::new_ref();
        for (i, v) in a.iter().enumerate() {
            t.borrow_mut().set(Val::Int(i as i64 + 1), v.clone());
        }
        t.borrow_mut().set(Val::str("n"), Val::Int(a.len() as i64));
        one(Val::Table(t))
    });
    reg(t, "sort", |it, a| {
        let tv = check_tab(it, &a, 0)?;
        let n = tlen(it, &tv)?;
        if n > 1 {
            if n >= i32::MAX as i64 {
                return Err(it.arg_error(1, "array too big"));
            }
            let cmp = arg(&a, 1);
            if !cmp.is_nil() && !matches!(cmp, Val::Func(_)) {
                return Err(it.type_error(2, "function", Some(&cmp)));
            }
            auxsort(it, &tv, &cmp, 1, n, 0)?;
        }
        Ok(vec![])
    });
    reg(t, "move", |it, a| {
        let a1 = check_tab(it, &a, 0)?;
        let f = check_int(it, &a, 1)?;
        let e = check_int(it, &a, 2)?;
        let tpos = check_int(it, &a, 3)?;
        let tt = if is_none_or_nil(&a, 4) { a1.clone() } else { check_tab(it, &a, 4)? };
        if e >= f {
            if !(f > 0 || e < i64::MAX + f) {
                return Err(it.arg_error(3, "too many elements to move"));
            }
            if tpos > e || tpos <= f || (!is_none_or_nil(&a, 4) && !a1.raw_eq(&tt)) {
                for i in 0..=(e - f) {
                    let v = tget(it, &a1, f + i)?;
                    tset(it, &tt, tpos + i, v)?;
                }
            } else {
                let mut i = e - f;
                loop {
                    let v = tget(it, &a1, f + i)?;
                    tset(it, &tt, tpos + i, v)?;
                    if i == 0 {
                        break;
                    }
                    i -= 1;
                }
            }
        }
        one(tt)
    });
}

// ---------------- math ----------------

fn rng_next() -> u64 {
    RNG.with(|r| {
        let mut s = r.borrow_mut();
        let result = s[1].wrapping_mul(5).rotate_left(7).wrapping_mul(9);
        let t = s[1] << 17;
        s[2] ^= s[0];
        s[3] ^= s[1];
        s[1] ^= s[2];
        s[0] ^= s[3];
        s[2] ^= t;
        s[3] = s[3].rotate_left(45);
        result
    })
}

fn rng_seed(a: u64, b: u64) {
    RNG.with(|r| {
        let mut s = r.borrow_mut();
        s[0] = a;
        s[1] = 0xff;
        s[2] = b;
        s[3] = 0;
    });
    for _ in 0..16 {
        rng_next();
    }
}

pub fn seed_random() {
    let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
    rng_seed(t, std::process::id() as u64);
}

fn open_math(m: &TableRef) {
    m.borrow_mut().set(Val::str("pi"), Val::Num(std::f64::consts::PI));
    m.borrow_mut().set(Val::str("huge"), Val::Num(f64::INFINITY));
    m.borrow_mut().set(Val::str("maxinteger"), Val::Int(i64::MAX));
    m.borrow_mut().set(Val::str("mininteger"), Val::Int(i64::MIN));
    reg(m, "abs", |it, a| match check_number(it, &a, 0)? {
        Val::Int(i) => one(Val::Int(i.wrapping_abs())),
        Val::Num(f) => one(Val::Num(f.abs())),
        _ => unreachable!(),
    });
    reg(m, "ceil", |it, a| match check_number(it, &a, 0)? {
        Val::Int(i) => one(Val::Int(i)),
        Val::Num(f) => {
            let c = f.ceil();
            one(match float_to_int_exact(c) {
                Some(i) => Val::Int(i),
                None => Val::Num(c),
            })
        }
        _ => unreachable!(),
    });
    reg(m, "floor", |it, a| match check_number(it, &a, 0)? {
        Val::Int(i) => one(Val::Int(i)),
        Val::Num(f) => {
            let c = f.floor();
            one(match float_to_int_exact(c) {
                Some(i) => Val::Int(i),
                None => Val::Num(c),
            })
        }
        _ => unreachable!(),
    });
    reg(m, "fmod", |it, a| {
        let x = check_number(it, &a, 0)?;
        let y = check_number(it, &a, 1)?;
        if let (Val::Int(a1), Val::Int(b1)) = (&x, &y) {
            if *b1 == 0 {
                return Err(it.arg_error(2, "zero"));
            }
            if *b1 == -1 {
                return one(Val::Int(0));
            }
            return one(Val::Int(a1 % b1));
        }
        let xf = match x {
            Val::Int(i) => i as f64,
            Val::Num(f) => f,
            _ => 0.0,
        };
        let yf = match y {
            Val::Int(i) => i as f64,
            Val::Num(f) => f,
            _ => 0.0,
        };
        one(Val::Num(xf % yf))
    });
    reg(m, "modf", |it, a| {
        let x = check_num(it, &a, 0)?;
        let ip = if x.is_infinite() { x } else { x.trunc() };
        let fp = if x.is_infinite() { 0.0 } else { x - ip };
        let ipv = match float_to_int_exact(ip) {
            Some(_) => Val::Num(ip),
            None => Val::Num(ip),
        };
        Ok(vec![ipv, Val::Num(fp)])
    });
    reg(m, "sqrt", |it, a| one(Val::Num(check_num(it, &a, 0)?.sqrt())));
    reg(m, "sin", |it, a| one(Val::Num(check_num(it, &a, 0)?.sin())));
    reg(m, "cos", |it, a| one(Val::Num(check_num(it, &a, 0)?.cos())));
    reg(m, "tan", |it, a| one(Val::Num(check_num(it, &a, 0)?.tan())));
    reg(m, "asin", |it, a| one(Val::Num(check_num(it, &a, 0)?.asin())));
    reg(m, "acos", |it, a| one(Val::Num(check_num(it, &a, 0)?.acos())));
    reg(m, "atan", |it, a| {
        let y = check_num(it, &a, 0)?;
        let x = opt_num(it, &a, 1, 1.0)?;
        one(Val::Num(y.atan2(x)))
    });
    reg(m, "exp", |it, a| one(Val::Num(check_num(it, &a, 0)?.exp())));
    reg(m, "log", |it, a| {
        let x = check_num(it, &a, 0)?;
        if is_none_or_nil(&a, 1) {
            return one(Val::Num(x.ln()));
        }
        let b = check_num(it, &a, 1)?;
        let r = if b == 2.0 {
            x.log2()
        } else if b == 10.0 {
            x.log10()
        } else {
            x.ln() / b.ln()
        };
        one(Val::Num(r))
    });
    reg(m, "deg", |it, a| one(Val::Num(check_num(it, &a, 0)? * (180.0 / std::f64::consts::PI))));
    reg(m, "rad", |it, a| one(Val::Num(check_num(it, &a, 0)? * (std::f64::consts::PI / 180.0))));
    reg(m, "tointeger", |_it, a| {
        let v = arg(&a, 0);
        one(match &v {
            Val::Int(i) => Val::Int(*i),
            Val::Num(f) => match float_to_int_exact(*f) {
                Some(i) => Val::Int(i),
                None => Val::Nil,
            },
            Val::Str(s) => match str2number(s) {
                Some(Val::Int(i)) => Val::Int(i),
                Some(Val::Num(f)) => match float_to_int_exact(f) {
                    Some(i) => Val::Int(i),
                    None => Val::Nil,
                },
                _ => Val::Nil,
            },
            _ => Val::Nil,
        })
    });
    reg(m, "type", |it, a| {
        let v = check_any(it, &a, 0)?;
        one(match v {
            Val::Int(_) => Val::str("integer"),
            Val::Num(_) => Val::str("float"),
            _ => Val::Nil,
        })
    });
    reg(m, "ult", |it, a| {
        let x = check_int(it, &a, 0)?;
        let y = check_int(it, &a, 1)?;
        one(Val::Bool((x as u64) < (y as u64)))
    });
    reg(m, "max", |it, a| {
        if a.is_empty() {
            return Err(it.arg_error(1, "value expected"));
        }
        let mut best = check_number(it, &a, 0)?;
        for i in 1..a.len() {
            let v = check_number(it, &a, i)?;
            if it.less_than(&best, &v, 0)? {
                best = v;
            }
        }
        one(best)
    });
    reg(m, "min", |it, a| {
        if a.is_empty() {
            return Err(it.arg_error(1, "value expected"));
        }
        let mut best = check_number(it, &a, 0)?;
        for i in 1..a.len() {
            let v = check_number(it, &a, i)?;
            if it.less_than(&v, &best, 0)? {
                best = v;
            }
        }
        one(best)
    });
    reg(m, "random", |it, a| {
        let rv = rng_next();
        let (low, up) = match a.len() {
            0 => {
                let f = (rv >> 11) as f64 * (0.5 / ((1u64 << 52) as f64));
                return one(Val::Num(f));
            }
            1 => (1, check_int(it, &a, 0)?),
            2 => (check_int(it, &a, 0)?, check_int(it, &a, 1)?),
            _ => return Err(it.error_native("wrong number of arguments")),
        };
        if low > up {
            let n = if a.len() == 1 { 1 } else { 2 };
            return Err(it.arg_error(n, "interval is empty"));
        }
        let range = (up as u64).wrapping_sub(low as u64);
        let r = if range == u64::MAX {
            rv
        } else {
            // project
            let lim = range;
            let mut x = rv;
            if lim & (lim + 1) == 0 {
                x & lim
            } else {
                let mut l = lim;
                l |= l >> 1;
                l |= l >> 2;
                l |= l >> 4;
                l |= l >> 8;
                l |= l >> 16;
                l |= l >> 32;
                loop {
                    x &= l;
                    if x <= lim {
                        break x;
                    }
                    x = rng_next();
                }
            }
        };
        one(Val::Int((low as u64).wrapping_add(r) as i64))
    });
    reg(m, "randomseed", |it, a| {
        if a.is_empty() {
            seed_random();
            return Ok(vec![]);
        }
        let n1 = check_int(it, &a, 0)?;
        let n2 = opt_int(it, &a, 1, 0)?;
        rng_seed(n1 as u64, n2 as u64);
        Ok(vec![Val::Int(n1), Val::Int(n2)])
    });
}

// ---------------- os ----------------

fn getfield(it: &mut Interp, t: &TableRef, key: &str, d: Option<i64>, delta: i64) -> LResult<i64> {
    let v = t.borrow().get_str(key);
    match tointeger(&v) {
        Some(i) => {
            if !(i >= 0 && i - delta <= i32::MAX as i64 || i < 0 && i - delta >= i32::MIN as i64) {
                let m = format!("field '{}' is out-of-bound", key);
                return Err(it.error_native(&m));
            }
            Ok(i - delta)
        }
        None => {
            if !matches!(v, Val::Nil) {
                let m = format!("field '{}' is not an integer", key);
                return Err(it.error_native(&m));
            }
            match d {
                Some(dv) => Ok(dv),
                None => {
                    let m = format!("field '{}' missing in date table", key);
                    Err(it.error_native(&m))
                }
            }
        }
    }
}

fn set_date_fields(t: &TableRef, tm: &super::ffi::Tm) {
    let mut tb = t.borrow_mut();
    tb.set(Val::str("year"), Val::Int(tm.tm_year as i64 + 1900));
    tb.set(Val::str("month"), Val::Int(tm.tm_mon as i64 + 1));
    tb.set(Val::str("day"), Val::Int(tm.tm_mday as i64));
    tb.set(Val::str("hour"), Val::Int(tm.tm_hour as i64));
    tb.set(Val::str("min"), Val::Int(tm.tm_min as i64));
    tb.set(Val::str("sec"), Val::Int(tm.tm_sec as i64));
    tb.set(Val::str("yday"), Val::Int(tm.tm_yday as i64 + 1));
    tb.set(Val::str("wday"), Val::Int(tm.tm_wday as i64 + 1));
    if tm.tm_isdst >= 0 {
        tb.set(Val::str("isdst"), Val::Bool(tm.tm_isdst != 0));
    }
}

fn open_os(o: &TableRef) {
    reg(o, "time", |it, a| {
        if is_none_or_nil(&a, 0) {
            return one(Val::Int(super::ffi::now()));
        }
        let t = check_table(it, &a, 0)?;
        let mut tm = super::ffi::Tm::default();
        tm.tm_year = getfield(it, &t, "year", None, 1900)? as i32;
        tm.tm_mon = getfield(it, &t, "month", None, 1)? as i32;
        tm.tm_mday = getfield(it, &t, "day", None, 0)? as i32;
        tm.tm_hour = getfield(it, &t, "hour", Some(12), 0)? as i32;
        tm.tm_min = getfield(it, &t, "min", Some(0), 0)? as i32;
        tm.tm_sec = getfield(it, &t, "sec", Some(0), 0)? as i32;
        let isdst = t.borrow().get_str("isdst");
        tm.tm_isdst = if isdst.is_nil() { -1 } else if isdst.truthy() { 1 } else { 0 };
        let r = super::ffi::c_mktime(&mut tm);
        set_date_fields(&t, &tm);
        if r == -1 {
            return Err(it.error_native("time result cannot be represented in this installation"));
        }
        one(Val::Int(r))
    });
    reg(o, "clock", |_it, _a| one(Val::Num(super::ffi::c_clock())));
    reg(o, "date", |it, a| {
        let fmt = opt_str(it, &a, 0, b"%c")?;
        let t = if is_none_or_nil(&a, 1) { super::ffi::now() } else { check_int(it, &a, 1)? };
        let mut f: &[u8] = &fmt;
        let utc = f.first() == Some(&b'!');
        if utc {
            f = &f[1..];
        }
        let tm = if utc { super::ffi::gmtime(t) } else { super::ffi::localtime(t) };
        let tm = match tm {
            Some(tm) => tm,
            None => return Err(it.error_native("date result cannot be represented in this installation")),
        };
        if f.starts_with(b"*t") {
            let tt = Table::new_ref();
            set_date_fields(&tt, &tm);
            return one(Val::Table(tt));
        }
        // validate conversions
        let valid: &[u8] = b"aAbBcdHIjmMpSUwWxXyYZ%";
        let valid_e: &[u8] = b"cCxXyY";
        let valid_o: &[u8] = b"deHImMSuUVwWy";
        let mut out = Vec::new();
        let mut i = 0;
        let all: &[u8] = b"aAbBcCdDeFgGhHIjmMnprRStTuUVwWxXyYzZ%";
        while i < f.len() {
            if f[i] != b'%' {
                out.push(f[i]);
                i += 1;
                continue;
            }
            i += 1;
            let (spec, len) = if i < f.len() && (f[i] == b'E' || f[i] == b'O') {
                let ok = i + 1 < f.len() && (if f[i] == b'E' { valid_e } else { valid_o }).contains(&f[i + 1]);
                if !ok {
                    let conv = String::from_utf8_lossy(&f[i..(i + 2).min(f.len())]).into_owned();
                    let m = format!("invalid conversion specifier '%{}'", conv);
                    return Err(it.arg_error(1, &m));
                }
                (f[i..i + 2].to_vec(), 2)
            } else if i < f.len() && all.contains(&f[i]) {
                (vec![f[i]], 1)
            } else {
                let conv = if i < f.len() { String::from_utf8_lossy(&f[i..i + 1]).into_owned() } else { String::new() };
                let m = format!("invalid conversion specifier '%{}'", conv);
                return Err(it.arg_error(1, &m));
            };
            let _ = valid;
            let mut cf = vec![b'%'];
            cf.extend_from_slice(&spec);
            out.extend_from_slice(&super::ffi::c_strftime(&cf, &tm));
            i += len;
        }
        one(Val::bytes(&out))
    });
    reg(o, "difftime", |it, a| {
        let t1 = check_int(it, &a, 0)?;
        let t2 = opt_int(it, &a, 1, 0)?;
        one(Val::Num((t1 - t2) as f64))
    });
    reg(o, "getenv", |it, a| {
        let n = check_str(it, &a, 0)?;
        let name = String::from_utf8_lossy(&n).into_owned();
        match std::env::var_os(&name) {
            Some(v) => {
                use std::os::unix::ffi::OsStrExt;
                one(Val::bytes(v.as_bytes()))
            }
            None => one(Val::Nil),
        }
    });
    reg(o, "exit", |it, a| {
        let code = match arg(&a, 0) {
            Val::Nil | Val::Bool(true) => 0,
            Val::Bool(false) => 1,
            _ => check_int(it, &a, 0)? as i32,
        };
        c_stdout_flush();
        let _ = std::io::stdout().flush();
        std::process::exit(code);
    });
    reg(o, "remove", |it, a| {
        let n = check_str(it, &a, 0)?;
        let name = String::from_utf8_lossy(&n).into_owned();
        let r = match std::fs::metadata(&name) {
            Ok(m) if m.is_dir() => std::fs::remove_dir(&name),
            _ => std::fs::remove_file(&name),
        };
        match r {
            Ok(_) => one(Val::Bool(true)),
            Err(e) => Ok(vec![Val::Nil, Val::str(&format!("{}: {}", name, ioerr(&e))), Val::Int(e.raw_os_error().unwrap_or(0) as i64)]),
        }
    });
    reg(o, "rename", |it, a| {
        let n1 = check_str(it, &a, 0)?;
        let n2 = check_str(it, &a, 1)?;
        let a1 = String::from_utf8_lossy(&n1).into_owned();
        let a2 = String::from_utf8_lossy(&n2).into_owned();
        match std::fs::rename(&a1, &a2) {
            Ok(_) => one(Val::Bool(true)),
            Err(e) => Ok(vec![Val::Nil, Val::str(&format!("{}: {}", a1, ioerr(&e))), Val::Int(e.raw_os_error().unwrap_or(0) as i64)]),
        }
    });
    reg(o, "tmpname", |_it, _a| {
        let n = format!("/tmp/lua_{:06x}", rng_next() & 0xffffff);
        one(Val::str(&n))
    });
    reg(o, "setlocale", |_it, a| {
        match arg(&a, 0) {
            Val::Nil => one(Val::str("C")),
            Val::Str(s) if s.is_empty() || &s[..] == b"C" || &s[..] == b"POSIX" => one(Val::str("C")),
            _ => one(Val::Nil),
        }
    });
    reg(o, "execute", |_it, a| {
        c_stdout_flush();
        let _ = std::io::stdout().flush();
        match arg(&a, 0) {
            Val::Nil => one(Val::Bool(super::ffi::c_system(None) != 0)),
            v => {
                let cmd = match &v {
                    Val::Str(s) => s.to_vec(),
                    _ => number_to_str(&v),
                };
                let stat = super::ffi::c_system(Some(&cmd));
                if stat == -1 {
                    return Ok(vec![Val::Nil, Val::str("exit"), Val::Int(-1)]);
                }
                let (what, code) = if stat & 0x7f == 0 { ("exit", (stat >> 8) & 0xff) } else { ("signal", stat & 0x7f) };
                let ok = what == "exit" && code == 0;
                Ok(vec![if ok { Val::Bool(true) } else { Val::Nil }, Val::str(what), Val::Int(code as i64)])
            }
        }
    });
}

// ---------------- io ----------------

fn open_io(io: &TableRef) {
    reg(io, "write", |it, a| {
        for (i, v) in a.iter().enumerate() {
            match v {
                Val::Str(s) => c_stdout_write(s),
                Val::Int(_) | Val::Num(_) => {
                    let s = if let Val::Int(n) = v { n.to_string().into_bytes() } else { super::ffi::fmt_float("%.14g", if let Val::Num(f) = v { *f } else { 0.0 }).into_bytes() };
                    c_stdout_write(&s);
                }
                _ => {
                    let v = v.clone();
                    return Err(it.type_error(i + 1, "string", Some(&v)));
                }
            }
        }
        let out = it.globals.borrow().get_str("io");
        let stdout = if let Val::Table(t) = out { t.borrow().get_str("stdout") } else { Val::Nil };
        one(stdout)
    });
    reg(io, "read", |_it, _a| one(Val::Nil));
    let mkfile = |name: &'static str, is_err: bool| -> Val {
        let t = Table::new_ref();
        let mt = Table::new_ref();
        let methods = Table::new_ref();
        reg(&methods, "write", move |it, a| {
            for (i, v) in a.iter().enumerate().skip(1) {
                let bytes = match v {
                    Val::Str(s) => s.to_vec(),
                    Val::Int(_) | Val::Num(_) => number_to_str(v),
                    _ => {
                        let v = v.clone();
                        return Err(it.type_error(i, "string", Some(&v)));
                    }
                };
                if is_err {
                    let _ = std::io::stderr().write_all(&bytes);
                } else {
                    c_stdout_write(&bytes);
                }
            }
            one(arg(&a, 0))
        });
        reg(&methods, "flush", move |_it, a| {
            if !is_err {
                c_stdout_flush();
            }
            one(arg(&a, 0))
        });
        reg(&methods, "close", |_it, _a| one(Val::Bool(true)));
        reg(&methods, "setvbuf", |_it, _a| one(Val::Bool(true)));
        mt.borrow_mut().set(Val::str("__index"), Val::Table(methods));
        mt.borrow_mut().set(Val::str("__name"), Val::str("FILE*"));
        let nm = name;
        reg(&mt, "__tostring", move |it, a| {
            let addr = arg(&a, 0).ptr_addr();
            let _ = it;
            let _ = nm;
            one(Val::str(&format!("file (0x{:012x})", addr)))
        });
        t.borrow_mut().meta = Some(mt);
        Val::Table(t)
    };
    io.borrow_mut().set(Val::str("stdout"), mkfile("stdout", false));
    io.borrow_mut().set(Val::str("stderr"), mkfile("stderr", true));
    io.borrow_mut().set(Val::str("stdin"), mkfile("stdin", false));
    reg(io, "open", |it, a| {
        let n = check_str(it, &a, 0)?;
        let name = String::from_utf8_lossy(&n).into_owned();
        Ok(vec![Val::Nil, Val::str(&format!("{}: Operation not permitted", name)), Val::Int(1)])
    });
    reg(io, "lines", |it, a| {
        let n = opt_str(it, &a, 0, b"")?;
        let name = String::from_utf8_lossy(&n).into_owned();
        let m = format!("{}: No such file or directory", name);
        Err(it.error_native(&m))
    });
    reg(io, "close", |_it, _a| one(Val::Bool(true)));
    reg(io, "flush", |_it, _a| {
        c_stdout_flush();
        Ok(vec![])
    });
    reg(io, "type", |_it, a| match arg(&a, 0) {
        Val::Table(t) => {
            let is_file = t.borrow().meta.as_ref().map(|m| matches!(m.borrow().get_str("__name"), Val::Str(ref s) if &s[..] == b"FILE*")).unwrap_or(false);
            one(if is_file { Val::str("file") } else { Val::Nil })
        }
        _ => one(Val::Nil),
    });
    reg(io, "popen", |it, _a| Err(it.error_native("'popen' not supported")));
    reg(io, "tmpfile", |_it, _a| one(Val::Nil));
    reg(io, "input", |_it, _a| one(Val::Nil));
    reg(io, "output", |_it, _a| one(Val::Nil));
}

// ---------------- utf8 ----------------

fn utf8_decode(s: &[u8], i: usize, strict: bool) -> Option<(u32, usize)> {
    let c = s[i] as u32;
    if c < 0x80 {
        return Some((c, 1));
    }
    let limits: [u32; 6] = [!0, 0x80, 0x800, 0x10000, 0x200000, 0x4000000];
    let mut res: u32 = 0;
    let mut count = 0usize;
    let mut cc = c;
    while cc & 0x40 != 0 {
        count += 1;
        if i + count >= s.len() {
            return None;
        }
        let nc = s[i + count] as u32;
        if nc & 0xC0 != 0x80 {
            return None;
        }
        res = (res << 6) | (nc & 0x3F);
        cc <<= 1;
    }
    res |= (cc & 0x7F) << (count * 5);
    if count > 5 || res > 0x7FFFFFFF || res < limits[count] {
        return None;
    }
    if strict && (res > 0x10FFFF || (0xD800..=0xDFFF).contains(&res)) {
        return None;
    }
    Some((res, count + 1))
}

fn u_posrelat(pos: i64, len: usize) -> i64 {
    if pos >= 0 {
        pos
    } else if (-pos) as usize > len {
        0
    } else {
        len as i64 + pos + 1
    }
}

fn open_utf8(u: &TableRef) {
    u.borrow_mut().set(Val::str("charpattern"), Val::bytes(b"[\x00-\x7F\xC2-\xFD][\x80-\xBF]*"));
    reg(u, "char", |it, a| {
        let mut out = Vec::new();
        for i in 0..a.len() {
            let c = check_int(it, &a, i)?;
            if (c as u64) > 0x7FFFFFFF {
                return Err(it.arg_error(i + 1, "value out of range"));
            }
            out.extend_from_slice(&super::lexer::utf8_encode(c as u32));
        }
        one(Val::bytes(&out))
    });
    reg(u, "len", |it, a| {
        let s = check_str(it, &a, 0)?;
        let mut posi = u_posrelat(opt_int(it, &a, 1, 1)?, s.len());
        let mut posj = u_posrelat(opt_int(it, &a, 2, -1)?, s.len());
        let lax = arg(&a, 3).truthy();
        if !(1 <= posi && posi - 1 <= s.len() as i64) {
            return Err(it.arg_error(2, "initial position out of bounds"));
        }
        posi -= 1;
        if posj - 1 >= s.len() as i64 {
            return Err(it.arg_error(3, "final position out of bounds"));
        }
        posj -= 1;
        let mut n = 0;
        while posi <= posj {
            match utf8_decode(&s, posi as usize, !lax) {
                None => return Ok(vec![Val::Nil, Val::Int(posi + 1)]),
                Some((_, l)) => {
                    posi += l as i64;
                    n += 1;
                }
            }
        }
        one(Val::Int(n))
    });
    reg(u, "codepoint", |it, a| {
        let s = check_str(it, &a, 0)?;
        let posi = u_posrelat(opt_int(it, &a, 1, 1)?, s.len());
        let pose = u_posrelat(opt_int(it, &a, 2, posi)?, s.len());
        let lax = arg(&a, 3).truthy();
        if posi < 1 {
            return Err(it.arg_error(2, "out of bounds"));
        }
        if pose > s.len() as i64 {
            return Err(it.arg_error(3, "out of bounds"));
        }
        let mut out = Vec::new();
        let mut p = posi - 1;
        while p < pose {
            match utf8_decode(&s, p as usize, !lax) {
                None => return Err(it.error_native("invalid UTF-8 code")),
                Some((c, l)) => {
                    out.push(Val::Int(c as i64));
                    p += l as i64;
                }
            }
        }
        Ok(out)
    });
    reg(u, "offset", |it, a| {
        let s = check_str(it, &a, 0)?;
        let n = check_int(it, &a, 1)?;
        let defi = if n >= 0 { 1 } else { s.len() as i64 + 1 };
        let mut posi = u_posrelat(opt_int(it, &a, 2, defi)?, s.len()) - 1;
        let len = s.len() as i64;
        if !(0 <= posi && posi <= len) {
            return Err(it.arg_error(3, "position out of bounds"));
        }
        let iscont = |p: i64| p < len && (s[p as usize] & 0xC0) == 0x80;
        let mut n = n;
        if n == 0 {
            while posi > 0 && iscont(posi) {
                posi -= 1;
            }
            return one(Val::Int(posi + 1));
        }
        if iscont(posi) {
            return Err(it.error_native("initial position is a continuation byte"));
        }
        if n < 0 {
            while n < 0 && posi > 0 {
                loop {
                    posi -= 1;
                    if !(posi > 0 && iscont(posi)) {
                        break;
                    }
                }
                n += 1;
            }
        } else {
            n -= 1;
            while n > 0 && posi < len {
                loop {
                    posi += 1;
                    if !iscont(posi) {
                        break;
                    }
                }
                n -= 1;
            }
        }
        if n == 0 {
            one(Val::Int(posi + 1))
        } else {
            one(Val::Nil)
        }
    });
    reg(u, "codes", |it, a| {
        let s = check_str(it, &a, 0)?;
        let lax = arg(&a, 1).truthy();
        let iter = mk_native("codes_iter", move |it, a| {
            let s = check_str(it, &a, 0)?;
            let mut i = tointeger(&arg(&a, 1)).unwrap_or(0) as usize;
            if i > 0 {
                while i < s.len() && (s[i] & 0xC0) == 0x80 {
                    i += 1;
                }
            }
            if i >= s.len() {
                return one(Val::Nil);
            }
            let _ = i;
            let mut j = i;
            if i > 0 || tointeger(&arg(&a, 1)).unwrap_or(0) > 0 {
                // already advanced
            }
            if tointeger(&arg(&a, 1)).unwrap_or(0) == 0 {
                j = 0;
            }
            match utf8_decode(&s, j, !lax) {
                None => Err(it.error_native("invalid UTF-8 code")),
                Some((c, _)) => Ok(vec![Val::Int(j as i64 + 1), Val::Int(c as i64)]),
            }
        });
        Ok(vec![iter, Val::Str(s), Val::Int(0)])
    });
}

pub fn tonumber_val(v: &Val) -> Option<Val> {
    tonumber(v)
}
