use super::args::*;
use super::interp::{Interp, LResult};
use super::stdlib::{mk_native, reg};
use super::value::*;

const L_ESC: u8 = b'%';
const SPECIALS: &[u8] = b"^$*+?.([%-";
const CAP_UNFINISHED: isize = -1;
const CAP_POSITION: isize = -2;
const MAXCAPTURES: usize = 32;
const MAXCCALLS: usize = 200;

pub struct MatchState<'a> {
    src: &'a [u8],
    pat: &'a [u8],
    level: usize,
    capture: [(usize, isize); MAXCAPTURES],
    matchdepth: usize,
}

type MR = Result<Option<usize>, String>;

fn c_isalpha(c: u8) -> bool {
    c.is_ascii_alphabetic()
}
fn c_iscntrl(c: u8) -> bool {
    c < 32 || c == 127
}
fn c_isgraph(c: u8) -> bool {
    (33..=126).contains(&c)
}
fn c_ispunct(c: u8) -> bool {
    c_isgraph(c) && !c.is_ascii_alphanumeric()
}
fn c_isspace(c: u8) -> bool {
    c == b' ' || (9..=13).contains(&c)
}

fn match_class(c: u8, cl: u8) -> bool {
    let res = match cl.to_ascii_lowercase() {
        b'a' => c_isalpha(c),
        b'c' => c_iscntrl(c),
        b'd' => c.is_ascii_digit(),
        b'g' => c_isgraph(c),
        b'l' => c.is_ascii_lowercase(),
        b'p' => c_ispunct(c),
        b's' => c_isspace(c),
        b'u' => c.is_ascii_uppercase(),
        b'w' => c.is_ascii_alphanumeric(),
        b'x' => c.is_ascii_hexdigit(),
        _ => return cl == c,
    };
    if cl.is_ascii_uppercase() {
        !res
    } else {
        res
    }
}

impl<'a> MatchState<'a> {
    fn new(src: &'a [u8], pat: &'a [u8]) -> Self {
        MatchState { src, pat, level: 0, capture: [(0, 0); MAXCAPTURES], matchdepth: MAXCCALLS }
    }
    fn reprep(&mut self) {
        self.level = 0;
        self.matchdepth = MAXCCALLS;
    }
    fn p(&self, i: usize) -> u8 {
        if i < self.pat.len() {
            self.pat[i]
        } else {
            0
        }
    }
    fn s(&self, i: usize) -> u8 {
        if i < self.src.len() {
            self.src[i]
        } else {
            0
        }
    }
    fn class_end(&self, p: usize) -> Result<usize, String> {
        let mut p = p;
        let c = self.p(p);
        p += 1;
        if c == L_ESC {
            if p >= self.pat.len() {
                return Err("malformed pattern (ends with '%')".into());
            }
            return Ok(p + 1);
        }
        if c == b'[' {
            if self.p(p) == b'^' {
                p += 1;
            }
            loop {
                if p >= self.pat.len() {
                    return Err("malformed pattern (missing ']')".into());
                }
                let cc = self.pat[p];
                p += 1;
                if cc == L_ESC && p < self.pat.len() {
                    p += 1;
                }
                if self.p(p) == b']' {
                    break;
                }
            }
            return Ok(p + 1);
        }
        Ok(p)
    }
    fn match_bracket_class(&self, c: u8, p: usize, ec: usize) -> bool {
        let mut sig = true;
        let mut p = p;
        if self.p(p + 1) == b'^' {
            sig = false;
            p += 1;
        }
        loop {
            p += 1;
            if p >= ec {
                break;
            }
            if self.p(p) == L_ESC {
                p += 1;
                if match_class(c, self.p(p)) {
                    return sig;
                }
            } else if self.p(p + 1) == b'-' && p + 2 < ec {
                p += 2;
                if self.p(p - 2) <= c && c <= self.p(p) {
                    return sig;
                }
            } else if self.p(p) == c {
                return sig;
            }
        }
        !sig
    }
    fn single_match(&self, s: usize, p: usize, ep: usize) -> bool {
        if s >= self.src.len() {
            return false;
        }
        let c = self.src[s];
        match self.p(p) {
            b'.' => true,
            L_ESC => match_class(c, self.p(p + 1)),
            b'[' => self.match_bracket_class(c, p, ep - 1),
            pc => pc == c,
        }
    }
    fn match_balance(&self, s: usize, p: usize) -> MR {
        if p + 1 >= self.pat.len() {
            return Err("malformed pattern (missing arguments to '%b')".into());
        }
        if s >= self.src.len() || self.src[s] != self.pat[p] {
            return Ok(None);
        }
        let b = self.pat[p];
        let e = self.pat[p + 1];
        let mut cont = 1;
        let mut s = s;
        loop {
            s += 1;
            if s >= self.src.len() {
                break;
            }
            let c = self.src[s];
            if c == e {
                cont -= 1;
                if cont == 0 {
                    return Ok(Some(s + 1));
                }
            } else if c == b {
                cont += 1;
            }
        }
        Ok(None)
    }
    fn max_expand(&mut self, s: usize, p: usize, ep: usize) -> MR {
        let mut i = 0usize;
        while self.single_match(s + i, p, ep) {
            i += 1;
        }
        loop {
            let r = self.do_match(s + i, ep + 1)?;
            if r.is_some() {
                return Ok(r);
            }
            if i == 0 {
                return Ok(None);
            }
            i -= 1;
        }
    }
    fn min_expand(&mut self, s: usize, p: usize, ep: usize) -> MR {
        let mut s = s;
        loop {
            let r = self.do_match(s, ep + 1)?;
            if r.is_some() {
                return Ok(r);
            } else if self.single_match(s, p, ep) {
                s += 1;
            } else {
                return Ok(None);
            }
        }
    }
    fn start_capture(&mut self, s: usize, p: usize, what: isize) -> MR {
        let level = self.level;
        if level >= MAXCAPTURES {
            return Err("too many captures".into());
        }
        self.capture[level] = (s, what);
        self.level = level + 1;
        let r = self.do_match(s, p)?;
        if r.is_none() {
            self.level -= 1;
        }
        Ok(r)
    }
    fn capture_to_close(&self) -> Result<usize, String> {
        let mut level = self.level as isize - 1;
        while level >= 0 {
            if self.capture[level as usize].1 == CAP_UNFINISHED {
                return Ok(level as usize);
            }
            level -= 1;
        }
        Err("invalid pattern capture".into())
    }
    fn end_capture(&mut self, s: usize, p: usize) -> MR {
        let l = self.capture_to_close()?;
        self.capture[l].1 = (s - self.capture[l].0) as isize;
        let r = self.do_match(s, p)?;
        if r.is_none() {
            self.capture[l].1 = CAP_UNFINISHED;
        }
        Ok(r)
    }
    fn check_capture(&self, l: u8) -> Result<usize, String> {
        let l = l as isize - b'1' as isize;
        if l < 0 || l as usize >= self.level || self.capture[l as usize].1 == CAP_UNFINISHED {
            return Err(format!("invalid capture index %{}", l + 1));
        }
        Ok(l as usize)
    }
    fn match_capture(&self, s: usize, l: u8) -> MR {
        let l = self.check_capture(l)?;
        let (init, len) = self.capture[l];
        let len = len as usize;
        if self.src.len() - s >= len && self.src[init..init + len] == self.src[s..s + len] {
            Ok(Some(s + len))
        } else {
            Ok(None)
        }
    }
    pub fn do_match(&mut self, s: usize, p: usize) -> MR {
        if self.matchdepth == 0 {
            return Err("pattern too complex".into());
        }
        self.matchdepth -= 1;
        let mut s = s;
        let mut p = p;
        let result: Option<usize>;
        loop {
            if p >= self.pat.len() {
                result = Some(s);
                break;
            }
            match self.pat[p] {
                b'(' => {
                    result = if self.p(p + 1) == b')' { self.start_capture(s, p + 2, CAP_POSITION)? } else { self.start_capture(s, p + 1, CAP_UNFINISHED)? };
                    break;
                }
                b')' => {
                    result = self.end_capture(s, p + 1)?;
                    break;
                }
                b'$' if p + 1 == self.pat.len() => {
                    result = if s == self.src.len() { Some(s) } else { None };
                    break;
                }
                L_ESC if self.p(p + 1) == b'b' => {
                    match self.match_balance(s, p + 2)? {
                        Some(ns) => {
                            s = ns;
                            p += 4;
                            continue;
                        }
                        None => {
                            result = None;
                            break;
                        }
                    }
                }
                L_ESC if self.p(p + 1) == b'f' => {
                    p += 2;
                    if self.p(p) != b'[' {
                        return Err("missing '[' after '%f' in pattern".into());
                    }
                    let ep = self.class_end(p)?;
                    let previous = if s == 0 { 0 } else { self.src[s - 1] };
                    if !self.match_bracket_class(previous, p, ep - 1) && self.match_bracket_class(self.s(s), p, ep - 1) {
                        p = ep;
                        continue;
                    }
                    result = None;
                    break;
                }
                L_ESC if self.p(p + 1).is_ascii_digit() => {
                    match self.match_capture(s, self.p(p + 1))? {
                        Some(ns) => {
                            s = ns;
                            p += 2;
                            continue;
                        }
                        None => {
                            result = None;
                            break;
                        }
                    }
                }
                _ => {
                    let ep = self.class_end(p)?;
                    let epc = self.p(ep);
                    if !self.single_match(s, p, ep) {
                        if epc == b'*' || epc == b'?' || epc == b'-' {
                            p = ep + 1;
                            continue;
                        }
                        result = None;
                        break;
                    }
                    match epc {
                        b'?' => {
                            let r = self.do_match(s + 1, ep + 1)?;
                            if r.is_some() {
                                result = r;
                                break;
                            }
                            p = ep + 1;
                            continue;
                        }
                        b'+' => {
                            result = self.max_expand(s + 1, p, ep)?;
                            break;
                        }
                        b'*' => {
                            result = self.max_expand(s, p, ep)?;
                            break;
                        }
                        b'-' => {
                            result = self.min_expand(s, p, ep)?;
                            break;
                        }
                        _ => {
                            s += 1;
                            p = ep;
                            continue;
                        }
                    }
                }
            }
        }
        self.matchdepth += 1;
        Ok(result)
    }

    fn get_onecapture(&self, i: usize, s: usize, e: usize) -> Result<Val, String> {
        if i >= self.level {
            if i != 0 {
                return Err(format!("invalid capture index %{}", i + 1));
            }
            return Ok(Val::bytes(&self.src[s..e]));
        }
        let (init, len) = self.capture[i];
        if len == CAP_UNFINISHED {
            return Err("unfinished capture".into());
        }
        if len == CAP_POSITION {
            return Ok(Val::Int(init as i64 + 1));
        }
        Ok(Val::bytes(&self.src[init..init + len as usize]))
    }

    fn push_captures(&self, s: Option<usize>, e: usize, whole: bool) -> Result<Vec<Val>, String> {
        let nlevels = if self.level == 0 && whole { 1 } else { self.level };
        let mut out = Vec::with_capacity(nlevels);
        for i in 0..nlevels {
            out.push(self.get_onecapture(i, s.unwrap_or(0), e)?);
        }
        Ok(out)
    }
}

fn posrelat_i(pos: i64, len: usize) -> usize {
    if pos > 0 {
        pos as usize
    } else if pos == 0 {
        1
    } else if pos < -(len as i64) {
        1
    } else {
        (len as i64 + pos + 1) as usize
    }
}

fn getendpos(pos: i64, len: usize) -> usize {
    if pos > len as i64 {
        len
    } else if pos >= 0 {
        pos as usize
    } else if pos < -(len as i64) {
        0
    } else {
        (len as i64 + pos + 1) as usize
    }
}

fn nospecials(p: &[u8]) -> bool {
    !p.iter().any(|c| SPECIALS.contains(c))
}

fn find_sub(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if needle.len() > hay.len() {
        return None;
    }
    (0..=hay.len() - needle.len()).find(|&i| &hay[i..i + needle.len()] == needle)
}

fn str_find_aux(it: &mut Interp, a: Vec<Val>, find: bool) -> LResult<Vec<Val>> {
    let s = check_str(it, &a, 0)?;
    let p = check_str(it, &a, 1)?;
    let init = posrelat_i(opt_int(it, &a, 2, 1)?, s.len()) - 1;
    if init > s.len() {
        return Ok(vec![Val::Nil]);
    }
    if find && (arg(&a, 3).truthy() || nospecials(&p)) {
        if let Some(pos) = find_sub(&s[init..], &p) {
            let st = init + pos;
            return Ok(vec![Val::Int(st as i64 + 1), Val::Int((st + p.len()) as i64)]);
        }
        return Ok(vec![Val::Nil]);
    }
    let anchor = p.first() == Some(&b'^');
    let pat: &[u8] = if anchor { &p[1..] } else { &p[..] };
    let mut ms = MatchState::new(&s, pat);
    let mut s1 = init;
    loop {
        ms.reprep();
        match ms.do_match(s1, 0) {
            Err(e) => return Err(it.error_native(&e)),
            Ok(Some(res)) => {
                if find {
                    let mut out = vec![Val::Int(s1 as i64 + 1), Val::Int(res as i64)];
                    match ms.push_captures(None, 0, false) {
                        Ok(c) => out.extend(c),
                        Err(e) => return Err(it.error_native(&e)),
                    }
                    return Ok(out);
                } else {
                    return match ms.push_captures(Some(s1), res, true) {
                        Ok(c) => Ok(c),
                        Err(e) => Err(it.error_native(&e)),
                    };
                }
            }
            Ok(None) => {}
        }
        s1 += 1;
        if !(s1 <= s.len() && !anchor) {
            break;
        }
    }
    Ok(vec![Val::Nil])
}

fn add_value(it: &mut Interp, ms: &MatchState, b: &mut Vec<u8>, s: usize, e: usize, repl: &Val) -> LResult<bool> {
    let result = match repl {
        Val::Func(_) => {
            let caps = match ms.push_captures(Some(s), e, true) {
                Ok(c) => c,
                Err(m) => return Err(it.error_native(&m)),
            };
            let r = it.call(repl, caps, None)?;
            r.into_iter().next().unwrap_or(Val::Nil)
        }
        Val::Table(_) => {
            let k = match ms.get_onecapture(0, s, e) {
                Ok(k) => k,
                Err(m) => return Err(it.error_native(&m)),
            };
            it.index(repl.clone(), k, &super::ast::Expr::Nil, 0)?
        }
        _ => {
            // string / number
            let news: Vec<u8> = match repl {
                Val::Str(x) => x.to_vec(),
                _ => number_to_str(repl),
            };
            let mut i = 0;
            while i < news.len() {
                let c = news[i];
                if c != L_ESC {
                    b.push(c);
                    i += 1;
                    continue;
                }
                i += 1;
                let d = if i < news.len() { news[i] } else { 0 };
                if d == L_ESC {
                    b.push(L_ESC);
                } else if d == b'0' {
                    b.extend_from_slice(&ms.src[s..e]);
                } else if d.is_ascii_digit() {
                    match ms.get_onecapture((d - b'1') as usize, s, e) {
                        Ok(Val::Str(cs)) => b.extend_from_slice(&cs),
                        Ok(v @ Val::Int(_)) => b.extend_from_slice(&number_to_str(&v)),
                        Ok(_) => {}
                        Err(m) => return Err(it.error_native(&m)),
                    }
                } else {
                    return Err(it.error_native("invalid use of '%' in replacement string"));
                }
                i += 1;
            }
            return Ok(true);
        }
    };
    match &result {
        Val::Nil | Val::Bool(false) => {
            b.extend_from_slice(&ms.src[s..e]);
            Ok(false)
        }
        Val::Str(x) => {
            b.extend_from_slice(x);
            Ok(true)
        }
        Val::Int(_) | Val::Num(_) => {
            b.extend_from_slice(&number_to_str(&result));
            Ok(true)
        }
        other => {
            let tn = it.typename_of(other);
            let m = format!("invalid replacement value (a {})", tn);
            Err(it.error_native(&m))
        }
    }
}

fn add_quoted(b: &mut Vec<u8>, s: &[u8]) {
    b.push(b'"');
    for (i, &c) in s.iter().enumerate() {
        if c == b'"' || c == b'\\' || c == b'\n' {
            b.push(b'\\');
            b.push(c);
        } else if c_iscntrl(c) {
            let next = s.get(i + 1).copied().unwrap_or(0);
            if !next.is_ascii_digit() {
                b.extend_from_slice(format!("\\{}", c).as_bytes());
            } else {
                b.extend_from_slice(format!("\\{:03}", c).as_bytes());
            }
        } else {
            b.push(c);
        }
    }
    b.push(b'"');
}

fn checkformat(form: &[u8], flags: &[u8], precision: bool) -> bool {
    let mut i = 1;
    while i < form.len() && flags.contains(&form[i]) {
        i += 1;
    }
    let at = |i: usize| -> u8 {
        if i < form.len() {
            form[i]
        } else {
            0
        }
    };
    if at(i) != b'0' {
        if at(i).is_ascii_digit() {
            i += 1;
        }
        if at(i).is_ascii_digit() {
            i += 1;
        }
        if at(i) == b'.' && precision {
            i += 1;
            if at(i).is_ascii_digit() {
                i += 1;
            }
            if at(i).is_ascii_digit() {
                i += 1;
            }
        }
    }
    at(i).is_ascii_alphabetic()
}

fn str_format(it: &mut Interp, a: Vec<Val>) -> LResult<Vec<Val>> {
    let fmt = check_str(it, &a, 0)?;
    let top = a.len();
    let mut argi = 0usize;
    let mut b: Vec<u8> = Vec::new();
    let mut i = 0;
    let f = &fmt[..];
    while i < f.len() {
        if f[i] != L_ESC {
            b.push(f[i]);
            i += 1;
            continue;
        }
        i += 1;
        if i < f.len() && f[i] == L_ESC {
            b.push(L_ESC);
            i += 1;
            continue;
        }
        argi += 1;
        if argi >= top {
            return Err(it.arg_error(argi + 1, "no value"));
        }
        // getformat
        let allowed: &[u8] = b"-+ #0123456789.";
        let mut len = 0;
        while i + len < f.len() && allowed.contains(&f[i + len]) {
            len += 1;
        }
        len += 1;
        if len >= 32 - 10 {
            return Err(it.error_native("invalid format string to 'format'"));
        }
        let mut form: Vec<u8> = vec![b'%'];
        let end = (i + len).min(f.len());
        form.extend_from_slice(&f[i..end]);
        let conv = if i + len - 1 < f.len() { f[i + len - 1] } else { 0 };
        i += len;
        let formstr = |form: &[u8]| String::from_utf8_lossy(form).into_owned();
        match conv {
            b'c' => {
                if !checkformat(&form, b"-", false) {
                    let m = format!("invalid conversion specification: '{}'", formstr(&form));
                    return Err(it.error_native(&m));
                }
                let n = check_int(it, &a, argi)?;
                b.extend_from_slice(&super::ffi::fmt_cint(&formstr(&form), n as i32));
            }
            b'd' | b'i' | b'u' | b'o' | b'x' | b'X' => {
                let flags: &[u8] = match conv {
                    b'd' | b'i' => b"-+ 0",
                    b'u' => b"-0",
                    _ => b"-#0",
                };
                let n = check_int(it, &a, argi)?;
                if !checkformat(&form, flags, true) {
                    let m = format!("invalid conversion specification: '{}'", formstr(&form));
                    return Err(it.error_native(&m));
                }
                let mut fs = form.clone();
                fs.pop();
                fs.extend_from_slice(b"ll");
                fs.push(conv);
                b.extend_from_slice(super::ffi::fmt_int(&formstr(&fs), n).as_bytes());
            }
            b'a' | b'A' | b'f' | b'F' | b'e' | b'E' | b'g' | b'G' => {
                let n = check_num(it, &a, argi)?;
                if !checkformat(&form, b"-+ #0", true) {
                    let m = format!("invalid conversion specification: '{}'", formstr(&form));
                    return Err(it.error_native(&m));
                }
                b.extend_from_slice(super::ffi::fmt_float(&formstr(&form), n).as_bytes());
            }
            b'p' => {
                if !checkformat(&form, b"-", false) {
                    let m = format!("invalid conversion specification: '{}'", formstr(&form));
                    return Err(it.error_native(&m));
                }
                let v = arg(&a, argi);
                let addr = match &v {
                    Val::Table(_) | Val::Func(_) | Val::Str(_) => v.ptr_addr(),
                    _ => 0,
                };
                let mut fs = form.clone();
                fs.pop();
                if addr == 0 {
                    fs.push(b's');
                    b.extend_from_slice(&super::ffi::fmt_str(&formstr(&fs), b"(null)"));
                } else {
                    fs.push(b's');
                    b.extend_from_slice(&super::ffi::fmt_str(&formstr(&fs), format!("0x{:x}", addr).as_bytes()));
                }
            }
            b'q' => {
                if form.len() > 2 {
                    return Err(it.error_native("specifier '%q' cannot have modifiers"));
                }
                let v = arg(&a, argi);
                match &v {
                    Val::Str(s) => add_quoted(&mut b, s),
                    Val::Int(n) => {
                        if *n == i64::MIN {
                            b.extend_from_slice(format!("0x{:x}", n).as_bytes());
                        } else {
                            b.extend_from_slice(n.to_string().as_bytes());
                        }
                    }
                    Val::Num(x) => {
                        let s = if *x == f64::INFINITY {
                            "1e9999".to_string()
                        } else if *x == f64::NEG_INFINITY {
                            "-1e9999".to_string()
                        } else if x.is_nan() {
                            "(0/0)".to_string()
                        } else if x.floor() == *x && x.abs() < 1e15 {
                            // integral float: use %a-like representation like Lua (hex)
                            super::ffi::fmt_float("%a", *x)
                        } else {
                            super::ffi::fmt_float("%a", *x)
                        };
                        b.extend_from_slice(s.as_bytes());
                    }
                    Val::Nil | Val::Bool(_) => {
                        let s = it.tostring(&v)?;
                        b.extend_from_slice(&s);
                    }
                    _ => return Err(it.arg_error(argi + 1, "value has no literal form")),
                }
            }
            b's' => {
                let v = arg(&a, argi);
                let s = it.tostring(&v)?;
                if form.len() == 2 {
                    b.extend_from_slice(&s);
                } else {
                    if s.contains(&0) {
                        return Err(it.arg_error(argi + 1, "string contains zeros"));
                    }
                    if !checkformat(&form, b"-", true) {
                        let m = format!("invalid conversion specification: '{}'", formstr(&form));
                        return Err(it.error_native(&m));
                    }
                    if !form.contains(&b'.') && s.len() >= 100 {
                        b.extend_from_slice(&s);
                    } else {
                        b.extend_from_slice(&super::ffi::fmt_str(&formstr(&form), &s));
                    }
                }
            }
            _ => {
                let m = format!("invalid conversion '{}' to 'format'", formstr(&form));
                return Err(it.error_native(&m));
            }
        }
    }
    Ok(vec![Val::bytes(&b)])
}

pub fn open_string(it: &mut Interp, st: &TableRef) {
    reg(st, "len", |it, a| {
        let s = check_str(it, &a, 0)?;
        Ok(vec![Val::Int(s.len() as i64)])
    });
    reg(st, "sub", |it, a| {
        let s = check_str(it, &a, 0)?;
        let l = s.len();
        let start = posrelat_i(check_int(it, &a, 1)?, l);
        let e = getendpos(opt_int(it, &a, 2, -1)?, l);
        if start <= e {
            Ok(vec![Val::bytes(&s[start - 1..e])])
        } else {
            Ok(vec![Val::str("")])
        }
    });
    reg(st, "upper", |it, a| {
        let s = check_str(it, &a, 0)?;
        let v: Vec<u8> = s.iter().map(|c| c.to_ascii_uppercase()).collect();
        Ok(vec![Val::bytes(&v)])
    });
    reg(st, "lower", |it, a| {
        let s = check_str(it, &a, 0)?;
        let v: Vec<u8> = s.iter().map(|c| c.to_ascii_lowercase()).collect();
        Ok(vec![Val::bytes(&v)])
    });
    reg(st, "rep", |it, a| {
        let s = check_str(it, &a, 0)?;
        let n = check_int(it, &a, 1)?;
        let sep = opt_str(it, &a, 2, b"")?;
        if n <= 0 {
            return Ok(vec![Val::str("")]);
        }
        let total = (s.len() as u128 + sep.len() as u128) * n as u128;
        if total >= 0x7fffffff {
            return Err(it.error_native("resulting string too large"));
        }
        let mut out = Vec::with_capacity(total as usize);
        for i in 0..n {
            out.extend_from_slice(&s);
            if i + 1 < n {
                out.extend_from_slice(&sep);
            }
        }
        Ok(vec![Val::bytes(&out)])
    });
    reg(st, "reverse", |it, a| {
        let s = check_str(it, &a, 0)?;
        let v: Vec<u8> = s.iter().rev().cloned().collect();
        Ok(vec![Val::bytes(&v)])
    });
    reg(st, "byte", |it, a| {
        let s = check_str(it, &a, 0)?;
        let l = s.len();
        let pi = posrelat_i(opt_int(it, &a, 1, 1)?, l);
        let pose = getendpos(opt_int(it, &a, 2, pi as i64)?, l);
        if pi > pose {
            return Ok(vec![]);
        }
        if pose - pi >= i32::MAX as usize {
            return Err(it.error_native("string slice too long"));
        }
        Ok(s[pi - 1..pose].iter().map(|&c| Val::Int(c as i64)).collect())
    });
    reg(st, "char", |it, a| {
        let mut out = Vec::new();
        for i in 0..a.len() {
            let c = check_int(it, &a, i)?;
            if (c as u64) > 255 {
                return Err(it.arg_error(i + 1, "value out of range"));
            }
            out.push(c as u8);
        }
        Ok(vec![Val::bytes(&out)])
    });
    reg(st, "find", |it, a| str_find_aux(it, a, true));
    reg(st, "match", |it, a| str_find_aux(it, a, false));
    reg(st, "gmatch", |it, a| {
        let s = check_str(it, &a, 0)?;
        let p = check_str(it, &a, 1)?;
        let init = posrelat_i(opt_int(it, &a, 2, 1)?, s.len()) - 1;
        let state = Rc::new(std::cell::RefCell::new((if init > s.len() { s.len() + 1 } else { init }, usize::MAX)));
        let f = mk_native("gmatch_aux", move |it, _a| {
            let (mut src, lastmatch) = *state.borrow();
            let mut ms = MatchState::new(&s, &p);
            while src <= s.len() {
                ms.reprep();
                match ms.do_match(src, 0) {
                    Err(e) => return Err(it.error_native(&e)),
                    Ok(Some(e)) if e != lastmatch => {
                        *state.borrow_mut() = (e, e);
                        return match ms.push_captures(Some(src), e, true) {
                            Ok(c) => Ok(c),
                            Err(m) => Err(it.error_native(&m)),
                        };
                    }
                    _ => {}
                }
                src += 1;
            }
            state.borrow_mut().0 = src;
            Ok(vec![Val::Nil])
        });
        Ok(vec![f])
    });
    reg(st, "gsub", |it, a| {
        let src = check_str(it, &a, 0)?;
        let p = check_str(it, &a, 1)?;
        let repl = arg(&a, 2);
        let max_s = opt_int(it, &a, 3, src.len() as i64 + 1)?;
        if !matches!(repl, Val::Int(_) | Val::Num(_) | Val::Str(_) | Val::Func(_) | Val::Table(_)) {
            return Err(it.type_error(3, "string/function/table", if a.len() > 2 { Some(&repl) } else { None }));
        }
        let anchor = p.first() == Some(&b'^');
        let pat: &[u8] = if anchor { &p[1..] } else { &p[..] };
        let mut ms = MatchState::new(&src, pat);
        let mut b: Vec<u8> = Vec::new();
        let mut s = 0usize;
        let mut lastmatch = usize::MAX;
        let mut n: i64 = 0;
        let mut changed = false;
        while n < max_s {
            ms.reprep();
            let r = match ms.do_match(s, 0) {
                Ok(r) => r,
                Err(e) => return Err(it.error_native(&e)),
            };
            match r {
                Some(e) if e != lastmatch => {
                    n += 1;
                    changed = add_value(it, &ms, &mut b, s, e, &repl)? | changed;
                    s = e;
                    lastmatch = e;
                }
                _ => {
                    if s < src.len() {
                        b.push(src[s]);
                        s += 1;
                    } else {
                        break;
                    }
                }
            }
            if anchor {
                break;
            }
        }
        let res = if !changed {
            Val::Str(src.clone())
        } else {
            b.extend_from_slice(&src[s..]);
            Val::bytes(&b)
        };
        Ok(vec![res, Val::Int(n)])
    });
    reg(st, "format", str_format);
    reg(st, "dump", |it, _a| Err(it.error_native("unable to dump given function")));
    for name in ["pack", "unpack", "packsize"] {
        reg(st, name, |it, _a| Err(it.error_native("string packing is not supported")));
    }

    // string metatable
    let mt = Table::new_ref();
    mt.borrow_mut().set(Val::str("__index"), Val::Table(st.clone()));
    for ev in ["add", "sub", "mul", "mod", "pow", "div", "idiv", "unm"] {
        let name = format!("__{}", ev);
        let evs = ev.to_string();
        reg(&mt, &name, move |it, a| {
            let x = arg(&a, 0);
            let y = arg(&a, 1);
            let op = match evs.as_str() {
                "add" => super::ast::BinOp::Add,
                "sub" => super::ast::BinOp::Sub,
                "mul" => super::ast::BinOp::Mul,
                "mod" => super::ast::BinOp::Mod,
                "pow" => super::ast::BinOp::Pow,
                "div" => super::ast::BinOp::Div,
                "idiv" => super::ast::BinOp::IDiv,
                _ => super::ast::BinOp::Sub,
            };
            let nx = super::interp::tonumber(&x);
            let ny = super::interp::tonumber(&y);
            if let (Some(nx), Some(ny)) = (nx, ny) {
                if evs == "unm" {
                    return Ok(vec![match nx {
                        Val::Int(i) => Val::Int(i.wrapping_neg()),
                        Val::Num(f) => Val::Num(-f),
                        v => v,
                    }]);
                }
                if let (Val::Int(_), Val::Int(0)) = (&nx, &ny) {
                    if evs == "idiv" {
                        return Err(it.error_native("attempt to divide by zero"));
                    }
                    if evs == "mod" {
                        return Err(it.error_native("attempt to perform 'n%%0'"));
                    }
                }
                return Ok(vec![super::interp::arith_raw(op, &nx, &ny).unwrap_or(Val::Nil)]);
            }
            let ta = it.typename_of(&x);
            let tb = it.typename_of(&y);
            let m = format!("attempt to {} a '{}' with a '{}'", evs, ta, tb);
            Err(it.error_native(&m))
        });
    }
    it.string_mt = Some(mt);
}
EOF"}

