// A small Handlebars template engine compatible with the subset used by fblog.
use crate::json::{self, Number, Value};
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct TplError {
    pub reason: String,
    pub line: usize,
    pub col: usize,
    pub pos: usize,
}

#[derive(Debug, Clone)]
pub struct RenderError {
    pub reason: String,
    pub line: usize,
    pub col: usize,
}

#[derive(Debug, Clone)]
pub enum PathRoot {
    Ctx,
    Root,
}

#[derive(Debug, Clone)]
pub struct Path {
    pub root: PathRoot,
    pub up: usize,
    pub local: bool,
    pub segs: Vec<String>,
    pub simple: Option<String>,
}

#[derive(Debug, Clone)]
pub enum Param {
    Lit(Value),
    Path(Path),
    Sub(Box<Call>),
}

#[derive(Debug, Clone)]
pub struct Call {
    pub name: Param,
    pub params: Vec<Param>,
    pub hash: Vec<(String, Param)>,
    pub block_params: Vec<String>,
}

#[derive(Debug, Clone)]
pub enum Elem {
    Raw(String),
    Expr { call: Call, line: usize, col: usize },
    Block { call: Call, tmpl: Vec<Elem>, inverse: Option<Vec<Elem>>, line: usize, col: usize },
    Partial { name: String, line: usize, col: usize },
}

#[derive(Debug, Clone)]
pub struct Template {
    pub name: String,
    pub elems: Vec<Elem>,
}

// ---------------- tokenizer ----------------

#[derive(Debug, Clone)]
enum TagKind {
    Expr(Call),
    BlockStart(Call),
    BlockEnd(String),
    Else(Option<Call>),
    Comment,
    Partial(String),
    RawBlock(String, String),
}

#[derive(Debug, Clone)]
enum Tok {
    Raw(String),
    Tag { kind: TagKind, ltrim: bool, rtrim: bool, start: usize, end: usize, line: usize, col: usize },
}

fn line_col(src: &str, pos: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= pos {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

fn is_symbol_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '$' || (c as u32) >= 0x80
}

struct TagParser<'a> {
    s: &'a str,
    i: usize,
    base: usize,
}

type TR<T> = Result<T, (String, usize)>;

impl<'a> TagParser<'a> {
    fn peek(&self) -> Option<char> {
        self.s[self.i..].chars().next()
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.i += c.len_utf8();
            } else {
                break;
            }
        }
    }
    fn at_end(&self) -> bool {
        self.i >= self.s.len()
    }
    fn err<T>(&self, msg: &str) -> TR<T> {
        Err((msg.to_string(), self.base + self.i))
    }
    fn identifier(&mut self) -> Option<String> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if is_symbol_char(c) {
                self.i += c.len_utf8();
            } else {
                break;
            }
        }
        if self.i > st {
            Some(self.s[st..self.i].to_string())
        } else {
            None
        }
    }
    fn string_lit(&mut self) -> TR<Value> {
        let q = self.peek().unwrap();
        self.i += 1;
        let st = self.i;
        let mut raw = String::new();
        loop {
            match self.peek() {
                None => return self.err("expected string"),
                Some(c) if c == q => break,
                Some('\\') => {
                    self.i += 1;
                    match self.peek() {
                        Some(c2) => {
                            if c2 == '\'' && q == '\'' {
                                raw.push('\'');
                            } else {
                                raw.push('\\');
                                raw.push(c2);
                            }
                            self.i += c2.len_utf8();
                        }
                        None => return self.err("expected string"),
                    }
                }
                Some(c) => {
                    if c == '"' {
                        raw.push_str("\\\"");
                    } else {
                        raw.push(c);
                    }
                    self.i += c.len_utf8();
                }
            }
        }
        let _ = st;
        self.i += 1;
        let js = format!("\"{}\"", raw);
        match json::parse(&js) {
            Ok(v) => Ok(v),
            Err(_) => Ok(Value::String(raw)),
        }
    }
    fn number_lit(&mut self) -> Option<Value> {
        // -?\d+\.?\d*(E-?\d+)? !symbol_char
        let st = self.i;
        let b = self.s.as_bytes();
        let mut j = self.i;
        if j < b.len() && b[j] == b'-' {
            j += 1;
        }
        let ds = j;
        while j < b.len() && b[j].is_ascii_digit() {
            j += 1;
        }
        if j == ds {
            return None;
        }
        if j < b.len() && b[j] == b'.' {
            j += 1;
            while j < b.len() && b[j].is_ascii_digit() {
                j += 1;
            }
        }
        if j < b.len() && b[j] == b'E' {
            let mut k = j + 1;
            if k < b.len() && b[k] == b'-' {
                k += 1;
            }
            let ks = k;
            while k < b.len() && b[k].is_ascii_digit() {
                k += 1;
            }
            if k > ks {
                j = k;
            }
        }
        if let Some(c) = self.s[j..].chars().next() {
            if is_symbol_char(c) {
                return None;
            }
        }
        let txt = &self.s[st..j];
        let v = match json::parse(txt) {
            Ok(v) => v,
            Err(_) => match txt.trim_end_matches('.').parse::<f64>() {
                Ok(f) => Value::Number(Number::F(f)),
                Err(_) => return None,
            },
        };
        self.i = j;
        Some(v)
    }
    fn path(&mut self) -> TR<Path> {
        let mut p = Path { root: PathRoot::Ctx, up: 0, local: false, segs: Vec::new(), simple: None };
        let st = self.i;
        if self.s[self.i..].starts_with("@root") {
            let after = &self.s[self.i + 5..];
            let nc = after.chars().next();
            if nc.map(|c| !is_symbol_char(c)).unwrap_or(true) {
                p.root = PathRoot::Root;
                self.i += 5;
                if self.peek() == Some('.') || self.peek() == Some('/') {
                    self.i += 1;
                } else {
                    return Ok(p);
                }
            }
        }
        loop {
            if self.s[self.i..].starts_with("../") || self.s[self.i..].starts_with("..\\") {
                p.up += 1;
                self.i += 3;
            } else {
                break;
            }
        }
        if self.s[self.i..].starts_with("./") {
            self.i += 2;
        }
        if self.peek() == Some('@') {
            p.local = true;
            self.i += 1;
            loop {
                if self.s[self.i..].starts_with("../") {
                    p.up += 1;
                    self.i += 3;
                } else {
                    break;
                }
            }
        }
        // first item
        let mut first = true;
        loop {
            let seg = if self.peek() == Some('[') {
                self.i += 1;
                let s0 = self.i;
                while let Some(c) = self.peek() {
                    if c == ']' {
                        break;
                    }
                    self.i += c.len_utf8();
                }
                if self.at_end() {
                    return self.err("expected path_id");
                }
                let seg = self.s[s0..self.i].to_string();
                self.i += 1;
                seg
            } else {
                match self.identifier() {
                    Some(id) => id,
                    None => {
                        if first && self.i == st {
                            return self.err("expected identifier, subexpression, or path_inline");
                        }
                        return self.err("expected path_id");
                    }
                }
            };
            p.segs.push(seg);
            first = false;
            match self.peek() {
                Some('.') | Some('/') => {
                    // must be followed by a path item
                    let nxt = self.s[self.i + 1..].chars().next();
                    match nxt {
                        Some(c) if is_symbol_char(c) || c == '[' => {
                            self.i += 1;
                            continue;
                        }
                        _ => {
                            self.i += 1;
                            return self.err("expected path_id");
                        }
                    }
                }
                _ => break,
            }
        }
        if !p.local && p.up == 0 && matches!(p.root, PathRoot::Ctx) && p.segs.len() == 1 && !self.s[st..self.i].starts_with('[') {
            p.simple = Some(p.segs[0].clone());
        }
        Ok(p)
    }
    fn param(&mut self) -> TR<Param> {
        match self.peek() {
            Some('(') => {
                self.i += 1;
                self.ws();
                let c = self.call_body(true)?;
                self.ws();
                if self.peek() != Some(')') {
                    return self.err("expected identifier or helper_parameter");
                }
                self.i += 1;
                Ok(Param::Sub(Box::new(c)))
            }
            Some('"') | Some('\'') => Ok(Param::Lit(self.string_lit()?)),
            Some(c) if c == '-' || c.is_ascii_digit() => {
                if let Some(v) = self.number_lit() {
                    return Ok(Param::Lit(v));
                }
                Ok(Param::Path(self.path()?))
            }
            _ => {
                // keywords true/false/null
                for (kw, v) in [("true", Value::Bool(true)), ("false", Value::Bool(false)), ("null", Value::Null)] {
                    if self.s[self.i..].starts_with(kw) {
                        let after = self.s[self.i + kw.len()..].chars().next();
                        if after.map(|c| !is_symbol_char(c) && c != '.' && c != '/' && c != '[').unwrap_or(true) {
                            self.i += kw.len();
                            return Ok(Param::Lit(v));
                        }
                    }
                }
                Ok(Param::Path(self.path()?))
            }
        }
    }
    /// parses: name (params|hash)* [as |a b|]
    fn call_body(&mut self, allow_block_params: bool) -> TR<Call> {
        let name = match self.peek() {
            Some('(') => self.param()?,
            _ => {
                if self.at_end() || self.peek() == Some('}') || self.peek() == Some('~') || self.peek() == Some(')') {
                    return self.err("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline");
                }
                match self.peek() {
                    Some('"') | Some('\'') => return self.err("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"),
                    _ => {}
                }
                Param::Path(self.path()?)
            }
        };
        let mut call = Call { name, params: Vec::new(), hash: Vec::new(), block_params: Vec::new() };
        loop {
            let before = self.i;
            self.ws();
            if self.at_end() {
                break;
            }
            let c = self.peek().unwrap();
            if c == '}' || c == '~' || c == ')' {
                break;
            }
            if before == self.i && c != '(' {
                // params must be separated by whitespace
                return self.err("expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace");
            }
            // block params
            if allow_block_params && self.s[self.i..].starts_with("as") {
                let rest = &self.s[self.i + 2..];
                let r2 = rest.trim_start_matches([' ', '\t', '\n', '\r']);
                if r2.starts_with('|') {
                    self.i = self.s.len() - r2.len() + 1;
                    loop {
                        self.ws();
                        match self.identifier() {
                            Some(id) => call.block_params.push(id),
                            None => break,
                        }
                    }
                    self.ws();
                    if self.peek() != Some('|') {
                        return self.err("expected identifier");
                    }
                    self.i += 1;
                    continue;
                }
            }
            // hash?
            let save = self.i;
            if let Some(id) = self.identifier() {
                if self.peek() == Some('=') {
                    self.i += 1;
                    let v = self.param()?;
                    call.hash.push((id, v));
                    continue;
                }
            }
            self.i = save;
            let p = self.param()?;
            call.params.push(p);
        }
        Ok(call)
    }
}

fn find_close(src: &str, from: usize, close: &str) -> Option<usize> {
    src[from..].find(close).map(|p| p + from)
}

fn tokenize(src: &str) -> Result<Vec<Tok>, TplError> {
    let mut toks = Vec::new();
    let mut i = 0;
    let mut raw = String::new();
    let b = src.as_bytes();
    let mk_err = |reason: String, pos: usize| -> TplError {
        let (line, col) = line_col(src, pos);
        TplError { reason, line, col, pos }
    };
    while i < b.len() {
        // escapes
        if b[i] == b'\\' && src[i + 1..].starts_with("{{") {
            raw.push_str("{{");
            i += 3;
            continue;
        }
        if !src[i..].starts_with("{{") {
            let c = src[i..].chars().next().unwrap();
            raw.push(c);
            i += c.len_utf8();
            continue;
        }
        if !raw.is_empty() {
            toks.push(Tok::Raw(std::mem::take(&mut raw)));
        }
        let start = i;
        let (line, col) = line_col(src, start);
        // raw block {{{{name}}}} ... {{{{/name}}}}
        if src[i..].starts_with("{{{{") {
            let close = match find_close(src, i + 4, "}}}}") {
                Some(c) => c,
                None => return Err(mk_err("expected raw_block".into(), src.len())),
            };
            let name = src[i + 4..close].trim().to_string();
            let body_start = close + 4;
            let endtag = format!("{{{{{{{{/{}}}}}}}", name);
            let endpos = match find_close(src, body_start, &endtag) {
                Some(e) => e,
                None => return Err(mk_err("expected raw_block_end".into(), src.len())),
            };
            let body = src[body_start..endpos].to_string();
            let end = endpos + endtag.len();
            toks.push(Tok::Tag { kind: TagKind::RawBlock(name, body), ltrim: false, rtrim: false, start, end, line, col });
            i = end;
            continue;
        }
        let mut j = i + 2;
        let triple = src[j..].starts_with('{');
        if triple {
            j += 1;
        }
        let mut ltrim = false;
        if src[j..].starts_with('~') {
            ltrim = true;
            j += 1;
        }
        // comments
        if !triple && src[j..].starts_with("!--") {
            let close = match find_close(src, j + 3, "--}}") {
                Some(c) => c,
                None => return Err(mk_err("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline".into(), start + 2)),
            };
            let rtrim = close > 0 && src[..close].ends_with('~');
            let end = close + 4;
            toks.push(Tok::Tag { kind: TagKind::Comment, ltrim, rtrim, start, end, line, col });
            i = end;
            continue;
        }
        if !triple && src[j..].starts_with('!') {
            let close = match find_close(src, j + 1, "}}") {
                Some(c) => c,
                None => return Err(mk_err("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline".into(), start + 2)),
            };
            let rtrim = src[..close].ends_with('~');
            let end = close + 2;
            toks.push(Tok::Tag { kind: TagKind::Comment, ltrim, rtrim, start, end, line, col });
            i = end;
            continue;
        }
        let close_str = if triple { "}}}" } else { "}}" };
        let mut kind_char = None;
        if !triple {
            if let Some(c) = src[j..].chars().next() {
                if c == '#' || c == '/' || c == '^' || c == '>' || c == '&' || c == '*' {
                    kind_char = Some(c);
                    j += 1;
                }
            }
        }
        // parse content
        let content_start = j;
        let mut tp = TagParser { s: src, i: content_start, base: 0 };
        let finish = |tp: &mut TagParser| -> Result<(bool, usize), TplError> {
            tp.ws();
            let mut rt = false;
            if tp.s[tp.i..].starts_with('~') {
                rt = true;
                tp.i += 1;
            }
            if tp.s[tp.i..].starts_with(close_str) {
                Ok((rt, tp.i + close_str.len()))
            } else {
                let (line, col) = line_col(src, tp.i);
                Err(TplError { reason: "expected identifier, helper_parameter, or trailing_tilde_to_omit_whitespace".into(), line, col, pos: tp.i })
            }
        };
        let conv = |e: (String, usize)| -> TplError {
            let (line, col) = line_col(src, e.1);
            TplError { reason: e.0, line, col, pos: e.1 }
        };
        let kind;
        match kind_char {
            Some('#') => {
                if tp.s[tp.i..].starts_with('>') || tp.s[tp.i..].starts_with('*') {
                    return Err(mk_err("unsupported block".into(), tp.i));
                }
                tp.ws();
                let call = tp.call_body(true).map_err(conv)?;
                kind = TagKind::BlockStart(call);
            }
            Some('/') => {
                tp.ws();
                let id = match tp.identifier() {
                    Some(id) => id,
                    None => return Err(mk_err("expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline".into(), start + 2)),
                };
                kind = TagKind::BlockEnd(id);
            }
            Some('^') => {
                tp.ws();
                if tp.s[tp.i..].starts_with('~') || tp.s[tp.i..].starts_with("}}") {
                    kind = TagKind::Else(None);
                } else {
                    return Err(mk_err("expected keywords".into(), tp.i));
                }
            }
            Some('>') => {
                tp.ws();
                let st = tp.i;
                while let Some(c) = tp.peek() {
                    if is_symbol_char(c) || c == '/' || c == '.' {
                        tp.i += c.len_utf8();
                    } else {
                        break;
                    }
                }
                if tp.i == st {
                    return Err(mk_err("expected partial_identifier, subexpression, or path_inline".into(), tp.i));
                }
                let name = src[st..tp.i].to_string();
                // skip remaining params
                while !tp.at_end() && !tp.s[tp.i..].starts_with("}}") && !tp.s[tp.i..].starts_with("~}}") {
                    tp.i += tp.peek().unwrap().len_utf8();
                }
                kind = TagKind::Partial(name);
            }
            Some(_) => {
                return Err(mk_err("unsupported tag".into(), tp.i));
            }
            None => {
                tp.ws();
                // else ?
                let rest = &tp.s[tp.i..];
                if !triple && rest.starts_with("else") && rest[4..].chars().next().map(|c| !is_symbol_char(c)).unwrap_or(true) {
                    tp.i += 4;
                    tp.ws();
                    if tp.s[tp.i..].starts_with('~') || tp.s[tp.i..].starts_with("}}") {
                        kind = TagKind::Else(None);
                    } else {
                        let call = tp.call_body(true).map_err(conv)?;
                        kind = TagKind::Else(Some(call));
                    }
                } else {
                    let call = tp.call_body(false).map_err(conv)?;
                    kind = TagKind::Expr(call);
                }
            }
        }
        let (rtrim, end) = finish(&mut tp)?;
        toks.push(Tok::Tag { kind, ltrim, rtrim, start, end, line, col });
        i = end;
    }
    if !raw.is_empty() {
        toks.push(Tok::Raw(raw));
    }
    Ok(toks)
}

fn ws_matcher(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn starts_with_empty_line(s: &str) -> bool {
    let t = s.trim_start_matches(ws_matcher);
    t.starts_with('\n') || t.starts_with('\r')
}

fn ends_with_empty_line(s: &str) -> bool {
    let t = s.trim_end_matches(ws_matcher);
    t.ends_with('\n') || t.ends_with('\r') || t.is_empty()
}

fn strip_first_newline(s: &str) -> String {
    let t = s.trim_start_matches(ws_matcher);
    if let Some(r) = t.strip_prefix("\r\n") {
        r.to_string()
    } else if let Some(r) = t.strip_prefix('\n') {
        r.to_string()
    } else if let Some(r) = t.strip_prefix('\r') {
        r.to_string()
    } else {
        s.to_string()
    }
}

pub fn compile(src: &str, name: &str) -> Result<Template, TplError> {
    let mut toks = tokenize(src)?;
    // standalone handling
    let n = toks.len();
    let mut idx = 0;
    while idx < n {
        let info = match &toks[idx] {
            Tok::Tag { kind, start, end, .. } => {
                let standalone_kind = matches!(kind, TagKind::BlockStart(_) | TagKind::BlockEnd(_) | TagKind::Else(_) | TagKind::Comment | TagKind::Partial(_) | TagKind::RawBlock(..));
                if standalone_kind {
                    Some((*start, *end))
                } else {
                    None
                }
            }
            _ => None,
        };
        if let Some((start, end)) = info {
            let trailing = starts_with_empty_line(&src[end..]);
            if trailing {
                let leading = ends_with_empty_line(&src[..start]);
                if start == 0 || leading {
                    if idx > 0 {
                        if let Tok::Raw(t) = &mut toks[idx - 1] {
                            *t = t.trim_end_matches(ws_matcher).to_string();
                        }
                    }
                    if idx + 1 < n {
                        if let Tok::Raw(t) = &mut toks[idx + 1] {
                            *t = strip_first_newline(t);
                        }
                    }
                }
            }
        }
        idx += 1;
    }
    // whitespace control
    for idx in 0..n {
        let (lt, rt) = match &toks[idx] {
            Tok::Tag { ltrim, rtrim, .. } => (*ltrim, *rtrim),
            _ => (false, false),
        };
        if lt && idx > 0 {
            if let Tok::Raw(t) = &mut toks[idx - 1] {
                *t = t.trim_end().to_string();
            }
        }
        if rt && idx + 1 < n {
            if let Tok::Raw(t) = &mut toks[idx + 1] {
                *t = t.trim_start().to_string();
            }
        }
    }
    // build tree
    struct Open {
        call: Call,
        name: String,
        tmpl: Vec<Elem>,
        inverse: Option<Vec<Elem>>,
        in_inverse: bool,
        line: usize,
        col: usize,
        chained: usize,
    }
    let mut stack: Vec<Open> = Vec::new();
    let mut root: Vec<Elem> = Vec::new();
    fn push_elem(stack: &mut Vec<Open>, root: &mut Vec<Elem>, e: Elem) {
        match stack.last_mut() {
            Some(o) => {
                if o.in_inverse {
                    o.inverse.as_mut().unwrap().push(e);
                } else {
                    o.tmpl.push(e);
                }
            }
            None => root.push(e),
        }
    }
    fn call_name(c: &Call) -> String {
        match &c.name {
            Param::Path(p) => p.segs.join("."),
            _ => String::new(),
        }
    }
    for t in toks {
        match t {
            Tok::Raw(s) => {
                if !s.is_empty() {
                    push_elem(&mut stack, &mut root, Elem::Raw(s));
                }
            }
            Tok::Tag { kind, line, col, start, .. } => match kind {
                TagKind::Comment => {}
                TagKind::RawBlock(_, body) => push_elem(&mut stack, &mut root, Elem::Raw(body)),
                TagKind::Expr(call) => push_elem(&mut stack, &mut root, Elem::Expr { call, line, col }),
                TagKind::Partial(name) => push_elem(&mut stack, &mut root, Elem::Partial { name, line, col }),
                TagKind::BlockStart(call) => {
                    let name = call_name(&call);
                    stack.push(Open { call, name, tmpl: Vec::new(), inverse: None, in_inverse: false, line, col, chained: 0 });
                }
                TagKind::Else(chain) => {
                    let top = match stack.last_mut() {
                        Some(t) => t,
                        None => {
                            let (l, c) = line_col(src, start + 2);
                            return Err(TplError { reason: "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace".into(), line: l, col: c, pos: start + 2 });
                        }
                    };
                    if top.in_inverse {
                        let (l, c) = line_col(src, start + 2);
                        return Err(TplError { reason: "unexpected invert_tag_item; expected leading_tilde_to_omit_whitespace".into(), line: l, col: c, pos: start + 2 });
                    }
                    top.in_inverse = true;
                    top.inverse = Some(Vec::new());
                    if let Some(c) = chain {
                        // else if ...: open a nested block inside inverse
                        let name = top.name.clone();
                        let chained = top.chained;
                        let _ = name;
                        stack.push(Open { name: call_name(&c), call: c, tmpl: Vec::new(), inverse: None, in_inverse: false, line, col, chained: chained + 1 });
                        // mark that this nested block shares the outer close tag
                        let l = stack.len();
                        stack[l - 1].name = stack[l - 2].name.clone();
                    }
                }
                TagKind::BlockEnd(name) => {
                    loop {
                        let top = match stack.pop() {
                            Some(t) => t,
                            None => {
                                let (l, c) = line_col(src, start + 2);
                                return Err(TplError { reason: "expected identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline".into(), line: l, col: c, pos: start + 2 });
                            }
                        };
                        let chained = top.chained;
                        if top.name != name && chained == 0 {
                            let (l, c) = line_col(src, start);
                            return Err(TplError { reason: format!("MismatchingClosedHelper(\"{}\", \"{}\")", top.name, name), line: l, col: c, pos: start });
                        }
                        let e = Elem::Block { call: top.call, tmpl: top.tmpl, inverse: top.inverse, line: top.line, col: top.col };
                        push_elem(&mut stack, &mut root, e);
                        if chained == 0 {
                            break;
                        }
                    }
                }
            },
        }
    }
    if !stack.is_empty() {
        let (l, c) = line_col(src, src.len());
        return Err(TplError {
            reason: "expected escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact".into(),
            line: l,
            col: c,
            pos: src.len(),
        });
    }
    Ok(Template { name: name.to_string(), elems: root })
}

pub fn format_template_error(e: &TplError, name: &str, src: &str) -> String {
    let reason = if e.reason.starts_with("MismatchingClosedHelper") { e.reason.clone() } else { format!("InvalidSyntax({:?})", e.reason) };
    // segment similar to pest's output
    let lines: Vec<&str> = src.split('\n').collect();
    let mut seg = String::new();
    for (i, l) in lines.iter().enumerate() {
        seg.push_str(&format!("{:>4} | {}\n", i, l));
        if i + 1 == e.line {
            let mut marker = String::from("     |");
            let w = l.chars().count();
            for k in 0..w.max(e.col) {
                if k + 1 == e.col && e.col <= w {
                    marker.push('^');
                } else if k < w {
                    marker.push('-');
                }
            }
            seg.push_str(&marker);
            seg.push('\n');
        }
    }
    format!(
        "Template invalid: TemplateError {{ reason: {}, template_name: Some({:?}), line_no: Some({}), column_no: Some({}), segment: Some({:?}) }}",
        reason, name, e.line, e.col, seg
    )
}

// ---------------- rendering ----------------

pub fn render_json(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => String::new(),
        Value::Array(a) => {
            let mut buf = String::from("[");
            for (i, x) in a.iter().enumerate() {
                buf.push_str(&render_json(x));
                if i + 1 < a.len() {
                    buf.push_str(", ");
                }
            }
            buf.push(']');
            buf
        }
        Value::Object(_) => "[object]".to_string(),
    }
}

pub fn is_truthy(v: &Value, include_zero: bool) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Number(n) => {
            let f = n.as_f64();
            if include_zero {
                !f.is_nan()
            } else {
                f.is_normal()
            }
        }
        Value::Null => false,
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

struct BlockCtx {
    base: Value,
    locals: BTreeMap<String, Value>,
    params: Vec<(String, Value)>,
}

struct Ctx {
    root: Value,
    blocks: Vec<BlockCtx>,
}

fn get_seg(v: &Value, seg: &str) -> Option<Value> {
    match v {
        Value::Object(m) => m.get(seg).cloned(),
        Value::Array(a) => seg.parse::<usize>().ok().and_then(|i| a.get(i).cloned()),
        _ => None,
    }
}

fn resolve_path(ctx: &Ctx, p: &Path) -> Value {
    let nb = ctx.blocks.len();
    if p.local {
        if p.up >= nb {
            return Value::Null;
        }
        let b = &ctx.blocks[nb - 1 - p.up];
        let mut cur = match b.locals.get(&p.segs[0]) {
            Some(v) => v.clone(),
            None => return Value::Null,
        };
        for s in &p.segs[1..] {
            cur = match get_seg(&cur, s) {
                Some(v) => v,
                None => return Value::Null,
            };
        }
        return cur;
    }
    let mut segs: &[String] = &p.segs;
    let mut cur: Value;
    match p.root {
        PathRoot::Root => {
            cur = ctx.root.clone();
        }
        PathRoot::Ctx => {
            // block params
            if p.up == 0 && !segs.is_empty() {
                for b in ctx.blocks.iter().rev() {
                    if let Some((_, v)) = b.params.iter().find(|(n, _)| n == &segs[0]) {
                        let mut c = v.clone();
                        for s in &segs[1..] {
                            c = match get_seg(&c, s) {
                                Some(v) => v,
                                None => return Value::Null,
                            };
                        }
                        return c;
                    }
                }
            }
            if p.up >= nb {
                cur = ctx.root.clone();
                if p.up > nb {
                    return Value::Null;
                }
            } else {
                cur = ctx.blocks[nb - 1 - p.up].base.clone();
            }
        }
    }
    while !segs.is_empty() && (segs[0] == "this" || segs[0] == ".") {
        segs = &segs[1..];
    }
    for s in segs {
        if s == "this" {
            continue;
        }
        cur = match get_seg(&cur, s) {
            Some(v) => v,
            None => return Value::Null,
        };
    }
    cur
}

const BUILTIN_HELPERS: &[&str] = &["if", "unless", "each", "with", "lookup", "raw", "log", "eq", "ne", "gt", "gte", "lt", "lte", "and", "or", "not", "len"];
const CUSTOM_HELPERS: &[&str] = &["bold", "cyan", "red", "green", "yellow", "blue", "purple", "color_rgb", "uppercase", "level_style", "fixed_size", "min_size"];

fn is_helper(name: &str) -> bool {
    BUILTIN_HELPERS.contains(&name) || CUSTOM_HELPERS.contains(&name)
}

fn compare_json(x: &Value, y: &Value) -> Option<std::cmp::Ordering> {
    fn cmp_num_str(a: &Number, b: &str) -> Option<std::cmp::Ordering> {
        let af = a.as_f64();
        let bf = b.parse::<f64>().ok()?;
        af.partial_cmp(&bf)
    }
    match (x, y) {
        (Value::Number(a), Value::Number(b)) => a.as_f64().partial_cmp(&b.as_f64()),
        (Value::String(a), Value::String(b)) => Some(a.cmp(b)),
        (Value::Bool(a), Value::Bool(b)) => Some(a.cmp(b)),
        (Value::Number(a), Value::String(b)) => cmp_num_str(a, b),
        (Value::String(a), Value::Number(b)) => cmp_num_str(b, a).map(|o| o.reverse()),
        _ => None,
    }
}

pub struct PanicMsg(pub String);

enum HErr {
    Render(String),
    Panic(String),
}

pub enum RenderFail {
    Error(RenderError),
    Panic(String),
}

struct Renderer<'a> {
    tname: &'a str,
}

fn level_color(level: &str) -> &'static str {
    match level.trim().to_lowercase().as_str() {
        "trace" => "36",
        "debug" => "34",
        "info" => "32",
        "warn" | "warning" => "33",
        "error" | "err" => "31",
        _ => "35",
    }
}

impl<'a> Renderer<'a> {
    fn eval_param(&self, p: &Param, ctx: &mut Ctx, line: usize, col: usize) -> Result<Value, RenderFail> {
        match p {
            Param::Lit(v) => Ok(v.clone()),
            Param::Path(path) => {
                if let Some(n) = &path.simple {
                    let _ = n;
                }
                Ok(resolve_path(ctx, path))
            }
            Param::Sub(c) => {
                let v = self.call_value(c, ctx, line, col)?;
                Ok(v.unwrap_or(Value::Null))
            }
        }
    }

    fn rerr(&self, reason: String, line: usize, col: usize) -> RenderFail {
        RenderFail::Error(RenderError { reason, line, col })
    }

    /// Evaluate a helper (or path) producing a value. Returns None for "missing".
    fn call_value(&self, c: &Call, ctx: &mut Ctx, line: usize, col: usize) -> Result<Option<Value>, RenderFail> {
        let name = match &c.name {
            Param::Path(p) => p,
            Param::Sub(s) => {
                // name is a subexpression: evaluate it as value
                let v = self.call_value(s, ctx, line, col)?;
                return Ok(v);
            }
            Param::Lit(v) => return Ok(Some(v.clone())),
        };
        let has_args = !c.params.is_empty() || !c.hash.is_empty();
        let hname = name.simple.clone();
        match &hname {
            Some(h) if is_helper(h) => {}
            Some(h) if has_args => return Err(self.rerr(format!("Helper not found {}", h), line, col)),
            None if has_args => {
                let full = name.segs.join("/");
                return Err(self.rerr(format!("Helper not found {}", full), line, col));
            }
            _ => {
                let v = resolve_path(ctx, name);
                return Ok(if v.is_null() { None } else { Some(v) });
            }
        }
        let h = hname.unwrap();
        let mut params = Vec::new();
        for p in &c.params {
            params.push(self.eval_param(p, ctx, line, col)?);
        }
        let mut hash = Vec::new();
        for (k, p) in &c.hash {
            hash.push((k.clone(), self.eval_param(p, ctx, line, col)?));
        }
        self.apply_helper(&h, &params, &hash, line, col).map_err(|e| match e {
            HErr::Render(r) => self.rerr(r, line, col),
            HErr::Panic(p) => RenderFail::Panic(p),
        })
    }

    fn apply_helper(&self, h: &str, params: &[Value], _hash: &[(String, Value)], _line: usize, _col: usize) -> Result<Option<Value>, HErr> {
        let idx_err = |i: usize| HErr::Render(format!("Helper/Decorator {} param at index {} required but not found", h, i));
        let name_err = |n: &str| HErr::Render(format!("Helper/Decorator {} param with name {} required but not found", h, n));
        let type_err = |n: &str, t: &str| HErr::Render(format!("Helper/Decorator {} param with name {} type mismatch for {}", h, n, t));
        let get_str = |i: usize, n: &str| -> Result<String, HErr> {
            match params.get(i) {
                None => Err(name_err(n)),
                Some(Value::String(s)) => Ok(s.clone()),
                Some(_) => Err(type_err(n, "str")),
            }
        };
        let get_u64 = |i: usize, n: &str| -> Result<u64, HErr> {
            match params.get(i) {
                None => Err(name_err(n)),
                Some(Value::Number(num)) => match num {
                    Number::U(u) => Ok(*u),
                    Number::I(x) if *x >= 0 => Ok(*x as u64),
                    _ => Err(type_err(n, "u64")),
                },
                Some(_) => Err(type_err(n, "u64")),
            }
        };
        let s = |v: String| Ok(Some(Value::String(v)));
        match h {
            "eq" | "ne" | "gt" | "gte" | "lt" | "lte" => {
                let x = params.first().ok_or_else(|| idx_err(0))?;
                let y = params.get(1).ok_or_else(|| idx_err(1))?;
                let r = match h {
                    "eq" => x == y,
                    "ne" => x != y,
                    "gt" => compare_json(x, y) == Some(std::cmp::Ordering::Greater),
                    "gte" => compare_json(x, y).map(|o| o != std::cmp::Ordering::Less).unwrap_or(false),
                    "lt" => compare_json(x, y) == Some(std::cmp::Ordering::Less),
                    _ => compare_json(x, y).map(|o| o != std::cmp::Ordering::Greater).unwrap_or(false),
                };
                Ok(Some(Value::Bool(r)))
            }
            "and" => Ok(Some(Value::Bool(params.iter().all(|v| is_truthy(v, false))))),
            "or" => Ok(Some(Value::Bool(params.iter().any(|v| is_truthy(v, false))))),
            "not" => {
                let x = params.first().ok_or_else(|| idx_err(0))?;
                Ok(Some(Value::Bool(!is_truthy(x, false))))
            }
            "len" => {
                let x = params.first().ok_or_else(|| name_err("x"))?;
                let n = match x {
                    Value::Array(a) => a.len(),
                    Value::Object(o) => o.len(),
                    Value::String(s) => s.len(),
                    _ => 0,
                };
                Ok(Some(Value::Number(Number::U(n as u64))))
            }
            "lookup" => {
                let coll = params.first().ok_or_else(|| idx_err(0))?;
                let index = params.get(1).ok_or_else(|| idx_err(1))?;
                let v = match coll {
                    Value::Array(a) => match index {
                        Value::Number(n) => n.as_u64().and_then(|u| a.get(u as usize).cloned()),
                        _ => None,
                    },
                    Value::Object(m) => match index {
                        Value::String(k) => m.get(k).cloned(),
                        _ => None,
                    },
                    _ => None,
                };
                Ok(v)
            }
            "log" | "raw" => Ok(None),
            "if" | "unless" | "each" | "with" => {
                let hn = if h == "unless" { "if" } else { h };
                if params.is_empty() {
                    return Err(HErr::Render(format!("Helper/Decorator {} param at index 0 required but not found", hn)));
                }
                Ok(None)
            }
            "bold" => s(format!("\x1b[1m{}\x1b[0m", get_str(0, "t")?)),
            "cyan" => s(format!("\x1b[36m{}\x1b[0m", get_str(0, "t")?)),
            "red" => s(format!("\x1b[31m{}\x1b[0m", get_str(0, "t")?)),
            "green" => s(format!("\x1b[32m{}\x1b[0m", get_str(0, "t")?)),
            "yellow" => s(format!("\x1b[33m{}\x1b[0m", get_str(0, "t")?)),
            "blue" => s(format!("\x1b[34m{}\x1b[0m", get_str(0, "t")?)),
            "purple" => s(format!("\x1b[35m{}\x1b[0m", get_str(0, "t")?)),
            "uppercase" => s(get_str(0, "t")?.to_uppercase()),
            "level_style" => {
                let l = get_str(0, "level")?;
                s(format!("\x1b[1;{}m{}\x1b[0m", level_color(&l), l))
            }
            "color_rgb" => {
                let r = get_u64(0, "r")?;
                let g = get_u64(1, "g")?;
                let b = get_u64(2, "b")?;
                let t = get_str(3, "t")?;
                for c in [r, g, b] {
                    if c > 255 {
                        return Err(HErr::Panic("src/template.rs:38:46:\ncalled `Result::unwrap()` on an `Err` value: TryFromIntError(())".into()));
                    }
                }
                s(format!("\x1b[38;2;{};{};{}m{}\x1b[0m", r, g, b, t))
            }
            "fixed_size" => {
                let n = get_u64(0, "isize")? as usize;
                let mut t = get_str(1, "t")?;
                if t.len() > n {
                    if !t.is_char_boundary(n) {
                        return Err(HErr::Panic("src/template.rs:61:15:\nassertion failed: self.is_char_boundary(new_len)".into()));
                    }
                    t.truncate(n);
                    s(t)
                } else {
                    s(format!("{}{}", " ".repeat(n - t.len()), t))
                }
            }
            "min_size" => {
                let n = get_u64(0, "isize")? as usize;
                let t = get_str(1, "t")?;
                if t.len() < n {
                    s(format!("{}{}", " ".repeat(n - t.len()), t))
                } else {
                    s(t)
                }
            }
            _ => Ok(None),
        }
    }

    fn render(&self, elems: &[Elem], ctx: &mut Ctx, out: &mut String) -> Result<(), RenderFail> {
        for e in elems {
            match e {
                Elem::Raw(s) => out.push_str(s),
                Elem::Partial { name, line, col } => {
                    return Err(self.rerr(format!("Partial not found {}", name), *line, *col));
                }
                Elem::Expr { call, line, col } => {
                    let v = self.call_value(call, ctx, *line, *col)?;
                    if let Some(v) = v {
                        out.push_str(&render_json(&v));
                    }
                }
                Elem::Block { call, tmpl, inverse, line, col } => {
                    self.render_block(call, tmpl, inverse.as_deref(), ctx, out, *line, *col)?;
                }
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn render_block(&self, call: &Call, tmpl: &[Elem], inverse: Option<&[Elem]>, ctx: &mut Ctx, out: &mut String, line: usize, col: usize) -> Result<(), RenderFail> {
        let name = match &call.name {
            Param::Path(p) => p.simple.clone().unwrap_or_else(|| p.segs.join("/")),
            _ => String::new(),
        };
        if !is_helper(&name) {
            return Err(self.rerr(format!("Helper not found {}", name), line, col));
        }
        let mut params = Vec::new();
        for p in &call.params {
            params.push(self.eval_param(p, ctx, line, col)?);
        }
        let mut hash = Vec::new();
        for (k, p) in &call.hash {
            hash.push((k.clone(), self.eval_param(p, ctx, line, col)?));
        }
        match name.as_str() {
            "if" | "unless" => {
                let p = match params.first() {
                    Some(p) => p,
                    None => return Err(self.rerr("Helper/Decorator if param at index 0 required but not found".into(), line, col)),
                };
                let include_zero = hash.iter().find(|(k, _)| k == "includeZero").map(|(_, v)| matches!(v, Value::Bool(true))).unwrap_or(false);
                let mut value = is_truthy(p, include_zero);
                if name == "unless" {
                    value = !value;
                }
                if value {
                    self.render(tmpl, ctx, out)?;
                } else if let Some(inv) = inverse {
                    self.render(inv, ctx, out)?;
                }
                Ok(())
            }
            "each" => {
                let v = match params.first() {
                    Some(p) => p.clone(),
                    None => return Err(self.rerr("Helper/Decorator each param at index 0 required but not found".into(), line, col)),
                };
                match &v {
                    Value::Array(list) if !list.is_empty() || inverse.is_none() => {
                        let len = list.len();
                        for (i, item) in list.iter().enumerate() {
                            let mut locals = BTreeMap::new();
                            locals.insert("first".to_string(), Value::Bool(i == 0));
                            locals.insert("last".to_string(), Value::Bool(i + 1 == len));
                            locals.insert("index".to_string(), Value::Number(Number::U(i as u64)));
                            let mut bp = Vec::new();
                            if let Some(n) = call.block_params.first() {
                                bp.push((n.clone(), item.clone()));
                            }
                            if let Some(n) = call.block_params.get(1) {
                                bp.push((n.clone(), Value::Number(Number::U(i as u64))));
                            }
                            ctx.blocks.push(BlockCtx { base: item.clone(), locals, params: bp });
                            let r = self.render(tmpl, ctx, out);
                            ctx.blocks.pop();
                            r?;
                        }
                        Ok(())
                    }
                    Value::Object(obj) if !obj.is_empty() || inverse.is_none() => {
                        let len = obj.len();
                        for (i, (k, item)) in obj.iter().enumerate() {
                            let mut locals = BTreeMap::new();
                            locals.insert("first".to_string(), Value::Bool(i == 0));
                            locals.insert("last".to_string(), Value::Bool(i + 1 == len));
                            locals.insert("index".to_string(), Value::Number(Number::U(i as u64)));
                            locals.insert("key".to_string(), Value::String(k.clone()));
                            let mut bp = Vec::new();
                            if let Some(n) = call.block_params.first() {
                                bp.push((n.clone(), item.clone()));
                            }
                            if let Some(n) = call.block_params.get(1) {
                                bp.push((n.clone(), Value::String(k.clone())));
                            }
                            ctx.blocks.push(BlockCtx { base: item.clone(), locals, params: bp });
                            let r = self.render(tmpl, ctx, out);
                            ctx.blocks.pop();
                            r?;
                        }
                        Ok(())
                    }
                    _ => {
                        if let Some(inv) = inverse {
                            self.render(inv, ctx, out)?;
                        }
                        Ok(())
                    }
                }
            }
            "with" => {
                let v = match params.first() {
                    Some(p) => p.clone(),
                    None => return Err(self.rerr("Helper/Decorator with param at index 0 required but not found".into(), line, col)),
                };
                if is_truthy(&v, false) {
                    let mut bp = Vec::new();
                    if let Some(n) = call.block_params.first() {
                        bp.push((n.clone(), v.clone()));
                    }
                    ctx.blocks.push(BlockCtx { base: v, locals: BTreeMap::new(), params: bp });
                    let r = self.render(tmpl, ctx, out);
                    ctx.blocks.pop();
                    r?;
                } else if let Some(inv) = inverse {
                    self.render(inv, ctx, out)?;
                }
                Ok(())
            }
            "raw" => {
                self.render(tmpl, ctx, out)?;
                Ok(())
            }
            "log" => Ok(()),
            _ => {
                let v = self.apply_helper(&name, &params, &hash, line, col).map_err(|e| match e {
                    HErr::Render(r) => self.rerr(r, line, col),
                    HErr::Panic(p) => RenderFail::Panic(p),
                })?;
                if let Some(v) = v {
                    out.push_str(&render_json(&v));
                }
                Ok(())
            }
        }
    }
}

impl RenderError {
    pub fn to_string(&self, tname: &str) -> String {
        format!("Error rendering \"{}\" line {}, col {}: {}", tname, self.line, self.col, self.reason)
    }
}

pub fn render(t: &Template, data: &Value) -> Result<String, RenderFail> {
    let r = Renderer { tname: &t.name };
    let _ = r.tname;
    let mut ctx = Ctx { root: data.clone(), blocks: vec![BlockCtx { base: data.clone(), locals: BTreeMap::new(), params: Vec::new() }] };
    let mut out = String::new();
    r.render(&t.elems, &mut ctx, &mut out)?;
    Ok(out)
}
EOF"}

