// Command line parsing emulating clap's behaviour and messages.
use std::io::Write;

#[derive(Default, Debug)]
pub struct Args {
    pub additional_values: Vec<String>,
    pub config_file: Option<String>,
    pub message_keys: Vec<String>,
    pub print_lua: bool,
    pub time_keys: Vec<String>,
