enum Kind {
    Flag,
    Single,
    Multi,
    Help,
    Version,
}

struct ArgDef {
    id: &'static str,
    short: Option<char>,
    long: &'static str,
    value: &'static str,
    kind: Kind,
}

const DEFS: &[ArgDef] = &[
    ArgDef { id: "additional-value", short: Some('a'), long: "additional-value", value: "additional-value", kind: Kind::Multi },
    ArgDef { id: "config-file", short: None, long: "config-file", value: "config-file", kind: Kind::Single },
    ArgDef { id: "message-key", short: Some('m'), long: "message-key", value: "message-key", kind: Kind::Multi },
    ArgDef { id: "print-lua", short: None, long: "print-lua", value: "", kind: Kind::Flag },
    ArgDef { id: "time-key", short: Some('t'), long: "time-key", value: "time-key", kind: Kind::Multi },
    ArgDef { id: "level-key", short: Some('l'), long: "level-key", value: "level-key", kind: Kind::Multi },
    ArgDef { id: "map-level", short: None, long: "map-level", value: "from=to", kind: Kind::Multi },
    ArgDef { id: "dump-all", short: Some('d'), long: "dump-all", value: "", kind: Kind::Flag },
    ArgDef { id: "excluded-value", short: Some('x'), long: "excluded-value", value: "excluded-value", kind: Kind::Multi },
    ArgDef { id: "with-prefix", short: Some('p'), long: "with-prefix", value: "", kind: Kind::Flag },
    ArgDef { id: "filter", short: Some('f'), long: "filter", value: "filter", kind: Kind::Single },
    ArgDef { id: "no-implicit-filter-return-statement", short: None, long: "no-implicit-filter-return-statement", value: "", kind: Kind::Flag },
    ArgDef { id: "main-line-format", short: None, long: "main-line-format", value: "main-line-format", kind: Kind::Single },
    ArgDef { id: "additional-value-format", short: None, long: "additional-value-format", value: "additional-value-format", kind: Kind::Single },
    ArgDef { id: "substitute", short: Some('s'), long: "substitute", value: "", kind: Kind::Flag },
    ArgDef { id: "context-key", short: Some('c'), long: "context-key", value: "context-key", kind: Kind::Single },
    ArgDef { id: "placeholder-format", short: Some('F'), long: "placeholder-format", value: "placeholder-format", kind: Kind::Single },
    ArgDef { id: "help", short: Some('h'), long: "help", value: "", kind: Kind::Help },
    ArgDef { id: "version", short: Some('V'), long: "version", value: "", kind: Kind::Version },
];

fn bin_name() -> String {
    let a0 = std::env::args_os().next().map(|s| s.to_string_lossy().into_owned()).unwrap_or_else(|| "fblog".into());
    match std::path::Path::new(&a0).file_name() {
        Some(n) => n.to_string_lossy().into_owned(),
        None => a0,
    }
}

pub fn help_text() -> String {
    let b = bin_name();
    format!(
        "json log viewer

Usage: {b} [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Sets the input file to use, otherwise assumes stdin [default: -]

Options:
  -a, --additional-value <additional-value>
          adds additional values
      --config-file <config-file>
          configuration file to load
  -m, --message-key <message-key>
          Adds an additional key to detect the message in the log entry. The first matching key will be assigned to `fblog_message`.
      --print-lua
          Prints lua init expressions. Used for fblog debugging.
  -t, --time-key <time-key>
          Adds an additional key to detect the time in the log entry. The first matching key will be assigned to `fblog_timestamp`.
  -l, --level-key <level-key>
          Adds an additional key to detect the level in the log entry. The first matching key will be assigned to `fblog_level`.
      --map-level <from=to>
          Rewrite the log level from one value to another.
  -d, --dump-all
          dumps all values
  -x, --excluded-value <excluded-value>
          Excludes values (--dump-all is enabled implicitly)
  -p, --with-prefix
          consider all text before opening curly brace as prefix
  -f, --filter <filter>
          lua expression to filter log entries. `message ~= nil and string.find(message, \"text.*\") ~= nil`
      --no-implicit-filter-return-statement
          if you pass a filter expression 'return' is automatically prepended. Pass this switch to disable the implicit return.
      --main-line-format <main-line-format>
          Formats the main fblog output. All log values can be used. fblog provides sanitized variables starting with `fblog_`.
      --additional-value-format <additional-value-format>
          Formats the additional value fblog output.
  -s, --substitute
          Enable substitution of placeholders in the log messages with their corresponding values from the context.
  -c, --context-key <context-key>
          Use this key as the source of substitutions for the message. Value can either be an array ({{1}}) or an object ({{key}}).
  -F, --placeholder-format <placeholder-format>
          The format that should be used for substituting values in the message, where the key is the literal word `key`. Example: [[key]] or ${{key}}.
  -h, --help
          Print help
  -V, --version
          Print version
"
    )
}

fn display(d: &ArgDef) -> String {
    match d.kind {
        Kind::Single | Kind::Multi => format!("--{} <{}>", d.long, d.value),
        _ => format!("--{}", d.long),
    }
}

struct State {
    used: Vec<usize>,
    counts: Vec<usize>,
    input_set: bool,
}

fn usage_line(st: &State, extra: Option<usize>) -> String {
    let b = bin_name();
    let mut used: Vec<usize> = st.used.clone();
    if let Some(e) = extra {
        if !used.contains(&e) {
            used.push(e);
        }
    }
    if used.is_empty() && !st.input_set {
        return format!("Usage: {} [OPTIONS] [INPUT]", b);
    }
    let mut s = format!("Usage: {}", b);
    for u in &used {
        s.push(' ');
        s.push_str(&display(&DEFS[*u]));
    }
    if st.input_set {
        s.push_str(" <INPUT>");
    } else {
        s.push_str(" [INPUT]");
    }
    s
}

fn general_usage() -> String {
    format!("Usage: {} [OPTIONS] [INPUT]", bin_name())
}

fn fail(msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    let mut e = std::io::stderr();
    let _ = e.write_all(msg.as_bytes());
    let _ = e.flush();
    std::process::exit(2);
}

fn err_with_usage(msg: &str, tips: &[String], usage: &str) -> ! {
    let mut s = format!("error: {}\n", msg);
    if !tips.is_empty() {
        s.push('\n');
        for t in tips {
            s.push_str(&format!("  tip: {}\n", t));
        }
    }
    s.push('\n');
    s.push_str(usage);
    s.push_str("\n\nFor more information, try '--help'.\n");
    fail(&s);
}

fn err_no_usage(msg: &str) -> ! {
    fail(&format!("error: {}\n\nFor more information, try '--help'.\n", msg));
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let la = a.len();
    let lb = b.len();
    if la == 0 && lb == 0 {
        return 1.0;
    }
    if la == 0 || lb == 0 {
        return 0.0;
    }
    let search = (la.max(lb) / 2).saturating_sub(1);
    let mut bflags = vec![false; lb];
    let mut aflags = vec![false; la];
    let mut matches = 0usize;
    for i in 0..la {
        let lo = i.saturating_sub(search);
        let hi = (i + search + 1).min(lb);
        for j in lo..hi {
            if !bflags[j] && a[i] == b[j] {
                aflags[i] = true;
                bflags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..la {
        if aflags[i] {
            while !bflags[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / la as f64 + m / lb as f64 + (m - (t / 2) as f64) / m) / 3.0
}

fn did_you_mean(arg: &str) -> Option<usize> {
    let mut cands: Vec<(f64, usize)> = Vec::new();
    for (i, d) in DEFS.iter().enumerate() {
        let c = jaro(arg, d.long);
        if c > 0.7 {
            cands.push((c, i));
        }
    }
    cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    cands.pop().map(|c| c.1)
}

fn print_help() -> ! {
    let mut o = std::io::stdout();
    let _ = o.write_all(help_text().as_bytes());
    let _ = o.flush();
    std::process::exit(0);
}

fn print_version() -> ! {
    let mut o = std::io::stdout();
    let _ = o.write_all(b"fblog 4.17.0\n");
    let _ = o.flush();
    std::process::exit(0);
}

fn apply_value(args: &mut Args, st: &mut State, idx: usize, val: String) {
    let d = &DEFS[idx];
    if d.kind == Kind::Single && st.counts[idx] > 0 {
        err_with_usage(&format!("the argument '{}' cannot be used multiple times", display(d)), &[], &general_usage());
    }
    st.counts[idx] += 1;
    if !st.used.contains(&idx) {
        st.used.push(idx);
    }
    match d.id {
        "additional-value" => args.additional_values.push(val),
        "config-file" => args.config_file = Some(val),
        "message-key" => args.message_keys.push(val),
        "time-key" => args.time_keys.push(val),
        "level-key" => args.level_keys.push(val),
        "map-level" => match val.split_once('=') {
            Some((a, b)) => args.map_levels.push((a.to_string(), b.to_string())),
            None => err_no_usage(&format!("invalid value '{}' for '{}': missing '='", val, display(d))),
        },
        "excluded-value" => args.excluded_values.push(val),
        "filter" => args.filter = Some(val),
        "main-line-format" => args.main_line_format = Some(val),
        "additional-value-format" => args.additional_value_format = Some(val),
        "context-key" => args.context_key = Some(val),
        "placeholder-format" => args.placeholder_format = Some(val),
        _ => {}
    }
}

fn apply_flag(args: &mut Args, st: &mut State, idx: usize) {
    let d = &DEFS[idx];
    match d.kind {
        Kind::Help => print_help(),
        Kind::Version => print_version(),
        _ => {}
    }
    if st.counts[idx] > 0 {
        err_with_usage(&format!("the argument '{}' cannot be used multiple times", display(d)), &[], &general_usage());
    }
    st.counts[idx] += 1;
    if !st.used.contains(&idx) {
        st.used.push(idx);
    }
    match d.id {
        "print-lua" => args.print_lua = true,
        "dump-all" => args.dump_all = true,
        "with-prefix" => args.with_prefix = true,
        "no-implicit-filter-return-statement" => args.no_implicit_return = true,
        "substitute" => args.substitute = true,
        _ => {}
    }
}

fn missing_value(idx: usize) -> ! {
    err_no_usage(&format!("a value is required for '{}' but none was supplied", display(&DEFS[idx])));
}

fn find_long(name: &str) -> Option<usize> {
    DEFS.iter().position(|d| d.long == name)
}

fn find_short(c: char) -> Option<usize> {
    DEFS.iter().position(|d| d.short == Some(c))
}

fn takes_value(idx: usize) -> bool {
    matches!(DEFS[idx].kind, Kind::Single | Kind::Multi)
}

fn unknown_long(name: &str, st: &State) -> ! {
    let arg = format!("--{}", name);
    match did_you_mean(name) {
        Some(i) => {
            let tip = format!("a similar argument exists: '--{}'", DEFS[i].long);
            err_with_usage(&format!("unexpected argument '{}' found", arg), &[tip], &usage_line(st, Some(i)));
        }
        None => {
            let tip = format!("to pass '{}' as a value, use '-- {}'", arg, arg);
            err_with_usage(&format!("unexpected argument '{}' found", arg), &[tip], &usage_line(st, None));
        }
    }
}

fn unknown_short(c: char) -> ! {
    let arg = format!("-{}", c);
    let tip = format!("to pass '{}' as a value, use '-- {}'", arg, arg);
    err_with_usage(&format!("unexpected argument '{}' found", arg), &[tip], &general_usage());
}

pub fn parse() -> Args {
    let raw: Vec<String> = std::env::args_os().skip(1).map(|s| s.to_string_lossy().into_owned()).collect();
    let mut args = Args { input: "-".to_string(), ..Default::default() };
    let mut st = State { used: Vec::new(), counts: vec![0; DEFS.len()], input_set: false };
    let mut pending: Option<usize> = None;
    let mut trailing = false;
    let mut i = 0;
    while i < raw.len() {
        let tok = raw[i].clone();
        i += 1;
        if trailing {
            if let Some(p) = pending.take() {
                apply_value(&mut args, &mut st, p, tok);
                continue;
            }
            positional(&mut args, &mut st, tok);
            continue;
        }
        if let Some(p) = pending {
            if tok.starts_with('-') && tok != "-" {
                if tok == "--" {
                    missing_value(p);
                }
                if let Some(name) = tok.strip_prefix("--") {
                    let n = name.split_once('=').map(|x| x.0).unwrap_or(name);
                    if find_long(n).is_some() {
                        missing_value(p);
                    }
                    unknown_long(n, &st);
                }
                let c = tok[1..].chars().next().unwrap();
                if find_short(c).is_some() {
                    missing_value(p);
                }
                unknown_short(c);
            }
            pending = None;
            apply_value(&mut args, &mut st, p, tok);
            continue;
        }
        if tok == "--" {
            trailing = true;
            continue;
        }
        if let Some(rest) = tok.strip_prefix("--") {
            let (name, val) = match rest.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (rest, None),
            };
            match find_long(name) {
                None => unknown_long(name, &st),
                Some(idx) => {
                    if takes_value(idx) {
                        match val {
                            Some(v) => apply_value(&mut args, &mut st, idx, v),
                            None => pending = Some(idx),
                        }
                    } else {
                        if let Some(v) = val {
                            let mut s2 = State { used: st.used.clone(), counts: st.counts.clone(), input_set: st.input_set };
                            if !s2.used.contains(&idx) {
                                s2.used.push(idx);
                            }
                            err_with_usage(&format!("unexpected value '{}' for '{}' found; no more were expected", v, display(&DEFS[idx])), &[], &usage_line(&s2, None));
                        }
                        apply_flag(&mut args, &mut st, idx);
                    }
                }
            }
            continue;
        }
        if tok.starts_with('-') && tok.len() > 1 {
            let chars: Vec<char> = tok[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                match find_short(c) {
                    None => unknown_short(c),
                    Some(idx) => {
                        if takes_value(idx) {
                            let mut rest: String = chars[k + 1..].iter().collect();
                            if rest.is_empty() {
                                pending = Some(idx);
                            } else {
                                if let Some(r) = rest.strip_prefix('=') {
                                    rest = r.to_string();
                                }
                                apply_value(&mut args, &mut st, idx, rest);
                            }
                            break;
                        } else {
                            if k + 1 < chars.len() && chars[k + 1] == '=' {
                                let v: String = chars[k + 2..].iter().collect();
                                let mut s2 = State { used: st.used.clone(), counts: st.counts.clone(), input_set: st.input_set };
                                if !s2.used.contains(&idx) {
                                    s2.used.push(idx);
                                }
                                err_with_usage(&format!("unexpected value '{}' for '-{}' found; no more were expected", v, c), &[], &usage_line(&s2, None));
                            }
                            apply_flag(&mut args, &mut st, idx);
                        }
                    }
                }
                k += 1;
            }
            continue;
        }
        positional(&mut args, &mut st, tok);
    }
    if let Some(p) = pending {
        missing_value(p);
    }
    args
}

fn positional(args: &mut Args, st: &mut State, tok: String) {
    if st.input_set {
        err_with_usage(&format!("unexpected argument '{}' found", tok), &[], &general_usage());
    }
    st.input_set = true;
    args.input = tok;
}
