// Minimal TOML parser sufficient for fblog configuration files.
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub enum TVal {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime(String),
    Array(Vec<(TVal, usize, usize)>),
    Table(TTable),
}

#[derive(Debug, Clone, Default)]
pub struct TTable {
    pub entries: BTreeMap<String, (TVal, usize, usize)>,
    pub defined: bool,
    pub inline: bool,
    pub array_of_tables: bool,
}

#[derive(Debug)]
pub struct TomlError {
    pub msg: String,
    pub start: usize,
    pub end: usize,
}

pub fn format_error(src: &str, e: &TomlError) -> String {
    // compute line/col of start
    let mut line = 1;
    let mut line_start = 0;
    for (i, c) in src.char_indices() {
        if i >= e.start {
            break;
        }
        if c == '\n' {
            line += 1;
            line_start = i + 1;
        }
    }
    let line_end = src[line_start..].find('\n').map(|p| p + line_start).unwrap_or(src.len());
    let line_text = &src[line_start..line_end];
    let col = src[line_start..e.start.min(src.len()).max(line_start)].chars().count() + 1;
    let gutter = line.to_string().len();
    let mut carets = e.end.saturating_sub(e.start).max(1);
    let avail = line_text.chars().count() + 1 - (col - 1).min(line_text.chars().count());
    if carets > avail {
        carets = avail.max(1);
    }
    format!(
        "TOML parse error at line {}, column {}\n{} |\n{} | {}\n{} | {}{}\n{}\n",
        line,
        col,
        " ".repeat(gutter),
        line,
        line_text,
        " ".repeat(gutter),
        " ".repeat(col - 1),
        "^".repeat(carets),
        e.msg
    )
}

struct P<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
}

type R<T> = Result<T, TomlError>;

impl<'a> P<'a> {
    fn err<T>(&self, msg: &str, start: usize, end: usize) -> R<T> {
        Err(TomlError { msg: msg.to_string(), start, end })
    }
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn comment(&mut self) {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                self.i += 1;
            }
        }
    }
    fn ws_comment_newlines(&mut self) {
        loop {
            self.ws();
            self.comment();
            match self.peek() {
                Some(b'\n') => self.i += 1,
                Some(b'\r') if self.s.get(self.i + 1) == Some(&b'\n') => self.i += 2,
                _ => break,
            }
        }
    }
    fn expect_eol(&mut self) -> R<()> {
        self.ws();
        self.comment();
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.i += 1;
                Ok(())
            }
            Some(b'\r') if self.s.get(self.i + 1) == Some(&b'\n') => {
                self.i += 2;
                Ok(())
            }
            Some(c) => {
                let st = self.i;
                let msg = if c == b'=' { "extra `=`, expected nothing".to_string() } else { "expected newline, `#`".to_string() };
                self.err(&msg, st, st + 1)
            }
        }
    }
    fn bare_key(&mut self) -> Option<String> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' {
                self.i += 1;
            } else {
                break;
            }
        }
        if self.i > st {
            Some(self.src[st..self.i].to_string())
        } else {
            None
        }
    }
    fn key_part(&mut self) -> R<String> {
        match self.peek() {
            Some(b'"') => self.basic_string(),
            Some(b'\'') => self.literal_string(),
            _ => match self.bare_key() {
                Some(k) => Ok(k),
                None => {
                    let st = self.i;
                    self.err("invalid key", st, st + 1)
                }
            },
        }
    }
    fn key(&mut self) -> R<(Vec<String>, usize, usize)> {
        let st = self.i;
        let mut parts = vec![self.key_part()?];
        loop {
            let save = self.i;
            self.ws();
            if self.peek() == Some(b'.') {
                self.i += 1;
                self.ws();
                parts.push(self.key_part()?);
            } else {
                self.i = save;
                break;
            }
        }
        Ok((parts, st, self.i))
    }
    fn hex4(&mut self, n: usize) -> R<char> {
        let st = self.i;
        if self.i + n > self.s.len() {
            return self.err("invalid unicode escape", st, st + 1);
        }
        let h = &self.src[self.i..self.i + n];
        let v = u32::from_str_radix(h, 16).map_err(|_| TomlError { msg: "invalid unicode escape".into(), start: st, end: st + n })?;
        self.i += n;
        char::from_u32(v).ok_or(TomlError { msg: "invalid unicode escape".into(), start: st, end: st + n })
    }
    fn basic_string(&mut self) -> R<String> {
        let st = self.i;
        if self.s[self.i..].starts_with(b"\"\"\"") {
            self.i += 3;
            if self.peek() == Some(b'\n') {
                self.i += 1;
            } else if self.s[self.i..].starts_with(b"\r\n") {
                self.i += 2;
            }
            let mut out = String::new();
            loop {
                if self.s[self.i..].starts_with(b"\"\"\"") {
                    self.i += 3;
                    // allow up to two extra quotes
                    let mut extra = 0;
                    while self.peek() == Some(b'"') && extra < 2 {
                        out.push('"');
                        self.i += 1;
                        extra += 1;
                    }
                    return Ok(out);
                }
                match self.peek() {
                    None => return self.err("invalid multiline basic string", st, st + 1),
                    Some(b'\\') => {
                        self.i += 1;
                        match self.peek() {
                            Some(b'\n') | Some(b' ') | Some(b'\t') | Some(b'\r') => {
                                while let Some(c) = self.peek() {
                                    if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                                        self.i += 1;
                                    } else {
                                        break;
                                    }
                                }
                            }
                            _ => out.push(self.escape()?),
                        }
                    }
                    Some(_) => {
                        let c = self.src[self.i..].chars().next().unwrap();
                        out.push(c);
                        self.i += c.len_utf8();
                    }
                }
            }
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None | Some(b'\n') => return self.err("invalid basic string", st, self.i),
                Some(b'"') => {
                    self.i += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.i += 1;
                    out.push(self.escape()?);
                }
                Some(_) => {
                    let c = self.src[self.i..].chars().next().unwrap();
                    out.push(c);
                    self.i += c.len_utf8();
                }
            }
        }
    }
    fn escape(&mut self) -> R<char> {
        let st = self.i;
        let c = match self.peek() {
            Some(c) => c,
            None => return self.err("invalid escape sequence", st, st),
        };
        self.i += 1;
        Ok(match c {
            b'b' => '\u{8}',
            b't' => '\t',
            b'n' => '\n',
            b'f' => '\u{c}',
            b'r' => '\r',
            b'e' => '\u{1b}',
            b'"' => '"',
            b'\\' => '\\',
            b'u' => return self.hex4(4),
            b'U' => return self.hex4(8),
            _ => return self.err("invalid escape sequence", st - 1, st + 1),
        })
    }
    fn literal_string(&mut self) -> R<String> {
        let st = self.i;
        if self.s[self.i..].starts_with(b"'''") {
            self.i += 3;
            if self.peek() == Some(b'\n') {
                self.i += 1;
            } else if self.s[self.i..].starts_with(b"\r\n") {
                self.i += 2;
            }
            let start = self.i;
            loop {
                if self.s[self.i..].starts_with(b"'''") {
                    let mut end = self.i;
                    self.i += 3;
                    let mut extra = 0;
                    while self.peek() == Some(b'\'') && extra < 2 {
                        self.i += 1;
                        end += 1;
                        extra += 1;
                    }
                    return Ok(self.src[start..end].to_string());
                }
                if self.peek().is_none() {
                    return self.err("invalid multiline literal string", st, st + 1);
                }
                self.i += 1;
            }
        }
        self.i += 1;
        let start = self.i;
        loop {
            match self.peek() {
                None | Some(b'\n') => return self.err("invalid literal string", st, self.i),
                Some(b'\'') => {
                    let s = self.src[start..self.i].to_string();
                    self.i += 1;
                    return Ok(s);
                }
                Some(_) => self.i += 1,
            }
        }
    }
    fn value(&mut self) -> R<(TVal, usize, usize)> {
        let st = self.i;
        let v = match self.peek() {
            None | Some(b'\n') | Some(b'\r') | Some(b'#') => return self.err("expected value", st, st + 1),
            Some(b'"') => TVal::Str(self.basic_string()?),
            Some(b'\'') => TVal::Str(self.literal_string()?),
            Some(b'[') => {
                self.i += 1;
                let mut items = Vec::new();
                loop {
                    self.ws_comment_newlines();
                    if self.peek() == Some(b']') {
                        self.i += 1;
                        break;
                    }
                    let item = self.value()?;
                    items.push(item);
                    self.ws_comment_newlines();
                    match self.peek() {
                        Some(b',') => {
                            self.i += 1;
                        }
                        Some(b']') => {
                            self.i += 1;
                            break;
                        }
                        _ => {
                            let p = self.i;
                            return self.err("unclosed array", st, p);
                        }
                    }
                }
                TVal::Array(items)
            }
            Some(b'{') => {
                self.i += 1;
                let mut t = TTable { inline: true, defined: true, ..Default::default() };
                self.ws();
                if self.peek() == Some(b'}') {
                    self.i += 1;
                } else {
                    loop {
                        self.ws();
                        let (k, ks, ke) = self.key()?;
                        self.ws();
                        if self.peek() != Some(b'=') {
                            let p = self.i;
                            return self.err("expected `=`", p, p + 1);
                        }
                        self.i += 1;
                        self.ws();
                        let v = self.value()?;
                        insert_dotted(&mut t, &k, v, ks, ke)?;
                        self.ws();
                        match self.peek() {
                            Some(b',') => {
                                self.i += 1;
                            }
                            Some(b'}') => {
                                self.i += 1;
                                break;
                            }
                            _ => {
                                let p = self.i;
                                return self.err("unclosed inline table", st, p);
                            }
                        }
                    }
                }
                TVal::Table(t)
            }
            _ => {
                // scalar token
                let ts = self.i;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'+' || c == b'.' || c == b':' {
                        self.i += 1;
                    } else if c == b' ' && is_date_prefix(&self.src[ts..self.i]) && self.s.get(self.i + 1).map(|d| d.is_ascii_digit()).unwrap_or(false) {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                let tok = &self.src[ts..self.i];
                if tok.is_empty() {
                    let c = self.src[self.i..].chars().next().unwrap_or(' ');
                    return self.err("invalid string\nexpected `\"`, `'`", ts, ts + c.len_utf8());
                }
                match parse_scalar(tok) {
                    Some(v) => v,
                    None => return self.err("invalid string\nexpected `\"`, `'`", ts, self.i),
                }
            }
        };
        Ok((v, st, self.i))
    }
}

fn is_date_prefix(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() == 10 && b[4] == b'-' && b[7] == b'-' && b.iter().enumerate().all(|(i, c)| i == 4 || i == 7 || c.is_ascii_digit())
}

fn parse_scalar(tok: &str) -> Option<TVal> {
    match tok {
        "true" => return Some(TVal::Bool(true)),
        "false" => return Some(TVal::Bool(false)),
        "inf" | "+inf" => return Some(TVal::Float(f64::INFINITY)),
        "-inf" => return Some(TVal::Float(f64::NEG_INFINITY)),
        "nan" | "+nan" | "-nan" => return Some(TVal::Float(f64::NAN)),
        _ => {}
    }
    let b = tok.as_bytes();
    if b.len() >= 10 && b[0].is_ascii_digit() && (b.get(4) == Some(&b'-') || b.get(2) == Some(&b':')) {
        return Some(TVal::Datetime(tok.to_string()));
    }
    if b.len() >= 5 && b[0].is_ascii_digit() && b.get(2) == Some(&b':') {
        return Some(TVal::Datetime(tok.to_string()));
    }
    let clean: String = tok.chars().filter(|c| *c != '_').collect();
    if tok.contains("__") || tok.starts_with('_') || tok.ends_with('_') {
        return None;
    }
    for (pre, radix) in [("0x", 16), ("0o", 8), ("0b", 2)] {
        if let Some(r) = clean.strip_prefix(pre) {
            return i64::from_str_radix(r, radix).ok().map(TVal::Int);
        }
    }
    let digits = clean.trim_start_matches(['+', '-']);
    if digits.chars().all(|c| c.is_ascii_digit()) && !digits.is_empty() {
        if digits.len() > 1 && digits.starts_with('0') {
            return None;
        }
        return clean.parse::<i64>().ok().map(TVal::Int);
    }
    if clean.chars().all(|c| c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-') {
        if clean.ends_with('.') || clean.starts_with('.') || clean.contains(".e") || clean.contains(".E") {
            return None;
        }
        return clean.parse::<f64>().ok().map(TVal::Float);
    }
    None
}

fn insert_dotted(t: &mut TTable, key: &[String], v: (TVal, usize, usize), ks: usize, ke: usize) -> R<()> {
    if key.len() == 1 {
        if t.entries.contains_key(&key[0]) {
            return Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke });
        }
        t.entries.insert(key[0].clone(), v);
        return Ok(());
    }
    let ent = t.entries.entry(key[0].clone()).or_insert_with(|| (TVal::Table(TTable::default()), ks, ke));
    match &mut ent.0 {
        TVal::Table(sub) if !sub.inline => insert_dotted(sub, &key[1..], v, ks, ke),
        _ => Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke }),
    }
}

fn get_table<'b>(root: &'b mut TTable, path: &[String], ks: usize, ke: usize, header: bool, array: bool) -> R<&'b mut TTable> {
    let mut cur = root;
    for (i, k) in path.iter().enumerate() {
        let last = i + 1 == path.len();
        if last && array {
            let ent = cur.entries.entry(k.clone()).or_insert_with(|| (TVal::Array(Vec::new()), ks, ke));
            match &mut ent.0 {
                TVal::Array(items) => {
                    items.push((TVal::Table(TTable { array_of_tables: true, defined: true, ..Default::default() }), ks, ke));
                    match &mut items.last_mut().unwrap().0 {
                        TVal::Table(t) => return Ok(t),
                        _ => unreachable!(),
                    }
                }
                _ => return Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke }),
            }
        }
        let ent = cur.entries.entry(k.clone()).or_insert_with(|| (TVal::Table(TTable::default()), ks, ke));
        cur = match &mut ent.0 {
            TVal::Table(t) => {
                if last && header {
                    if t.defined || t.inline {
                        return Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke });
                    }
                    t.defined = true;
                }
                t
            }
            TVal::Array(items) => match items.last_mut() {
                Some((TVal::Table(t), _, _)) => t,
                _ => return Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke }),
            },
            _ => return Err(TomlError { msg: "duplicate key".into(), start: ks, end: ke }),
        };
    }
    Ok(cur)
}

pub fn parse(src: &str) -> R<TTable> {
    let mut root = TTable::default();
    let mut p = P { s: src.as_bytes(), src, i: 0 };
    let mut cur_path: Vec<String> = Vec::new();
    let mut cur_array = false;
    loop {
        p.ws_comment_newlines();
        if p.peek().is_none() {
            break;
        }
        if p.peek() == Some(b'[') {
            let array = p.s.get(p.i + 1) == Some(&b'[');
            p.i += if array { 2 } else { 1 };
            p.ws();
            let (k, ks, ke) = p.key()?;
            p.ws();
            if array {
                if !p.s[p.i..].starts_with(b"]]") {
                    let q = p.i;
                    return p.err("invalid table header\nexpected `.`, `]]`", q, q + 1);
                }
                p.i += 2;
            } else {
                if p.peek() != Some(b']') {
                    let q = p.i;
                    return p.err("invalid table header\nexpected `.`, `]`", q, q + 1);
                }
                p.i += 1;
            }
            get_table(&mut root, &k, ks, ke, true, array)?;
            cur_path = k;
            cur_array = array;
            p.expect_eol()?;
            continue;
        }
        let (k, ks, ke) = p.key()?;
        p.ws();
        if p.peek() != Some(b'=') {
            let q = p.i;
            return p.err("expected `.`, `=`", q, q + 1);
        }
        p.i += 1;
        p.ws();
        let v = p.value()?;
        {
            let table = if cur_path.is_empty() {
                &mut root
            } else {
                let mut t = &mut root;
                for (i, seg) in cur_path.iter().enumerate() {
                    let last = i + 1 == cur_path.len();
                    let ent = t.entries.get_mut(seg).unwrap();
                    t = match &mut ent.0 {
                        TVal::Table(tt) => tt,
                        TVal::Array(items) => match &mut items.last_mut().unwrap().0 {
                            TVal::Table(tt) => tt,
                            _ => unreachable!(),
                        },
                        _ => unreachable!(),
                    };
                    let _ = (last, cur_array);
                }
                t
            };
            insert_dotted(table, &k, v, ks, ke)?;
        }
        p.expect_eol()?;
    }
    Ok(root)
}

pub fn describe(v: &TVal) -> String {
    match v {
        TVal::Str(s) => format!("string {:?}", s),
        TVal::Int(i) => format!("integer `{}`", i),
        TVal::Float(f) => format!("floating point `{}`", fmt_f(*f)),
        TVal::Bool(b) => format!("boolean `{}`", b),
        TVal::Datetime(_) => "datetime".to_string(),
        TVal::Array(_) => "sequence".to_string(),
        TVal::Table(_) => "map".to_string(),
    }
}

fn fmt_f(f: f64) -> String {
    let s = format!("{}", f);
    if f.is_finite() && !s.contains('.') && !s.contains('e') {
        format!("{}.0", s)
    } else {
        s
    }
}
