// fblog-compatible json log viewer
mod cli;
mod hbs;
mod json;
mod lua;
mod timefmt;
mod toml;

use json::{Map, Value};
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};

const DEFAULT_MAIN_LINE_FORMAT: &str = "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}";
const DEFAULT_ADDITIONAL_VALUE_FORMAT: &str = "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}";

struct Config {
    message_keys: Vec<String>,
    time_keys: Vec<String>,
    dump_all_exclude: Vec<String>,
    always_print_fields: Vec<String>,
    level_keys: Vec<String>,
    main_line_format: String,
    additional_value_format: String,
    level_map: Vec<(String, String)>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            message_keys: vec!["short_message".into(), "msg".into(), "message".into()],
            time_keys: vec!["timestamp".into(), "time".into(), "@timestamp".into()],
            dump_all_exclude: vec![],
            always_print_fields: vec![],
            level_keys: vec!["level".into(), "severity".into(), "log.level".into(), "loglevel".into()],
            main_line_format: DEFAULT_MAIN_LINE_FORMAT.into(),
            additional_value_format: DEFAULT_ADDITIONAL_VALUE_FORMAT.into(),
            level_map: vec![],
        }
    }
}

pub fn panic_exit(location: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    lua::flush_stdout();
    let s = format!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        std::process::id(),
        location,
        msg
    );
    let _ = std::io::stderr().write_all(s.as_bytes());
    std::process::exit(101);
}

fn out_line(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let r = lock.write_all(s.as_bytes()).and_then(|_| lock.write_all(b"\n"));
    if r.is_err() {
        drop(lock);
        std::process::exit(14);
    }
}

fn type_err(src: &str, v: &toml::TVal, s: usize, e: usize, expected: &str) -> String {
    let te = toml::TomlError { msg: format!("invalid type: {}, expected {}", toml::describe(v), expected), start: s, end: e };
    toml::format_error(src, &te)
}

fn parse_config(src: &str) -> Result<Config, String> {
    let root = toml::parse(src).map_err(|e| toml::format_error(src, &e))?;
    let mut cfg = Config::default();
    let str_list = |name: &str| -> Result<Option<Vec<String>>, String> {
        match root.entries.get(name) {
            None => Ok(None),
            Some((toml::TVal::Array(items), _, _)) => {
                let mut out = Vec::new();
                for (it, s, e) in items {
                    match it {
                        toml::TVal::Str(x) => out.push(x.clone()),
                        other => return Err(type_err(src, other, *s, *e, "a string")),
                    }
                }
                Ok(Some(out))
            }
            Some((other, s, e)) => Err(type_err(src, other, *s, *e, "a sequence")),
        }
    };
    let string = |name: &str| -> Result<Option<String>, String> {
        match root.entries.get(name) {
            None => Ok(None),
            Some((toml::TVal::Str(x), _, _)) => Ok(Some(x.clone())),
            Some((other, s, e)) => Err(type_err(src, other, *s, *e, "a string")),
        }
    };
    if let Some(v) = str_list("message_keys")? {
        cfg.message_keys = v;
    }
    if let Some(v) = str_list("time_keys")? {
        cfg.time_keys = v;
    }
    if let Some(v) = str_list("dump_all_exclude")? {
        cfg.dump_all_exclude = v;
    }
    if let Some(v) = str_list("always_print_fields")? {
        cfg.always_print_fields = v;
    }
    if let Some(v) = str_list("level_keys")? {
        cfg.level_keys = v;
    }
    if let Some(v) = string("main_line_format")? {
        cfg.main_line_format = v;
    }
    if let Some(v) = string("additional_value_format")? {
        cfg.additional_value_format = v;
    }
    match root.entries.get("level_map") {
        None => {}
        Some((toml::TVal::Table(t), _, _)) => {
            for (k, (v, s, e)) in &t.entries {
                match v {
                    toml::TVal::Str(x) => cfg.level_map.push((k.clone(), x.clone())),
                    other => return Err(type_err(src, other, *s, *e, "a string")),
                }
            }
        }
        Some((other, s, e)) => return Err(type_err(src, other, *s, *e, "a map")),
    }
    Ok(cfg)
}

fn default_config_path() -> Option<std::path::PathBuf> {
    let xdg = std::env::var_os("XDG_CONFIG_HOME").map(std::path::PathBuf::from).filter(|p| p.is_absolute());
    let dir = match xdg {
        Some(d) => d,
        None => {
            let home = std::env::var_os("HOME").filter(|h| !h.is_empty())?;
            std::path::PathBuf::from(home).join(".config")
        }
    };
    Some(dir.join("fblog.toml"))
}

fn load_config(args: &cli::Args) -> Config {
    if let Some(path) = &args.config_file {
        let src = match std::fs::read(path) {
            Ok(b) => b,
            Err(_) => panic_exit("src/main.rs:35:50", "Could not load config file."),
        };
        let src = String::from_utf8_lossy(&src).into_owned();
        match parse_config(&src) {
            Ok(c) => c,
            Err(e) => {
                let _ = std::io::stderr().write_all(format!("Could not parse config file: {}\n", e).as_bytes());
                panic_exit("src/main.rs:35:50", "Could not load config file.");
            }
        }
    } else {
        let path = match default_config_path() {
            Some(p) => p,
            None => return Config::default(),
        };
        match std::fs::read(&path) {
            Ok(b) => {
                let src = String::from_utf8_lossy(&b).into_owned();
                match parse_config(&src) {
                    Ok(c) => c,
                    Err(e) => panic_exit("src/config.rs:84:17", &format!("Could not parse config file: {}", e)),
                }
            }
            Err(_) => Config::default(),
        }
    }
}

struct Settings {
    message_keys: Vec<String>,
    time_keys: Vec<String>,
    level_keys: Vec<String>,
    level_map: HashMap<String, String>,
    additional_values: Vec<String>,
    excluded: Vec<String>,
    dump_all: bool,
    with_prefix: bool,
    print_lua: bool,
    filter: Option<String>,
    implicit_return: bool,
    substitution: Option<(String, String, String)>,
}

fn value_to_string(v: &Value) -> Option<String> {
    match v {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

fn first_key(map: &Map, keys: &[String]) -> Option<String> {
    for k in keys {
        if let Some(v) = map.get(k) {
            if let Some(s) = value_to_string(v) {
                return Some(s);
            }
        }
    }
    None
}

// ---------- flatten ----------

struct Flat {
    items: Vec<(String, String)>,
    index: HashMap<String, usize>,
}

impl Flat {
    fn add(&mut self, k: String, v: String) {
        if let Some(&i) = self.index.get(&k) {
            self.items[i].1 = v;
        } else {
            self.index.insert(k.clone(), self.items.len());
            self.items.push((k, v));
        }
    }
}

fn flatten_obj(prefix: Option<&str>, map: &Map, out: &mut Flat) {
    for (k, v) in map {
        let name = match prefix {
            Some(p) => format!("{} > {}", p, k),
            None => k.clone(),
        };
        flatten_val(name, v, out);
    }
}

fn flatten_val(name: String, v: &Value, out: &mut Flat) {
    match v {
        Value::String(s) => out.add(name, s.clone()),
        Value::Null => {}
        Value::Bool(_) | Value::Number(_) => out.add(name, value_to_string(v).unwrap()),
        Value::Object(m) => flatten_obj(Some(&name), m, out),
        Value::Array(a) => flatten_arr(&name, a, 0, out),
    }
}

fn flatten_arr(name: &str, a: &[Value], base: usize, out: &mut Flat) {
    for (i, x) in a.iter().enumerate() {
        let key = format!("{}[{}]", name, i + base);
        match x {
            Value::Object(m) => flatten_obj(Some(&key), m, out),
            Value::Array(b) => flatten_arr(&key, b, 1, out),
            other => out.add(key, json::to_json_string(other)),
        }
    }
}

// ---------- lua ----------

fn lua_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '\\' => o.push_str("\\\\"),
            '"' => o.push_str("\\\""),
            '\'' => o.push_str("\\'"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c => o.push(c),
        }
    }
    o
}

fn lua_key(k: &str) -> String {
    k.chars().map(|c| if c.is_ascii_alphabetic() || c == '_' { c } else { '_' }).collect()
}

fn lua_value(v: &Value, in_array: bool) -> String {
    match v {
        Value::String(s) => format!("\"{}\"", lua_escape(s)),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "\"unsupported\"".to_string(),
        Value::Object(m) => {
            if in_array {
                return "\"unsupported\"".to_string();
            }
            let parts: Vec<String> = m.iter().map(|(k, v)| format!("{} = {}", lua_key(k), lua_value(v, false))).collect();
            format!("{{{}}}", parts.join(","))
        }
        Value::Array(a) => {
            if in_array {
                return "\"unsupported\"".to_string();
            }
            let parts: Vec<String> = a.iter().map(|x| lua_value(x, true)).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn apply_filter(map: &Map, st: &Settings, filter: &str) -> Result<bool, String> {
    let lines: Vec<String> = map.iter().map(|(k, v)| format!("{} = {}", lua_key(k), lua_value(v, false))).collect();
    let script = lines.join("\n");
    if st.print_lua {
        out_line(&script);
    }
    let mut it = lua::new_state();
    if let Err(e) = lua::exec(&mut it, script.as_bytes(), "src/filter.rs:20") {
        return Err(lua::format_error(&mut it, &e));
    }
    let (chunk, name) = if st.implicit_return { (format!("return {};", filter), "src/filter.rs:23") } else { (filter.to_string(), "src/filter.rs:25") };
    match lua::exec(&mut it, chunk.as_bytes(), name) {
        Ok(v) => Ok(v.first().map(|x| x.truthy()).unwrap_or(false)),
        Err(e) => Err(lua::format_error(&mut it, &e)),
    }
}

// ---------- substitution ----------

fn dim(s: &str) -> String {
    format!("\x1b[2m{}\x1b[0m", s)
}

fn fmt_ctx_value(v: &Value) -> String {
    match v {
        Value::String(s) => format!("\x1b[1;33m{}\x1b[0m", s),
        Value::Number(n) => format!("\x1b[1;36m{}\x1b[0m", n.to_string()),
        Value::Bool(true) => "\x1b[1;32mtrue\x1b[0m".to_string(),
        Value::Bool(false) => "\x1b[1;31mfalse\x1b[0m".to_string(),
        Value::Null => "\x1b[1mnull\x1b[0m".to_string(),
        Value::Array(a) => {
            let parts: Vec<String> = a.iter().map(fmt_ctx_value).collect();
            format!("{}{}{}", dim("["), parts.join(&dim(", ")), dim("]"))
        }
        Value::Object(m) => {
            let parts: Vec<String> = m.iter().map(|(k, v)| format!("\x1b[35m{}\x1b[0m{}{}", k, dim(": "), fmt_ctx_value(v))).collect();
            format!("{}{}{}", dim("{"), parts.join(&dim(", ")), dim("}"))
        }
    }
}

fn is_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

fn substitute(msg: &str, ctx: &Value, prefix: &str, suffix: &str) -> String {
    let b = msg.as_bytes();
    let pb = prefix.as_bytes();
    let sb = suffix.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    let mut last = 0;
    while i <= b.len() {
        let mut matched = None;
        if b[i..].starts_with(pb) {
            let ks = i + pb.len();
            let mut e = ks;
            while e < b.len() && is_key_char(b[e]) {
                e += 1;
            }
            let mut k = e;
            while k > ks {
                if b[k..].starts_with(sb) {
                    matched = Some((ks, k, k + sb.len()));
                    break;
                }
                k -= 1;
            }
        }
        match matched {
            Some((ks, ke, end)) => {
                out.push_str(&msg[last..i]);
                let key = &msg[ks..ke];
                let found = match ctx {
                    Value::Object(m) => m.get(key),
                    Value::Array(a) => key.parse::<usize>().ok().and_then(|idx| a.get(idx)),
                    _ => None,
                };
                match found {
                    Some(v) => out.push_str(&fmt_ctx_value(v)),
                    None => out.push_str(&format!("{}\x1b[1;31m{}\x1b[0m{}", dim(prefix), key, dim(suffix))),
                }
                i = end;
                last = end;
                if end == ks && end >= b.len() {
                    break;
                }
            }
            None => {
                if i >= b.len() {
                    break;
                }
                i += 1;
                while i < b.len() && !msg.is_char_boundary(i) {
                    i += 1;
                }
            }
        }
    }
    out.push_str(&msg[last.min(msg.len())..]);
    out
}

// ---------- line processing ----------

struct App {
    st: Settings,
    main_tpl: hbs::Template,
    add_tpl: hbs::Template,
}

fn handle_render_panic(p: &str) -> ! {
    let (loc, msg) = p.split_once(":\n").unwrap_or(("src/template.rs:1:1", p));
    panic_exit(loc, msg);
}

impl App {
    fn process_line(&self, line: &str) {
        let (prefix, json_part) = if self.st.with_prefix {
            match line.find('{') {
                Some(idx) => (Some(line[..idx].trim().to_string()), &line[idx..]),
                None => (None, line),
            }
        } else {
            (None, line)
        };
        match json::parse(json_part) {
            Ok(Value::Object(map)) => self.process_json(map, prefix),
            _ => out_line(&format!("\x1b[1;38;2;255;135;22m??? >\x1b[0m {}", line)),
        }
    }

    fn process_json(&self, map: Map, prefix: Option<String>) {
        if let Some(f) = &self.st.filter {
            match apply_filter(&map, &self.st, f) {
                Ok(true) => {}
                Ok(false) => return,
                Err(e) => {
                    let _ = std::io::stdout().flush();
                    let _ = std::io::stderr().write_all(format!("\x1b[31mFailed to apply filter expression\x1b[0m: '{}'\n", e).as_bytes());
                    return;
                }
            }
        }
        let ts = match first_key(&map, &self.st.time_keys) {
            Some(t) => timefmt::convert_timestamp(&t),
            None => String::new(),
        };
        let level = match first_key(&map, &self.st.level_keys) {
            Some(l) => match self.st.level_map.get(&l) {
                Some(m) => m.clone(),
                None => l,
            },
            None => "unknown".to_string(),
        };
        let mut message = first_key(&map, &self.st.message_keys).unwrap_or_default();
        if let Some((ck, pre, suf)) = &self.st.substitution {
            if let Some(ctx) = map.get(ck) {
                message = substitute(&message, ctx, pre, suf);
            }
        }
        let mut data = map.clone();
        data.insert("fblog_timestamp".into(), Value::String(ts));
        data.insert("fblog_level".into(), Value::String(level));
        data.insert("fblog_message".into(), Value::String(message));
        data.insert("fblog_prefix".into(), Value::String(prefix.unwrap_or_default()));
        let data = Value::Object(data);
        match hbs::render(&self.main_tpl, &data) {
            Ok(s) => out_line(&s),
            Err(hbs::RenderFail::Error(e)) => out_line(&format!("\x1b[1;31m??? >\x1b[0m Failed to process line: {}", e.to_string("main_line"))),
            Err(hbs::RenderFail::Panic(p)) => handle_render_panic(&p),
        }
        let mut flat = Flat { items: Vec::new(), index: HashMap::new() };
        flatten_obj(None, &map, &mut flat);
        if self.st.dump_all {
            for (k, v) in &flat.items {
                if !self.st.excluded.contains(k) {
                    self.print_additional(k, v);
                }
            }
        } else {
            for key in &self.st.additional_values {
                let p1 = format!("{} > ", key);
                let p2 = format!("{}[", key);
                for (k, v) in &flat.items {
                    if k == key || k.starts_with(&p1) || k.starts_with(&p2) {
                        self.print_additional(k, v);
                    }
                }
            }
        }
    }

    fn print_additional(&self, k: &str, v: &str) {
        let mut m = Map::new();
        m.insert("key".into(), Value::String(k.to_string()));
        m.insert("value".into(), Value::String(v.to_string()));
        match hbs::render(&self.add_tpl, &Value::Object(m)) {
            Ok(s) => out_line(&s),
            Err(hbs::RenderFail::Error(e)) => out_line(&format!("\x1b[1;31m   ??? >\x1b[0m Failed to process additional value: {}", e.to_string("additional_value"))),
            Err(hbs::RenderFail::Panic(p)) => handle_render_panic(&p),
        }
    }
}

fn run() {
    let args = cli::parse();
    let cfg = load_config(&args);

    let mut message_keys = args.message_keys.clone();
    message_keys.extend(cfg.message_keys.iter().cloned());
    let mut time_keys = args.time_keys.clone();
    time_keys.extend(cfg.time_keys.iter().cloned());
    let mut level_keys = args.level_keys.clone();
    level_keys.extend(cfg.level_keys.iter().cloned());
    let mut level_map: HashMap<String, String> = HashMap::new();
    for (k, v) in &cfg.level_map {
        level_map.insert(k.clone(), v.clone());
    }
    for (k, v) in &args.map_levels {
        level_map.insert(k.clone(), v.clone());
    }
    let mut additional_values = cfg.always_print_fields.clone();
    additional_values.extend(args.additional_values.iter().cloned());
    let mut excluded = cfg.dump_all_exclude.clone();
    excluded.extend(args.excluded_values.iter().cloned());
    let dump_all = args.dump_all || !args.excluded_values.is_empty();

    let substitution_enabled = args.substitute || args.context_key.is_some() || args.placeholder_format.is_some();
    let mut substitution = None;
    {
        let fmt = args.placeholder_format.clone().unwrap_or_else(|| "{key}".to_string());
        let parts = match fmt.split_once("key") {
            Some((a, b)) => Some((a.to_string(), b.to_string())),
            None => None,
        };
        if args.placeholder_format.is_some() && parts.is_none() {
            panic_exit("src/main.rs:68:23", "Invalid placeholder format: The identifier `key` is missing");
        }
        if substitution_enabled {
            let (a, b) = parts.unwrap();
            substitution = Some((args.context_key.clone().unwrap_or_else(|| "context".to_string()), a, b));
        }
    }

    let st = Settings {
        message_keys,
        time_keys,
        level_keys,
        level_map,
        additional_values,
        excluded,
        dump_all,
        with_prefix: args.with_prefix,
        print_lua: args.print_lua,
        filter: args.filter.clone(),
        implicit_return: !args.no_implicit_return,
        substitution,
    };

    let reader: Box<dyn Read> = if args.input == "-" {
        Box::new(std::io::stdin())
    } else {
        match std::fs::File::open(&args.input) {
            Ok(f) => Box::new(f),
            Err(_) => panic_exit("src/main.rs:105:68", &format!("Can't open file: {}", args.input)),
        }
    };

    let main_src = args.main_line_format.clone().unwrap_or_else(|| cfg.main_line_format.clone());
    let add_src = args.additional_value_format.clone().unwrap_or_else(|| cfg.additional_value_format.clone());
    let main_tpl = match hbs::compile(&main_src, "main_line") {
        Ok(t) => t,
        Err(e) => panic_exit("src/template.rs:96:65", &hbs::format_template_error(&e, "main_line", &main_src)),
    };
    let add_tpl = match hbs::compile(&add_src, "additional_value") {
        Ok(t) => t,
        Err(e) => panic_exit("src/template.rs:99:10", &hbs::format_template_error(&e, "additional_value", &add_src)),
    };

    let app = App { st, main_tpl, add_tpl };
    let mut br = BufReader::new(reader);
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        match br.read_until(b'\n', &mut buf) {
            Ok(0) => break,
            Ok(_) => {
                if buf.last() == Some(&b'\n') {
                    buf.pop();
                    if buf.last() == Some(&b'\r') {
                        buf.pop();
                    }
                }
                match std::str::from_utf8(&buf) {
                    Ok(line) => app.process_line(line),
                    Err(_) => out_line("\x1b[1;31m??? >\x1b[0m Could not read line: stream did not contain valid UTF-8"),
                }
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                out_line(&format!("\x1b[1;31m??? >\x1b[0m Could not read line: {}", e));
            }
        }
    }
    lua::flush_stdout();
}

fn main() {
    lua::stdlib::seed_random();
    let child = std::thread::Builder::new().stack_size(1 << 30).spawn(run).expect("thread");
    let r = child.join();
    lua::flush_stdout();
    if r.is_err() {
        std::process::exit(101);
    }
}
