// Coroutines implemented with OS threads and strict hand-off (only one thread runs at a time).
use std::cell::RefCell;
use std::rc::Rc;
use std::sync::mpsc::{channel, Receiver, Sender};

use super::args::*;
use super::interp::{Interp, LResult};
use super::stdlib::{mk_native, reg};
use super::value::*;

pub enum Msg {
    Resume(Vec<Val>),
    Kill,
    Yield(Vec<Val>),
    Done(Result<Vec<Val>, LuaError>),
}

#[derive(Clone, Copy, PartialEq)]
pub enum Status {
    Suspended,
    Running,
    Normal,
    Dead,
}

pub struct CoInner {
    pub status: Status,
    pub func: Option<Val>,
    pub to_co: Option<Sender<SendBox<Msg>>>,
    pub from_co: Option<Receiver<SendBox<Msg>>>,
    pub handle: Option<std::thread::JoinHandle<()>>,
    pub is_main: bool,
    pub error: Option<Val>,
}

pub struct Coro {
    pub inner: RefCell<CoInner>,
}

/// channel ends used by a running coroutine to talk to its resumer
pub struct CoCtx {
    pub rx: Receiver<SendBox<Msg>>,
    pub tx: Sender<SendBox<Msg>>,
    pub me: std::rc::Weak<Coro>,
}

impl Coro {
    pub fn new(func: Val) -> Rc<Coro> {
        Rc::new(Coro { inner: RefCell::new(CoInner { status: Status::Suspended, func: Some(func), to_co: None, from_co: None, handle: None, is_main: false, error: None }) })
    }
    pub fn new_main() -> Rc<Coro> {
        Rc::new(Coro { inner: RefCell::new(CoInner { status: Status::Running, func: None, to_co: None, from_co: None, handle: None, is_main: true, error: None }) })
    }
}

fn kill(inner: &mut CoInner) {
    if let Some(tx) = inner.to_co.take() {
        let _ = tx.send(SendBox(Msg::Kill));
        drop(tx);
        if let Some(rx) = inner.from_co.take() {
            loop {
                match rx.recv() {
                    Ok(SendBox(Msg::Done(r))) => {
                        drop(r);
                        break;
                    }
                    Ok(SendBox(other)) => drop(other),
                    Err(_) => break,
                }
            }
        }
    }
    if let Some(h) = inner.handle.take() {
        let _ = h.join();
    }
}

impl Drop for Coro {
    fn drop(&mut self) {
        let inner = self.inner.get_mut();
        kill(inner);
    }
}

fn status_str(it: &Interp, co: &Rc<Coro>) -> &'static str {
    if let Some(cur) = &it.current_co {
        if Rc::ptr_eq(cur, co) {
            return "running";
        }
    }
    match co.inner.borrow().status {
        Status::Suspended => "suspended",
        Status::Running => "running",
        Status::Normal => "normal",
        Status::Dead => "dead",
    }
}

/// resume a coroutine: Ok(Ok(values)) on yield/return, Ok(Err(errvalue)) on error
pub fn resume(it: &mut Interp, co: &Rc<Coro>, args: Vec<Val>) -> LResult<Result<Vec<Val>, Val>> {
    {
        let st = status_str(it, co);
        if st == "dead" {
            return Ok(Err(Val::str("cannot resume dead coroutine")));
        }
        if st != "suspended" {
            return Ok(Err(Val::str("cannot resume non-suspended coroutine")));
        }
    }
    if it.c_depth >= 195 {
        return Ok(Err(Val::str("C stack overflow")));
    }
    let (tx, rx) = {
        let mut inner = co.inner.borrow_mut();
        if inner.handle.is_none() {
            let (tx1, rx1) = channel::<SendBox<Msg>>();
            let (tx2, rx2) = channel::<SendBox<Msg>>();
            let func = inner.func.take().unwrap_or(Val::Nil);
            let payload = SendBox((func, it.globals.clone(), it.string_mt.clone(), it.loaded.clone(), rx1, tx2, Rc::downgrade(co), it.c_depth));
            let h = std::thread::Builder::new().stack_size(256 << 20).spawn(move || {
                let p = payload;
                let (func, globals, smt, loaded, rx, tx, me, cdepth) = p.0;
                let first = match rx.recv() {
                    Ok(SendBox(Msg::Resume(a))) => a,
                    _ => {
                        drop((func, globals, smt, loaded, me));
                        let _ = tx.send(SendBox(Msg::Done(Err(LuaError::Killed))));
                        return;
                    }
