                it2.globals = globals;
                it2.string_mt = smt;
                it2.loaded = loaded;
                it2.pcall_depth = 1;
                it2.c_depth = cdepth + 1;
                it2.current_co = me.upgrade();
                it2.co_ctx = Some(CoCtx { rx, tx: tx.clone(), me });
                let r = it2.call(&func, first, None);
                drop(func);
                it2.current_co = None;
                let ctx = it2.co_ctx.take();
                drop(it2);
                drop(ctx);
                let _ = tx.send(SendBox(Msg::Done(r)));
            });
            match h {
                Ok(h) => {
                    inner.handle = Some(h);
                    inner.to_co = Some(tx1);
                    inner.from_co = Some(rx2);
                }
                Err(_) => {
                    inner.status = Status::Dead;
                    return Ok(Err(Val::str("too many C levels")));
                }
            }
        }
        inner.status = Status::Running;
        (inner.to_co.clone().unwrap(), inner.from_co.take().unwrap())
    };
    let prev = it.current_co.clone();
    if let Some(p) = &prev {
        p.inner.borrow_mut().status = Status::Normal;
    }
    it.current_co = Some(co.clone());
    let _ = tx.send(SendBox(Msg::Resume(args)));
    let msg = rx.recv();
    it.current_co = prev.clone();
    if let Some(p) = &prev {
        p.inner.borrow_mut().status = Status::Running;
    }
