                    inner.error = Some(value.clone());
                    Ok(Err(value))
                }
                Err(LuaError::Syntax { msg, .. }) => Ok(Err(Val::str(&msg))),
                Err(LuaError::Killed) => Err(LuaError::Killed),
            }
        }
        _ => {
            inner.status = Status::Dead;
            Ok(Err(Val::str("cannot resume dead coroutine")))
        }
    }
}

