atoms = ["1", "-1", "2.5", "3", "'10'", "'abc'", "''", "true", "nil", "x", "y", "t", "t.a", "t.b", "t[1]", "s", "n", "f", "g.h", "u", "t.nest.v", "#s", "#t", "s:upper()", "s:sub(2)", "(s .. 'z')", "tostring(n)"]
ops = ["+", "-", "*", "/", "//", "%", "..", "==", "<", "<=", ">", "and", "or", "&"]
def expr(d=0):
    r = random.random()
    if d > 2 or r < 0.4:
        return random.choice(atoms)
    if r < 0.5:
        return random.choice(["-", "not ", "#"]) + "(" + expr(d+1) + ")"
    if r < 0.6:
        f = random.choice(["f", "t.a", "g.h", "s.len", "string.rep", "math.max", "x", "u.v", "t:m", "s:rep"])
        if f in ("t:m", "s:rep"):
            return f + "(" + expr(d+1) + ")"
        return f + "(" + expr(d+1) + ")"
    return "(" + expr(d+1) + " " + random.choice(ops) + " " + expr(d+1) + ")"
pre = "local x = 5 local y local s = 'hello' t = {a = 1, 'one', nest = {v = 2}} n = 3.5 f = function(a) return a end g = {}"
with open("/tmp/cmp/luafuzz2.txt", "w") as f:
    for i in range(120):
        e = expr()
        mode = random.random()
        if mode < 0.5:
            code = pre + " print(pcall(function() return " + e + " end))"
        else:
            code = pre + " return " + e
        f.write("--no-implicit-filter-return-statement -f " + shlex.quote(code) + " /tmp/cmp/one.log\n")
EOF
for seed in 1 2 3 4 5; do python3 /tmp/cmp/luafuzz2.py $seed; python3 /tmp/cmp/cmp.py /tmp/cmp/luafuzz2.txt > /tmp/cmp/outlg$seed.txt 2>&1; tail -1 /tmp/cmp/outlg$seed.txt; done"}

